INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a3948f4-9eb0-4990-80c9-c4641ef5a2c8', '奉酬李中丞洪湖州西亭即事見寄兼呈吳馮處士時中丞量移湖州長史', '奉酬李中丞洪湖州西亭即事见寄兼呈吳馮处士时中丞量移湖州长史', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["愛君溪上住，遲月開前扃。","山火照書卷，野風吹酒瓶。","爲誰留此物，意在眼中青。","樵子逗煙墅，漁翁宿沙汀。","主人非楚客，莫謾譏獨醒。","宿昔邢城功，道高心已冥。","貪將到處士，放醉烏家亭。"]', '["愛君溪上住，遲月开前扃。","山火照书卷，野风吹酒瓶。","爲誰留此物，意在眼中青。","樵子逗煙墅，漁翁宿沙汀。","主人非楚客，莫謾譏独醒。","宿昔邢城功，道高心已冥。","貪將到处士，放醉烏家亭。"]', '诗', 'shi', '', NULL, '奉酬李中丞洪湖州西亭即事見寄兼呈吳馮處士時中丞量移湖州長史 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7876c6c9-3d24-4f17-85eb-03d786a28e18', '苕溪草堂自大曆三年夏新營洎秋及春彌覺境勝因紀其事簡潘丞述湯評事衡四十三韻', '苕溪草堂自大曆三年夏新營洎秋及春彌覺境勝因紀其事簡潘丞述湯評事衡四十三韻', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["萬慮皆可遺，愛山情不易。","自從東溪住，始與人羣隔。","應物非宿心，遺身是吾策。","先民崆峒子，淪景事金液。","綺里猶近名，於陵未泯跡。","吾師逆流教，禪隱殊古昔。","洗足臨潺湲，銷聲寄松柏。","緗荷採堪服，柔草持可席。","道心制野猨，法語授幽客。","境淨萬象真，寄目皆有益。","原上無情花，山中聽經石。","竹生自蕭散，雲性常潔白。","却見羇世人，遠高摩霄翮。","達賢觀此意，煩想遂冰蘖。","伊予戰苦勝，覽境情不溺。","智以動念昏，功由無心積。","形骸爾何有，生死誰所戚。","爲與勝悟冥，不憂頹齡迫。","春風自駘蕩，禪地常闃寂。","擲札成柳枝，溉瓶養泉脉。","道人知止足，盥漱聊自適。","學外見古賢，頗令我心惕。","眇綿雲官世，夢幻羽陵籍。","鬼籙徒相矜，九原誰家宅。","俗情對淺近，至理昧堯跖。","蹈善嗟沈冥，履仁傷堙阨。","匠心聖亦尤，攻異天見責。","試以慧眼觀，斯言諒可覿。","外事非吾道，忘緣倦所歷。","中宵廢耳目，形靜神不役。","色天夜清迥，花漏時滴瀝。","東風吹杉梧，幽月到石壁。","此中一悟心，可與千載敵。","故交徒好我，筐中無咫尺。","潘生入空門，祖師傳祕賾。","湯子自天德，精詣功不僻。","放世與成名，兩圖在所擇。","吾高鴟夷子，身退無瑕摘。","吾嘉魯仲連，功成棄珪璧。","二賢兼彼才，晚節何感激。","不然作山計，改服我下澤。","君隳元亮冠，我脫潛師屐。","倚臥高松根，共逃金閨籍。"]', '["万慮皆可遺，愛山情不易。","自從东溪住，始與人羣隔。","應物非宿心，遺身是吾策。","先民崆峒子，淪景事金液。","綺里猶近名，於陵未泯跡。","吾師逆流教，禪隐殊古昔。","洗足臨潺湲，銷声寄松柏。","緗荷採堪服，柔草持可席。","道心制野猨，法語授幽客。","境淨万象真，寄目皆有益。","原上無情花，山中听經石。","竹生自蕭散，云性常潔白。","却见羇世人，远高摩霄翮。","達賢观此意，煩想遂冰蘖。","伊予戰苦勝，覽境情不溺。","智以动念昏，功由無心積。","形骸爾何有，生死誰所戚。","爲與勝悟冥，不憂頹齡迫。","春风自駘蕩，禪地常闃寂。","擲札成柳枝，溉瓶養泉脉。","道人知止足，盥漱聊自適。","学外见古賢，頗令我心惕。","眇綿云官世，梦幻羽陵籍。","鬼籙徒相矜，九原誰家宅。","俗情对淺近，至理昧堯跖。","蹈善嗟沈冥，履仁傷堙阨。","匠心聖亦尤，攻異天见責。","試以慧眼观，斯言諒可覿。","外事非吾道，忘緣倦所歷。","中宵廢耳目，形静神不役。","色天夜清迥，花漏时滴瀝。","东风吹杉梧，幽月到石壁。","此中一悟心，可與千載敵。","故交徒好我，筐中無咫尺。","潘生入空门，祖師傳祕賾。","湯子自天德，精詣功不僻。","放世與成名，兩圖在所擇。","吾高鴟夷子，身退無瑕摘。","吾嘉魯仲連，功成棄珪璧。","二賢兼彼才，晚節何感激。","不然作山計，改服我下澤。","君隳元亮冠，我脫潛師屐。","倚臥高松根，共逃金閨籍。"]', '诗', 'shi', '', NULL, '苕溪草堂自大曆三年夏新營洎秋及春彌覺境勝因紀其事簡潘丞述湯評事衡四十三韻 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac6a53b-f083-4371-bba7-934d31a2ffe7', '荅裴集陽伯明二賢各垂贈二十韻今以一章用酬兩作', '荅裴集陽伯明二賢各垂贈二十韻今以一章用酬兩作', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["知音如瓊枝，天生爲予有。","攀折若無階，何殊天上柳。","裴生清通嗣，陽子盛德後。","詩名比元長，賦體凌延壽。","珠生驪龍頷，或生靈蛇口。","何似雙瓊章，英英曜吾手。","白日不可汙，清源肯容垢。","持此山上心，待君忘情友。","且伴丘壑賞，未隨名宦誘。","坐石代瓊茵，製荷捐艾綬。","清宵集我寺，烹茗開禪牖。","發論教可垂，正文言不朽。","白雲供詩用，清吹生座右。","不嫌逸令醉，莫試仙壺酒。","皎皎尋陽隱，千年可爲偶。","一從漢道平，世事無紛糺。","星文齊七政，天軸明二斗。","召士揚弓旌，知君在林藪。","莫學潁陽子，請師高山叟。","出處藩我君，還來會厓阜。"]', '["知音如瓊枝，天生爲予有。","攀折若無階，何殊天上柳。","裴生清通嗣，陽子盛德後。","诗名比元长，賦體凌延壽。","珠生驪龙頷，或生靈蛇口。","何似雙瓊章，英英曜吾手。","白日不可汙，清源肯容垢。","持此山上心，待君忘情友。","且伴丘壑賞，未隨名宦誘。","坐石代瓊茵，製荷捐艾綬。","清宵集我寺，烹茗开禪牖。","發論教可垂，正文言不朽。","白云供诗用，清吹生座右。","不嫌逸令醉，莫試仙壺酒。","皎皎尋陽隐，千年可爲偶。","一從漢道平，世事無紛糺。","星文齊七政，天軸明二斗。","召士揚弓旌，知君在林藪。","莫学潁陽子，請師高山叟。","出处藩我君，還来會厓阜。"]', '诗', 'shi', '', NULL, '荅裴集陽伯明二賢各垂贈二十韻今以一章用酬兩作 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eef9ff7e-274e-4474-a36b-92a47cb7183b', '荅豆盧居士春夜遊東園見懷', '荅豆盧居士春夜游东园见懷', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春意賞不足，承夕步東園。","事表精慮遠，月中華木繁。","開襟寄清景，遐想屬空門。","安得纚芳屣，看君幽徑萱。"]', '["春意賞不足，承夕步东园。","事表精慮远，月中华木繁。","开襟寄清景，遐想屬空门。","安得纚芳屣，看君幽徑萱。"]', '诗', 'shi', '', NULL, '荅豆盧居士春夜遊東園見懷 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20564f12-8067-47f0-8dba-2ca90c1ba0e9', '寄崔萬芳夔', '寄崔万芳夔', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["氣殺高隼擊，惜芳步寒林。","風搖蒼琅根，霜剪荍𦾾心。","歸思忽眇眇，佳氣亦沈沈。","我身豈遐遠，如隔湘漢深。","事邇智莫及，願乖情不任。","遲君忘言侶，一笑開吾襟。"]', '["氣殺高隼擊，惜芳步寒林。","风搖蒼琅根，霜剪荍𦾾心。","归思忽眇眇，佳氣亦沈沈。","我身豈遐远，如隔湘漢深。","事邇智莫及，願乖情不任。","遲君忘言侶，一笑开吾襟。"]', '诗', 'shi', '', NULL, '寄崔萬芳夔 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959f922c-1bdd-4e38-b1ee-14ad030f8409', '訪朱放山人', '訪朱放山人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["野人未相識，何處異鄉隔。","昨逢雲陽信，教向雲陽覓。","空聞天上風，飄颻不可覿。","應非矍[鑠]翁，或是滄浪客。","早晚從我遊，共攜春山策。"]', '["野人未相識，何处異乡隔。","昨逢云陽信，教向云陽覓。","空闻天上风，飄颻不可覿。","應非矍[鑠]翁，或是滄浪客。","早晚從我游，共携春山策。"]', '诗', 'shi', '', NULL, '訪朱放山人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2058509a-b6ac-4aa7-86c3-593a36de1f3e', '晚冬廢溪東寺懷李司直縱', '晚冬廢溪东寺懷李司直縱', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["廢溪無人跡，益見離思深。","歸來始昨日，恍惚驚歲陰。","清想屬遙夜，圓景當空林。","宿昔月未改，何如故人心。","遊從間芳趾，搖落棲寒岑。","眇眇湖上別，含情初至今。","道流安寂寞，世路倦嶇嶔。","此意欲誰見，懷賢獨難任。","徽聲反冥默，夕籟何哀吟。","禪念破離夢，吾師誡援琴。","耿耿已及旦，曷由開此襟。","幽期諒未偶，勝境徒自尋。","安得西歸雲，因之傳素音。"]', '["廢溪無人跡，益见離思深。","归来始昨日，恍惚驚歲陰。","清想屬遙夜，圓景當空林。","宿昔月未改，何如故人心。","游從间芳趾，搖落棲寒岑。","眇眇湖上別，含情初至今。","道流安寂寞，世路倦嶇嶔。","此意欲誰见，懷賢独难任。","徽声反冥默，夕籟何哀吟。","禪念破離梦，吾師誡援琴。","耿耿已及旦，曷由开此襟。","幽期諒未偶，勝境徒自尋。","安得西归云，因之傳素音。"]', '诗', 'shi', '', NULL, '晚冬廢溪東寺懷李司直縱 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42e5d343-91fa-411c-934f-a223ebfd8de0', '兵後與故人別予西上至今在揚楚因有是寄', '兵後與故人別予西上至今在揚楚因有是寄', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["日月不相待，思君魂屢驚。","草玄寄楊子，作賦得蕪城。","溫溫獨游跡，遙遙相望情。","淮上青草歇，楚子秋風生。","辟士天下盡，君何獨屏營。","運開應佐世，業就可成名。","誰借楚山住，年年事耦耕。"]', '["日月不相待，思君魂屢驚。","草玄寄楊子，作賦得蕪城。","溫溫独游跡，遙遙相望情。","淮上青草歇，楚子秋风生。","辟士天下尽，君何独屏營。","運开應佐世，業就可成名。","誰借楚山住，年年事耦耕。"]', '诗', 'shi', '', NULL, '兵後與故人別予西上至今在揚楚因有是寄 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6f675e-030d-47ba-88b1-cef976d1938f', '因遊支硎寺寄邢端公', '因游支硎寺寄邢端公', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["大廈資多士，掄材得豫章。","清門推問望，早歲騁康莊。","作用方開物，聲名久擅塲。","丹延分塞郡，宿昔領戎行。","始馭屏星乘，旋陰蔽茀棠。","朝端瞻鶚立，關右仰鷹揚。","威令兼寧朔，英聲重護羌。","三軍成父子，雜虜避封疆。","身執金吾貴，時遭寶運昌。","雍容持漢矟，肅穆衛周堂。","排難知臣節，攻疑定國章。","一言明大義，千載揖休光。","踐職勳庸列，修躬志行彰。","優游應慕陸，止足定師張。","中扆懷殊政，南州佇小康。","仁爲桂江雨，威是柏臺霜。","謇諤言無隱，公忠禍不防。","譴深辭紫禁，恩在副朱方。","切玉鋒休淬，垂天翅罷翔。","論文徵賈馬，述隱許求羊。","肘後看金碧，腰間笑水蒼。","詩題白羽扇，酒挈綠油囊。","曠達機何有，深沈器莫量。","時應登古寺，佳趣在春岡。","止水平香砌，鮮雲滿石牀。","山情何寂樂，塵世自飛揚。","已遇鑪峰社，還思緝蕙房。","外心親地主，內學事空王。","花會宜春淺，禪遊喜夜涼。","高明依月境，蕭散躡庭芳。","得道殊秦佚，隳名似楚狂。","餘生於此足，不欲返韶陽。"]', '["大廈資多士，掄材得豫章。","清门推问望，早歲騁康莊。","作用方开物，声名久擅塲。","丹延分塞郡，宿昔領戎行。","始馭屏星乘，旋陰蔽茀棠。","朝端瞻鶚立，关右仰鷹揚。","威令兼寧朔，英声重護羌。","三軍成父子，杂虜避封疆。","身執金吾貴，时遭寶運昌。","雍容持漢矟，肅穆衛周堂。","排难知臣節，攻疑定国章。","一言明大義，千載揖休光。","踐職勳庸列，修躬志行彰。","優游應慕陸，止足定師張。","中扆懷殊政，南州佇小康。","仁爲桂江雨，威是柏台霜。","謇諤言無隐，公忠禍不防。","譴深辞紫禁，恩在副朱方。","切玉鋒休淬，垂天翅罷翔。","論文徵賈马，述隐許求羊。","肘後看金碧，腰间笑水蒼。","诗題白羽扇，酒挈綠油囊。","曠達機何有，深沈器莫量。","时應登古寺，佳趣在春岡。","止水平香砌，鲜云满石牀。","山情何寂乐，塵世自飞揚。","已遇鑪峰社，還思緝蕙房。","外心親地主，內学事空王。","花會宜春淺，禪游喜夜涼。","高明依月境，蕭散躡庭芳。","得道殊秦佚，隳名似楚狂。","餘生於此足，不欲返韶陽。"]', '诗', 'shi', '', NULL, '因遊支硎寺寄邢端公 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c001d0b-844c-408f-b999-e9d6b419b6a1', '同諸公奉侍祭岳瀆使大理盧幼平自會稽迴經平望將赴於朝廷期過故林不至', '同諸公奉侍祭岳瀆使大理盧幼平自會稽迴經平望將赴於朝廷期過故林不至', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["望祀崇周典，皇華出漢庭。","紫泥頒會計，玄酒薦芳馨。","聖慮多虔肅，齋心合至靈。","占祥刊史竹，筮日數堯蓂。","禮秩加新命，朝章篤理刑。","敷誠通北闕，遺愛在南亭。","苕水思曾泛，磯山憶重經。","清風門客仰，佳頌國人聽。","攀桂留卿月，徵文待使星。","春郊迴駟牡，遙識故林青。"]', '["望祀崇周典，皇华出漢庭。","紫泥頒會計，玄酒薦芳馨。","聖慮多虔肅，斋心合至靈。","占祥刊史竹，筮日數堯蓂。","禮秩加新命，朝章篤理刑。","敷誠通北闕，遺愛在南亭。","苕水思曾泛，磯山憶重經。","清风门客仰，佳頌国人听。","攀桂留卿月，徵文待使星。","春郊迴駟牡，遙識故林青。"]', '诗', 'shi', '', NULL, '同諸公奉侍祭岳瀆使大理盧幼平自會稽迴經平望將赴於朝廷期過故林不至 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aee3ca29-261b-4a10-9e26-c9b189add436', '早秋桐廬思歸示道諺上人', '早秋桐廬思归示道諺上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["桐江秋信早，憶在故山時。","靜夜風鳴磬，無人竹掃墀。","猨來觸淨水，鳥下啄寒棃。","可即關吾事，歸心自有期。"]', '["桐江秋信早，憶在故山时。","静夜风鳴磬，無人竹掃墀。","猨来觸淨水，鸟下啄寒棃。","可即关吾事，归心自有期。"]', '诗', 'shi', '', NULL, '早秋桐廬思歸示道諺上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('625ace04-666e-437e-a936-a227dc8fbef5', '勞勞山居寄呈吳處士', '勞勞山居寄呈吳处士', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山事繇來別，只應中老身。","寒園掃綻栗，秋浪拾乾薪。","領鶴閑書竹，誇雲笑向人。","俗家相去遠，野水作東鄰。"]', '["山事繇来別，只應中老身。","寒园掃綻栗，秋浪拾乾薪。","領鹤闲书竹，誇云笑向人。","俗家相去远，野水作东鄰。"]', '诗', 'shi', '', NULL, '勞勞山居寄呈吳處士 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba975704-55d9-4eb3-b676-ed76e0e92f0d', '寄報德寺從上人', '寄報德寺從上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["宗流許身子，物表養高閑。","空色清涼寺，秋聲鼓吹山。","看心水磬後，行道雨花間。","七葉翻章句，時時啓義關。"]', '["宗流許身子，物表養高闲。","空色清涼寺，秋声鼓吹山。","看心水磬後，行道雨花间。","七葉翻章句，时时啓義关。"]', '诗', 'shi', '', NULL, '寄報德寺從上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065d3757-006b-42c4-8489-d1f927495747', '山中月夜寄無錫長官', '山中月夜寄無錫长官', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["湖上涼風早，雙峰月色秋。","遙知秣陵令，今夜在西樓。","別葉蕭蕭下，含霜處處流。","如何共清景，異縣不同遊。"]', '["湖上涼风早，雙峰月色秋。","遙知秣陵令，今夜在西楼。","別葉蕭蕭下，含霜处处流。","如何共清景，異縣不同游。"]', '诗', 'shi', '', NULL, '山中月夜寄無錫長官 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d67d9d4a-0356-4439-9e1b-436fb42dfbd0', '奉賀顏使君真卿二十八郎隔絕自河北遠歸', '奉賀顏使君真卿二十八郎隔絕自河北远归', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["相失值氛煙，纔應掌上年。","久離驚貌長，多難喜身全。","比信尚書重，如威太守憐。","滿庭看玉樹，更有一枝連。"]', '["相失值氛煙，纔應掌上年。","久離驚貌长，多难喜身全。","比信尚书重，如威太守怜。","满庭看玉樹，更有一枝連。"]', '诗', 'shi', '', NULL, '奉賀顏使君真卿二十八郎隔絕自河北遠歸 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfac166d-3934-4149-bb77-4d1361f57a5f', '題湖上蘭若示清會上人', '題湖上蘭若示清會上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["峰心惠忍寺，嵊頂謝公山。","何似南湖近，芳洲一畝間。","意中雲木秀，事外水堂閑。","永日無人到，時看獨鶴還。"]', '["峰心惠忍寺，嵊頂謝公山。","何似南湖近，芳洲一畝间。","意中云木秀，事外水堂闲。","永日無人到，时看独鹤還。"]', '诗', 'shi', '', NULL, '題湖上蘭若示清會上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceef4f3f-70b7-443b-b2ae-45ae11aac8d9', '秋宵書事寄吳憑處士', '秋宵书事寄吳憑处士', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["真性在方丈，寂寥無四鄰。","秋天月色正，清夜道心真。","大夢觀前事，浮名悟此身。","不知庭樹意，榮落感何人。"]', '["真性在方丈，寂寥無四鄰。","秋天月色正，清夜道心真。","大梦观前事，浮名悟此身。","不知庭樹意，榮落感何人。"]', '诗', 'shi', '', NULL, '秋宵書事寄吳憑處士 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d0ccf8a-4d43-47e2-a9f5-3699aeaed84c', '題山壁示道維上人', '題山壁示道維上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["獨居何意足，山色在前門。","身野長無事，心冥自不言。","閑行數亂竹，靜坐照清源。","物外從知少，禪徒不耐煩。"]', '["独居何意足，山色在前门。","身野长無事，心冥自不言。","闲行數亂竹，静坐照清源。","物外從知少，禪徒不耐煩。"]', '诗', 'shi', '', NULL, '題山壁示道維上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea2609ba-ee56-4e2b-afa0-52b1abb966c1', '晚秋登佛川南峰懷裴例', '晚秋登佛川南峰懷裴例', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["登嶺望落日，眇然傷別魂。","亭臯秋色徧，遊子在荆門。","世故東西客，山空斷續猨。","此心誰復見，寂寞偶芳蓀。"]', '["登嶺望落日，眇然傷別魂。","亭臯秋色徧，游子在荆门。","世故东西客，山空斷續猨。","此心誰复见，寂寞偶芳蓀。"]', '诗', 'shi', '', NULL, '晚秋登佛川南峰懷裴例 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a194bbd-57a8-423b-8275-f6d90f2f9d3f', '訪陸處士羽', '訪陸处士羽', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["太湖東西路，吳主古山前。","所思不可見，歸鴻自翩翩。","何山賞春茗，何處弄春泉。","莫是滄浪子，悠悠一釣船。"]', '["太湖东西路，吳主古山前。","所思不可见，归鴻自翩翩。","何山賞春茗，何处弄春泉。","莫是滄浪子，悠悠一釣船。"]', '诗', 'shi', '', NULL, '訪陸處士羽 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('266be4f6-6260-4b1e-9f86-beef2c8ff4bc', '酬李侍御萼題看心道塲賦以眉毛腸心牙等五字', '酬李侍御萼題看心道塲賦以眉毛腸心牙等五字', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["我法從誰悟，心師是貫花。","三塵觀種子，一雨發萌芽。","定起輪燈缺，宵分印月斜。","了空如藏史，始肯會禪家。"]', '["我法從誰悟，心師是貫花。","三塵观種子，一雨發萌芽。","定起輪灯缺，宵分印月斜。","了空如藏史，始肯會禪家。"]', '诗', 'shi', '', NULL, '酬李侍御萼題看心道塲賦以眉毛腸心牙等五字 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26add434-21ca-44c0-bc88-35d8861735e9', '酬姚補闕南仲雲溪館中戲題隨書見寄', '酬姚補闕南仲云溪館中戲題隨书见寄', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["寺溪臨使府，風景借仁祠。","補衮周官貴，能名漢主思。","臥雲知獨處，望月憶同時。","忽枉緘中贈，瓊瑤滿手持。"]', '["寺溪臨使府，风景借仁祠。","補衮周官貴，能名漢主思。","臥云知独处，望月憶同时。","忽枉緘中贈，瓊瑤满手持。"]', '诗', 'shi', '', NULL, '酬姚補闕南仲雲溪館中戲題隨書見寄 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae6ab0a-237c-4e21-b48a-5b175721c9df', '春夜期裴都曹濟集心上人院不至', '春夜期裴都曹濟集心上人院不至', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["東林期隱吏，日月爲虛盈。","遠望浮雲隔，空憐定水清。","逍遙方外侶，荏苒府中情。","漸聽寒鞞發，淵淵在郡城。"]', '["东林期隐吏，日月爲虛盈。","远望浮云隔，空怜定水清。","逍遙方外侶，荏苒府中情。","漸听寒鞞發，淵淵在郡城。"]', '诗', 'shi', '', NULL, '春夜期裴都曹濟集心上人院不至 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e438ac36-0098-48c2-9f19-538b3864b9eb', '和裴少府懷京兄弟', '和裴少府懷京兄弟', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["宦遊三楚外，家在五陵原。","涼夜多歸夢，秋風滿故園。","北書無遠信，西候獨傷魂。","空念青門別，殷勤岐路言。"]', '["宦游三楚外，家在五陵原。","涼夜多归梦，秋风满故园。","北书無远信，西候独傷魂。","空念青门別，殷勤岐路言。"]', '诗', 'shi', '', NULL, '和裴少府懷京兄弟 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5827d143-1f3e-4968-95cd-a50208c0659c', '和閻士和望池月荅人', '和閻士和望池月荅人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["片月忽臨池，雙蛾憶畫時。","光浮空似粉，影散不成眉。","孤枕應驚夢，寒林正入帷。","情知兩處望，莫怨獨相思。"]', '["片月忽臨池，雙蛾憶畫时。","光浮空似粉，影散不成眉。","孤枕應驚梦，寒林正入帷。","情知兩处望，莫怨独相思。"]', '诗', 'shi', '', NULL, '和閻士和望池月荅人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2c31d26-e45b-441c-aad5-54f2d24801be', '遙和塵外上人與陸澧夜集山寺問湼槃義兼陸生文卷', '遙和塵外上人與陸澧夜集山寺问湼槃義兼陸生文卷', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["共是竹林賢，心從貝葉傳。","說經看月喻，開卷愛珠連。","清淨遙城外，蕭疎古塔前。","應隨北山子，高頂枕雲眠。"]', '["共是竹林賢，心從貝葉傳。","说經看月喻，开卷愛珠連。","清淨遙城外，蕭疎古塔前。","應隨北山子，高頂枕云眠。"]', '诗', 'shi', '', NULL, '遙和塵外上人與陸澧夜集山寺問湼槃義兼陸生文卷 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('443e078d-95b3-4650-846b-7de1cd41e6a7', '春日和盧使君幼平開元寺聽妙奘上人講', '春日和盧使君幼平开元寺听妙奘上人講', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["仁聖垂文在，虛空日月懸。","陵遲追哲匠，宗旨發幽詮。","法受諸侯請，心教四子傳。","春生雪山草，香下棘林天。","顧我從今日，聞經悟宿緣。","涼山萬里去，應爲教猶偏。"]', '["仁聖垂文在，虛空日月懸。","陵遲追哲匠，宗旨發幽詮。","法受諸侯請，心教四子傳。","春生雪山草，香下棘林天。","顧我從今日，闻經悟宿緣。","涼山万里去，應爲教猶偏。"]', '诗', 'shi', '', NULL, '春日和盧使君幼平開元寺聽妙奘上人講 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a07e5e5-a579-4693-abdd-cafb3ed67bfa', '荅李侍御問', '荅李侍御问', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["入道曾經離亂前，長干古寺住多年。","愛貧唯製蓮花足，取性閑書樹葉篇。","自笑不歸看石牓，誰高無事弄苔泉。","身外空名何足問，吾心已出第三禪。"]', '["入道曾經離亂前，长干古寺住多年。","愛貧唯製蓮花足，取性闲书樹葉篇。","自笑不归看石牓，誰高無事弄苔泉。","身外空名何足问，吾心已出第三禪。"]', '诗', 'shi', '', NULL, '荅李侍御問 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ccc72f0-4e2b-4591-acdc-1b70630167a0', '奉酬李員外使君嘉祐蘇臺屏營居春首有懷', '奉酬李員外使君嘉祐蘇台屏營居春首有懷', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["昔歲爲邦初未識，今朝休沐始相親。","移家水巷貧依靜，種柳風窗欲占春。","詩思先邀烏府客，山情還訪白樓人。","登臨許作煙霞伴，高在方袍間幅巾。"]', '["昔歲爲邦初未識，今朝休沐始相親。","移家水巷貧依静，種柳风窗欲占春。","诗思先邀烏府客，山情還訪白楼人。","登臨許作煙霞伴，高在方袍间幅巾。"]', '诗', 'shi', '', NULL, '奉酬李員外使君嘉祐蘇臺屏營居春首有懷 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f73594d4-caa0-4115-917f-a9c07e2161dd', '和李舍人使君紓題雲明府道室', '和李舍人使君紓題云明府道室', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["許令如今道姓雲，曾經西岳事桐君。","流霞手把應憐壽，黃鶴心期擬作羣。","金籙時教弟子檢，砂牀不遣世人聞。","桂陽亦是神仙守，分別無嗟兩地分。"]', '["許令如今道姓云，曾經西岳事桐君。","流霞手把應怜壽，黄鹤心期擬作羣。","金籙时教弟子檢，砂牀不遣世人闻。","桂陽亦是神仙守，分別無嗟兩地分。"]', '诗', 'shi', '', NULL, '和李舍人使君紓題雲明府道室 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff89d79-e08b-4ed4-815b-4843aec821c1', '奉和陸中丞使君長源寒食日作', '奉和陸中丞使君长源寒食日作', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["寒食江天氣最清，庾公晨望動高情。","因逢內火千家靜，便覩行春萬木榮。","深淺山容飛雨細，縈紆水態拂雲輕。","腰章本郡誰相似，數日臨人政已成。"]', '["寒食江天氣最清，庾公晨望动高情。","因逢內火千家静，便覩行春万木榮。","深淺山容飞雨細，縈紆水態拂云轻。","腰章本郡誰相似，數日臨人政已成。"]', '诗', 'shi', '', NULL, '奉和陸中丞使君長源寒食日作 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21cb9562-b70e-4ec5-a79d-78a68c1be706', '奉酬袁使君送陸灞却迴期道寺院', '奉酬袁使君送陸灞却迴期道寺院', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["欲別湖上客，暮期西林還。","高歌風音表，放舟月色間。","更人莫報夜，禪閣本無關。"]', '["欲別湖上客，暮期西林還。","高歌风音表，放舟月色间。","更人莫報夜，禪閣本無关。"]', '诗', 'shi', '', NULL, '奉酬袁使君送陸灞却迴期道寺院 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1da61721-336f-4f70-9fe4-fc96d8eb9794', '招韓武康章', '招韓武康章', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山僧雖不飲，酤酒引陶潛。","此意無人別，多爲俗士嫌。"]', '["山僧雖不饮，酤酒引陶潛。","此意無人別，多爲俗士嫌。"]', '诗', 'shi', '', NULL, '招韓武康章 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6002df1d-0ba7-4497-b370-f3a873600439', '秋居法華寺下院望高頂贈如獻上人', '秋居法华寺下院望高頂贈如獻上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["峰色秋天見，松聲靜夜聞。","影孤長不出，行道在寒雲。"]', '["峰色秋天见，松声静夜闻。","影孤长不出，行道在寒云。"]', '诗', 'shi', '', NULL, '秋居法華寺下院望高頂贈如獻上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f31c396a-eef7-452f-9f62-b3afdc43c51f', '贈韋早陸羽', '贈韋早陸羽', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["只將陶與謝，終日可忘情。","不欲多相識，逢人懶道名。"]', '["只將陶與謝，終日可忘情。","不欲多相識，逢人懶道名。"]', '诗', 'shi', '', NULL, '贈韋早陸羽 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8771fe65-6982-444c-8a41-410c25c2b104', '戲呈薛彝', '戲呈薛彝', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山僧不厭野，才子會須狂。","何處銷君興，春風擺綠楊。"]', '["山僧不厭野，才子會須狂。","何处銷君兴，春风擺綠楊。"]', '诗', 'shi', '', NULL, '戲呈薛彝 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8d80a88-b7a2-4e3c-8002-783940ad5901', '贈顏主簿', '贈顏主簿', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["漢家儀禮盛，名教出諸顏。","更見尚書後，能文在子山。"]', '["漢家儀禮盛，名教出諸顏。","更见尚书後，能文在子山。"]', '诗', 'shi', '', NULL, '贈顏主簿 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6edd2d8d-fbb2-4709-9ea5-e6091d26b3e5', '贈融上人', '贈融上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["常愛西林寺，池中月出時。","芭蕉一片葉，書取寄吾師。"]', '["常愛西林寺，池中月出时。","芭蕉一片葉，书取寄吾師。"]', '诗', 'shi', '', NULL, '贈融上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5e803eb-f34f-4b69-ae74-75d05285ecb3', '聽寒更寄朱兵曹巨川', '听寒更寄朱兵曹巨川', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["欹枕聽寒更，寒更發還住。","一夜千萬聲，幾聲到君處。"]', '["欹枕听寒更，寒更發還住。","一夜千万声，幾声到君处。"]', '诗', 'shi', '', NULL, '聽寒更寄朱兵曹巨川 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b4fd7a6-139e-49f3-b28a-e5eb3ffe497f', '早春書懷寄李少府仲宣', '早春书懷寄李少府仲宣', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["早年初問法，因悟目中花。","忽值胡雛起，芟夷如亂麻。","脫身投彼岸，弔影念生涯。","跡與空門合，心將世路賒。","東田已蕪沒，南澗益傷嗟。","崇替驚人事，凋殘感物華。","知君過我里，惆悵舊煙霞。"]', '["早年初问法，因悟目中花。","忽值胡雛起，芟夷如亂麻。","脫身投彼岸，弔影念生涯。","跡與空门合，心將世路賒。","东田已蕪沒，南澗益傷嗟。","崇替驚人事，凋殘感物华。","知君過我里，惆悵旧煙霞。"]', '诗', 'shi', '', NULL, '早春書懷寄李少府仲宣 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4ce7e08-88c0-4dc0-a2bc-fe504b31a8fa', '贈和評事判官', '贈和評事判官', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["廷評年少法家流，心似澄江月正秋。","學究天人知遠識，權分鹽鐵許良籌。","春風憶酒烏家近，好月論禪謝寺幽。","清白比來誰見賞，憐君獨有富人侯。"]', '["廷評年少法家流，心似澄江月正秋。","学究天人知远識，權分鹽鐵許良籌。","春风憶酒烏家近，好月論禪謝寺幽。","清白比来誰见賞，怜君独有富人侯。"]', '诗', 'shi', '', NULL, '贈和評事判官 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9419fd9a-b053-4d34-9fc5-4350e10e473c', '酬秦系山人題贈', '酬秦系山人題贈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["雲林出空烏未歸，松吹時飄雨浴衣。","石語花愁徒自詫，吾心見境盡爲非。"]', '["云林出空烏未归，松吹时飄雨浴衣。","石語花愁徒自詫，吾心见境尽爲非。"]', '诗', 'shi', '', NULL, '酬秦系山人題贈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4023af-9abc-4b0d-bba8-455a4395e39f', '酬秦系山人戲贈', '酬秦系山人戲贈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["正論禪寂忽狂歌，莫是塵心顛倒多。","白足行花曾不染，黃囊貯酒欲如何。"]', '["正論禪寂忽狂歌，莫是塵心顛倒多。","白足行花曾不染，黄囊貯酒欲如何。"]', '诗', 'shi', '', NULL, '酬秦系山人戲贈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1be0ebf-036a-41cf-962c-7b20b347f263', '貽李湯', '貽李湯', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["茅氏常論七真記，壺公愛說三山事。","寧知梅福在人間，獨爲蒼生作仙吏。","日服丹砂骨自清，膚如冰雪心更明。","山中玉筍是仙藥，袖裏素書題養生。","願隨黃鶴一輕舉，仰望青霄獨延佇。","平生好駿君已知，何必山陰訪王許。"]', '["茅氏常論七真記，壺公愛说三山事。","寧知梅福在人间，独爲蒼生作仙吏。","日服丹砂骨自清，膚如冰雪心更明。","山中玉筍是仙藥，袖裏素书題養生。","願隨黄鹤一轻舉，仰望青霄独延佇。","平生好駿君已知，何必山陰訪王許。"]', '诗', 'shi', '', NULL, '貽李湯 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd1cd3d-a7d6-4fc5-aa55-b13448d9b3b4', '述祖德贈湖上諸沈', '述祖德贈湖上諸沈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["我祖文章有盛名，千年海內重嘉聲。","雪飛梁苑操奇賦，春發池塘得佳句。","世業相承及我身，風流自謂過時人。","初看甲乙矜言語，對客偏能鴝鵒舞。","飽用黃金無所求，長裾曳地干王侯。","一朝金盡長裾裂，吾道不行計亦拙。","歲晚高歌悲苦寒，空堂危坐百憂攢。","昔時軒蓋金陵下，何處不傳沈與謝。","綿綿芳籍至今聞，眷眷通宗有數君。","誰見予心獨飄泊，依山寄水似浮雲。"]', '["我祖文章有盛名，千年海內重嘉声。","雪飞梁苑操奇賦，春發池塘得佳句。","世業相承及我身，风流自謂過时人。","初看甲乙矜言語，对客偏能鴝鵒舞。","飽用黄金無所求，长裾曳地干王侯。","一朝金尽长裾裂，吾道不行計亦拙。","歲晚高歌悲苦寒，空堂危坐百憂攢。","昔时軒蓋金陵下，何处不傳沈與謝。","綿綿芳籍至今闻，眷眷通宗有數君。","誰见予心独飄泊，依山寄水似浮云。"]', '诗', 'shi', '', NULL, '述祖德贈湖上諸沈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f152c170-82c8-4cc8-a1a7-ce1037f1569e', '舟行懷閻士和', '舟行懷閻士和', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["二月湖南春草徧，橫山渡口花如霰。","相思一日在孤舟，空見歸雲兩三片。"]', '["二月湖南春草徧，橫山渡口花如霰。","相思一日在孤舟，空见归云兩三片。"]', '诗', 'shi', '', NULL, '舟行懷閻士和 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa22ac0-3f81-434e-a4ae-468fbf435975', '贈張道士', '贈張道士', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["玉京真子名太一，因服日華心如日。","此心不許世人知，只向仙宮未曾出。"]', '["玉京真子名太一，因服日华心如日。","此心不許世人知，只向仙宮未曾出。"]', '诗', 'shi', '', NULL, '贈張道士 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55593b78-8ce4-413b-ab56-cd3d3416e319', '戲呈吳馮', '戲呈吳馮', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["世人不知心是道，只言道在他方妙。","還如瞽者望長安，長安在西向東笑。"]', '["世人不知心是道，只言道在他方妙。","還如瞽者望长安，长安在西向东笑。"]', '诗', 'shi', '', NULL, '戲呈吳馮 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ef3f17a-c05b-45b0-ba05-3135f4cdfed8', '宿山寺寄李中丞洪', '宿山寺寄李中丞洪', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["偶來中峰宿，閑坐見真境。","寂寂孤月心，亭亭圓泉影。","□□□滿山，花落始知靜。","從他半夜愁猨驚，不廢此心長杳冥。"]', '["偶来中峰宿，闲坐见真境。","寂寂孤月心，亭亭圓泉影。","□□□满山，花落始知静。","從他半夜愁猨驚，不廢此心长杳冥。"]', '诗', 'shi', '', NULL, '宿山寺寄李中丞洪 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad11014-288e-4860-9ac7-e9819470d12f', '戲贈吳馮', '戲贈吳馮', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["予讀古人書，遂識古人面。","不是識古人，邪正心自見。","貴義輕財求俗譽，一錢與人便驕倨。","昨朝爲火今爲冰，此道非君獨撫膺。"]', '["予读古人书，遂識古人面。","不是識古人，邪正心自见。","貴義轻財求俗譽，一錢與人便驕倨。","昨朝爲火今爲冰，此道非君独撫膺。"]', '诗', 'shi', '', NULL, '戲贈吳馮 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03cf8eaf-8e37-46cc-99b6-0929eadceb87', '感興贈烏程李明府伯宜兼簡諸秀才', '感兴贈烏程李明府伯宜兼簡諸秀才', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["門前峴山近，無路可登陟。","徒愛峴山高，仰之常歎息。","不如松與桂，生在重巖側。"]', '["门前峴山近，無路可登陟。","徒愛峴山高，仰之常歎息。","不如松與桂，生在重巖側。"]', '诗', 'shi', '', NULL, '感興贈烏程李明府伯宜兼簡諸秀才 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f63abe-1137-4588-a5f6-24de23368c50', '晚秋宿李軍道所居', '晚秋宿李軍道所居', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["清溪路不遙，都尉每相招。","落日休戎馬，秋風罷射鵰。","朮花生野徑，柏實滿寒條。","永夜依山府，禪心共寂寥。"]', '["清溪路不遙，都尉每相招。","落日休戎马，秋风罷射鵰。","朮花生野徑，柏實满寒條。","永夜依山府，禪心共寂寥。"]', '诗', 'shi', '', NULL, '晚秋宿李軍道所居 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98a22f14-aef7-4b95-a305-97ec10ae9c58', '送陸判官歸杭州', '送陸判官归杭州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["芳草潛州路，乘軺憶再旋。","餘花故林下，殘月舊池邊。","峰色雲端寺，潮聲海上天。","明朝富春渚，應見謝公船。"]', '["芳草潛州路，乘軺憶再旋。","餘花故林下，殘月旧池邊。","峰色云端寺，潮声海上天。","明朝富春渚，應见謝公船。"]', '诗', 'shi', '', NULL, '送陸判官歸杭州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3efe3373-2dd4-4189-a818-4fce16cd49cf', '奉和顏使君真卿與陸處士羽登妙喜寺三癸亭', '奉和顏使君真卿與陸处士羽登妙喜寺三癸亭', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["秋意西山多，列岑縈左次。","繕亭歷三癸，疏趾鄰什寺。","元化隱靈蹤，始君啓高誄。","誅榛養翹楚，鞭草理芳穗。","俯砌披水容，逼天掃峰翠。","境新耳目換，物遠風煙異。","倚石忘世情，援雲得真意。","嘉林幸勿剪，禪侶欣可庇。","衛法大臣過，佐遊羣英萃。","龍池護清澈，虎節到深邃。","徒想嵊頂期，於今沒遺記。"]', '["秋意西山多，列岑縈左次。","繕亭歷三癸，疏趾鄰什寺。","元化隐靈蹤，始君啓高誄。","誅榛養翹楚，鞭草理芳穗。","俯砌披水容，逼天掃峰翠。","境新耳目換，物远风煙異。","倚石忘世情，援云得真意。","嘉林幸勿剪，禪侶欣可庇。","衛法大臣過，佐游羣英萃。","龙池護清澈，虎節到深邃。","徒想嵊頂期，於今沒遺記。"]', '诗', 'shi', '', NULL, '奉和顏使君真卿與陸處士羽登妙喜寺三癸亭 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e45a7251-e7b2-46e5-971c-a55c4c63dbb7', '奉陪陸使君長源裴端公樞春遊東西武丘寺', '奉陪陸使君长源裴端公樞春游东西武丘寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["雲水夾雙剎，遙疑涌平陂。","入門見藏山，元化何由窺。","曳組探詭怪，停驄訪幽奇。","情高氣爲爽，德暖春亦隨。","瑤草自的皪，蕙樓爭蔽虧。","金精落壞陵，劒彩沈古池。","一覽币天界，中峰步未移。","應嘉生公石，列坐援松枝。"]', '["云水夾雙剎，遙疑涌平陂。","入门见藏山，元化何由窺。","曳組探詭怪，停驄訪幽奇。","情高氣爲爽，德暖春亦隨。","瑤草自的皪，蕙楼爭蔽虧。","金精落壞陵，劒彩沈古池。","一覽币天界，中峰步未移。","應嘉生公石，列坐援松枝。"]', '诗', 'shi', '', NULL, '奉陪陸使君長源裴端公樞春遊東西武丘寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dfb1fe5-5862-4db0-b3dd-977e7a0992ea', '奉和陸使君長源夏月遊太湖', '奉和陸使君长源夏月游太湖', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["庾公心曠遠，府事局耳目。","遂與南湖遊，虛襟滌煩燠。","始知皇天意，積水在亭育。","細流信不讓，動物欣所蓄。","萬頃合天容，洗然無雲族。","峭蒨矚仙嶺，超遙隨明牧。","知公愛澄清，波靜氣亦肅。","已見橫流極，況聞長鯨戮。","中洲暫採蘋，南郡思剖竹。","向夕分好風，飄然送歸舳。"]', '["庾公心曠远，府事局耳目。","遂與南湖游，虛襟滌煩燠。","始知皇天意，積水在亭育。","細流信不讓，动物欣所蓄。","万頃合天容，洗然無云族。","峭蒨矚仙嶺，超遙隨明牧。","知公愛澄清，波静氣亦肅。","已见橫流極，況闻长鯨戮。","中洲暫採蘋，南郡思剖竹。","向夕分好风，飄然送归舳。"]', '诗', 'shi', '', NULL, '奉和陸使君長源夏月遊太湖 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10837c16-9587-4251-84fe-69d822946433', '奉和崔中丞使君論李侍御萼登爛柯山宿石橋寺効小謝體', '奉和崔中丞使君論李侍御萼登爛柯山宿石橋寺効小謝體', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["常愛謝公郡，幽期願相從。","果迴青驄臆，共躡玄仙踪。","靈境若髣髴，爛柯思再逢。","飛梁丹霞接，古局蒼苔封。","往想冥昧理，誰親冰雪容。","蕙樓聳空界，蓮宇開中峰。","昔化沖虛鶴，今藏護法龍。","雲窺香樹沓，月見色天重。","永夜寄岑寂，清言滌心胸。","盛遊千年後，書在巖中松。"]', '["常愛謝公郡，幽期願相從。","果迴青驄臆，共躡玄仙踪。","靈境若髣髴，爛柯思再逢。","飞梁丹霞接，古局蒼苔封。","往想冥昧理，誰親冰雪容。","蕙楼聳空界，蓮宇开中峰。","昔化沖虛鹤，今藏護法龙。","云窺香樹沓，月见色天重。","永夜寄岑寂，清言滌心胸。","盛游千年後，书在巖中松。"]', '诗', 'shi', '', NULL, '奉和崔中丞使君論李侍御萼登爛柯山宿石橋寺効小謝體 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144e8b40-7119-4952-9e37-fde527ad7fb1', '同顏使君真卿李侍御萼遊法華寺登鳳翅山望太湖', '同顏使君真卿李侍御萼游法华寺登鳳翅山望太湖', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["雙峰開鳳翅，秀出南湖州。","地勢抱郊樹，山威增郡樓。","正逢周柱史，來會魯諸侯。","緩步凌彩蒨，清鐃發颼飀。","披雲得靈境，拂石臨芳洲。","積翠遙空碧，含風廣澤秋。","蕭辰資麗思，高論驚精修。","何似鍾山集，[徵]文及惠休。"]', '["雙峰开鳳翅，秀出南湖州。","地勢抱郊樹，山威增郡楼。","正逢周柱史，来會魯諸侯。","緩步凌彩蒨，清鐃發颼飀。","披云得靈境，拂石臨芳洲。","積翠遙空碧，含风廣澤秋。","蕭辰資丽思，高論驚精修。","何似鍾山集，[徵]文及惠休。"]', '诗', 'shi', '', NULL, '同顏使君真卿李侍御萼遊法華寺登鳳翅山望太湖 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92ca8a87-e2f9-4cdc-8357-21ed2a7972a1', '奉陪陸使君長源諸公遊支硎寺', '奉陪陸使君长源諸公游支硎寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["嘗覽高逸傳，山僧有遺蹤。","佐遊繼雅篇，嘉會何繇逢。","塵世即下界，色天當上峰。","春暉徧衆草，寒色留高松。","繚繞彩雲合，參差綺樓重。","瓊葩灑巾舃，石瀃清心胸。","靈境若可託，道情知所從。"]', '["嘗覽高逸傳，山僧有遺蹤。","佐游繼雅篇，嘉會何繇逢。","塵世即下界，色天當上峰。","春暉徧衆草，寒色留高松。","繚繞彩云合，參差綺楼重。","瓊葩灑巾舃，石瀃清心胸。","靈境若可託，道情知所從。"]', '诗', 'shi', '', NULL, '奉陪陸使君長源諸公遊支硎寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a6c5797-7ca9-4b01-be84-1d654803d0ae', '奉陪鄭使君諤遊太湖至洞庭山登上真觀却望湖水', '奉陪鄭使君諤游太湖至洞庭山登上真观却望湖水', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["郡齋得無事，放舟下南湖。","湖中見仙邸，果與心賞俱。","不遠風物變，忽如寰宇殊。","背雲視層崖，別是登蓬壺。","突兀盤水府，參差沓天衢。","迴瞻平蕪盡，洪流豁中區。","氣吞江山勢，色淨氛靄無。","靈長習水德，勝勢當地樞。","朝宗動歸心，萬里思鴻途。"]', '["郡斋得無事，放舟下南湖。","湖中见仙邸，果與心賞俱。","不远风物变，忽如寰宇殊。","背云視層崖，別是登蓬壺。","突兀盤水府，參差沓天衢。","迴瞻平蕪尽，洪流豁中區。","氣吞江山勢，色淨氛靄無。","靈长習水德，勝勢當地樞。","朝宗动归心，万里思鴻途。"]', '诗', 'shi', '', NULL, '奉陪鄭使君諤遊太湖至洞庭山登上真觀却望湖水 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6955a27f-37a1-4b5f-968b-f933ed97805f', '奉和袁使君高郡中新亭會張鍊師晝會二上人', '奉和袁使君高郡中新亭會張鍊師晝會二上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["置亭隱城堞，事簡跡易幽。","公性崇儉素，雅才非廣求。","傍簷竹雨清，拂案杉風秋。","不移府中步，登茲如遠遊。","坐覺詩思高，俯知物役休。","虛寂偶禪子，逍遙親道流。","更聞臨川作，下節安能酬。"]', '["置亭隐城堞，事簡跡易幽。","公性崇儉素，雅才非廣求。","傍簷竹雨清，拂案杉风秋。","不移府中步，登茲如远游。","坐覺诗思高，俯知物役休。","虛寂偶禪子，逍遙親道流。","更闻臨川作，下節安能酬。"]', '诗', 'shi', '', NULL, '奉和袁使君高郡中新亭會張鍊師晝會二上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec78521c-ea41-4da5-9d14-282471da0d1d', '奉和陸使君長源水堂納涼効曹劉體', '奉和陸使君长源水堂納涼効曹劉體', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["柳家陶暑亭，意遠不可齊。","煩襟蕩朱弦，高步援綠荑。","愛公滿亭客，來是清風攜。","瀅渟前溪上，曠望古郡西。","六月正中伏，水軒氣常淒。","野香襲荷芰，道性親鳧鷖。","禪子顧惠休，逸民重劉黎。","乃知高世量，不以出處暌。"]', '["柳家陶暑亭，意远不可齊。","煩襟蕩朱弦，高步援綠荑。","愛公满亭客，来是清风携。","瀅渟前溪上，曠望古郡西。","六月正中伏，水軒氣常淒。","野香襲荷芰，道性親鳧鷖。","禪子顧惠休，逸民重劉黎。","乃知高世量，不以出处暌。"]', '诗', 'shi', '', NULL, '奉和陸使君長源水堂納涼効曹劉體 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eced748b-2e7b-4991-82e4-5898eb8e8e77', '夏日奉陪陸使君長源公堂集', '夏日奉陪陸使君长源公堂集', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["府中自清遠，六月高梧間。","寥亮泛雅瑟，逍遙扣玄關。","嶺雲與人靜，庭鶴隨公閑。","動息諒兼遂，茲情即東山。"]', '["府中自清远，六月高梧间。","寥亮泛雅瑟，逍遙扣玄关。","嶺云與人静，庭鹤隨公闲。","动息諒兼遂，茲情即东山。"]', '诗', 'shi', '', NULL, '夏日奉陪陸使君長源公堂集 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c61ad4f-d648-4851-bc9d-7718e4b99bf8', '九日和于使君思上京親故', '九日和于使君思上京親故', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["霽景滿水國，我公望江城。","碧山與黃花，爛熳多秋情。","搖落見松柏，歲寒比忠貞。","歡娛在鴻都，是日思朝英。"]', '["霽景满水国，我公望江城。","碧山與黄花，爛熳多秋情。","搖落见松柏，歲寒比忠貞。","歡娛在鴻都，是日思朝英。"]', '诗', 'shi', '', NULL, '九日和于使君思上京親故 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('916d2a7a-fa6b-43bf-9faa-140f1e79c203', '伏日就湯評事衡湖上避暑', '伏日就湯評事衡湖上避暑', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["大火方燥石，停雲晝亦收。","將從賞心侶，寸景難遠遊。","擁几苦炎伏，出門望汀洲。","迴溪照軒宇，廣陌臨梧楸。","釋悶命雅瑟，放情思亂流。","更持無生論，可以清煩憂。"]', '["大火方燥石，停云晝亦收。","將從賞心侶，寸景难远游。","擁几苦炎伏，出门望汀洲。","迴溪照軒宇，廣陌臨梧楸。","釋悶命雅瑟，放情思亂流。","更持無生論，可以清煩憂。"]', '诗', 'shi', '', NULL, '伏日就湯評事衡湖上避暑 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e26809a-d48a-4d15-abe6-ba54c28792e7', '奉和顏使君真卿修韻海畢會諸文士東堂重校', '奉和顏使君真卿修韻海畢會諸文士东堂重校', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["外學宗碩儒，游焉從後進。","恃以仁恕廣，不學門欄峻。","著書裨理化，奉上表誠信。","探討始河圖，紛綸歸海韻。","親承大匠琢，況覩頹波振。","錯簡記鉛槧，閱書移玉鎮。","曷繇旌不朽，盛美流歌引。"]', '["外学宗碩儒，游焉從後進。","恃以仁恕廣，不学门欄峻。","著书裨理化，奉上表誠信。","探討始河圖，紛綸归海韻。","親承大匠琢，況覩頹波振。","錯簡記鉛槧，閱书移玉鎮。","曷繇旌不朽，盛美流歌引。"]', '诗', 'shi', '', NULL, '奉和顏使君真卿修韻海畢會諸文士東堂重校 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a48f3f5-6e61-4e22-8da8-0f164e72d54c', '喜義興權明府自君山至集陸處士羽青塘別業', '喜義兴權明府自君山至集陸处士羽青塘別業', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["應難久辭秩，暫寄君陽隱。","已見縣名花，會逢闈是粉。","本自尋人至，寧因看竹引。","身關白雲多，門占春山盡。","最賞無事心，籬邊釣溪近。"]', '["應难久辞秩，暫寄君陽隐。","已见縣名花，會逢闈是粉。","本自尋人至，寧因看竹引。","身关白云多，门占春山尽。","最賞無事心，籬邊釣溪近。"]', '诗', 'shi', '', NULL, '喜義興權明府自君山至集陸處士羽青塘別業 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f99a4443-293c-43db-afde-7bedd638580e', '夏日集李司直縱溪齋', '夏日集李司直縱溪斋', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["修景屬良會，遠飆生煩襟。","泄雲收淨綠，衆木積芳陰。","疏滌府中務，迢遙湖上心。","習閑得招我，賞夜宜泛琴。","山近資性靜，月來寄情深。","澹然若事外，豈藉隳華簪。"]', '["修景屬良會，远飆生煩襟。","泄云收淨綠，衆木積芳陰。","疏滌府中務，迢遙湖上心。","習闲得招我，賞夜宜泛琴。","山近資性静，月来寄情深。","澹然若事外，豈藉隳华簪。"]', '诗', 'shi', '', NULL, '夏日集李司直縱溪齋 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daa348f2-e36c-4742-a8d8-2c083162208d', '夏日題桐廬楊明府納涼山齋', '夏日題桐廬楊明府納涼山斋', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["陶家無炎暑，自有林中峰。","席上落山影，桐梢迴水容。","放懷涼風至，緩步清陰重。","何事親堆案，猶多高世蹤。"]', '["陶家無炎暑，自有林中峰。","席上落山影，桐梢迴水容。","放懷涼风至，緩步清陰重。","何事親堆案，猶多高世蹤。"]', '诗', 'shi', '', NULL, '夏日題桐廬楊明府納涼山齋 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('058af41c-0711-4f11-9a5a-c3e9f19a4df9', '和楊明府早秋遊法華寺', '和楊明府早秋游法华寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["釋事出縣閤，初聞茲山靈。","寺扉隱天色，影剎遙丁丁。","碧峰委合沓，香蔓垂蓂苓。","清景爲公有，放曠雲邊亭。","秋賞石潭潔，夜嘉杉月清。","誦空性不昧，助道跡又經。","是以於物理，紛然若未形。","移來字人要，全與此道冥。"]', '["釋事出縣閤，初闻茲山靈。","寺扉隐天色，影剎遙丁丁。","碧峰委合沓，香蔓垂蓂苓。","清景爲公有，放曠云邊亭。","秋賞石潭潔，夜嘉杉月清。","誦空性不昧，助道跡又經。","是以於物理，紛然若未形。","移来字人要，全與此道冥。"]', '诗', 'shi', '', NULL, '和楊明府早秋遊法華寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a74d2e6d-1a6f-470c-92b4-11614201d736', '宿道士觀', '宿道士观', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["古觀秋木秀，冷然屬鮮飆。","瓊葩被修蔓，柏實滿寒條。","影殿山寂寂，寥天月昭昭。","幽期寄仙侶，習定至中宵。","清佩聞虛步，真官方宿朝。"]', '["古观秋木秀，冷然屬鲜飆。","瓊葩被修蔓，柏實满寒條。","影殿山寂寂，寥天月昭昭。","幽期寄仙侶，習定至中宵。","清佩闻虛步，真官方宿朝。"]', '诗', 'shi', '', NULL, '宿道士觀 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('747eba0a-0cbc-406d-9a8f-3e45c60a170a', '冬日天井西峰張鍊師所居', '冬日天井西峰張鍊師所居', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["採薪逢野泉，漸見棲閑所。","坎坎山上聲，幽幽林中語。","仙鄉何代隱，鄉服言亦楚。","開水淨藥苗，掃雪候山侶。","零葉聚敗籬，幽花積寒渚。","冥冥孤鶴性，天外思輕舉。"]', '["採薪逢野泉，漸见棲闲所。","坎坎山上声，幽幽林中語。","仙乡何代隐，乡服言亦楚。","开水淨藥苗，掃雪候山侶。","零葉聚敗籬，幽花積寒渚。","冥冥孤鹤性，天外思轻舉。"]', '诗', 'shi', '', NULL, '冬日天井西峰張鍊師所居 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ea14494-6cc2-4c8e-93c5-e1e83816dddc', '奉同顏使君真卿開元寺經藏院會觀樹文殊碑', '奉同顏使君真卿开元寺經藏院會观樹文殊碑', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["萬國布殊私，千年降祖師。","雁門傳法至，龍藏立言時。","故實刊周典，新聲播魯詩。","六銖那更拂，劫石盡無期。"]', '["万国布殊私，千年降祖師。","雁门傳法至，龙藏立言时。","故實刊周典，新声播魯诗。","六銖那更拂，劫石尽無期。"]', '诗', 'shi', '', NULL, '奉同顏使君真卿開元寺經藏院會觀樹文殊碑 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39c7a954-06d2-4886-815f-33df6c3ccba2', '奉同盧使君幼平遊精舍寺', '奉同盧使君幼平游精舍寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["影剎西方在，虛空翠色分。","人天霽後見，猨鳥定中聞。","真界隱青壁，春山凌白雲。","今朝石門會，千古仰斯文。"]', '["影剎西方在，虛空翠色分。","人天霽後见，猨鸟定中闻。","真界隐青壁，春山凌白云。","今朝石门會，千古仰斯文。"]', '诗', 'shi', '', NULL, '奉同盧使君幼平遊精舍寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('461849d0-d0c0-43f0-a778-89fb40140ace', '奉同顏使君真卿袁侍御駱駝橋翫月', '奉同顏使君真卿袁侍御駱駝橋翫月', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山中常見月，不及共遊時。","水上恐將缺，林端愛落遲。","烏驚憲府客，人詠鮑家詩。","永夜南橋望，裴回若有期。"]', '["山中常见月，不及共游时。","水上恐將缺，林端愛落遲。","烏驚憲府客，人詠鲍家诗。","永夜南橋望，裴回若有期。"]', '诗', 'shi', '', NULL, '奉同顏使君真卿袁侍御駱駝橋翫月 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('588a3bdb-03ab-45c2-89df-2aef3ec414a6', '和邢端公登臺春望句句有春字之什', '和邢端公登台春望句句有春字之什', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春日繡衣輕，春臺別有情。","春煙間草色，春鳥隔花聲。","春樹亂無次，春山遙得名。","春風正飄蕩，春甕莫須傾。"]', '["春日繡衣轻，春台別有情。","春煙间草色，春鸟隔花声。","春樹亂無次，春山遙得名。","春风正飄蕩，春甕莫須傾。"]', '诗', 'shi', '', NULL, '和邢端公登臺春望句句有春字之什 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00148577-1689-4ef2-ae7f-9bc484345c53', '經仙人渚即沈山下古人沈義白日昇仙處', '經仙人渚即沈山下古人沈義白日昇仙处', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["日月人間短，何時此得仙。","古山春已盡，遺渚事空傳。","不見騰雲駕，徒臨洗藥泉。","如今成逝水，翻使恨流年。"]', '["日月人间短，何时此得仙。","古山春已尽，遺渚事空傳。","不见腾云駕，徒臨洗藥泉。","如今成逝水，翻使恨流年。"]', '诗', 'shi', '', NULL, '經仙人渚即沈山下古人沈義白日昇仙處 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4981d78-fa46-4ecb-a281-4f88075a98aa', '獨遊二首 一', '独游二首 一', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["性野趣無端，春晴路又乾。","逢泉破石弄，放鶴向雲看。","好僻誰相似，從狂我自安。","芳洲亦有意，步上白沙灘。"]', '["性野趣無端，春晴路又乾。","逢泉破石弄，放鹤向云看。","好僻誰相似，從狂我自安。","芳洲亦有意，步上白沙灘。"]', '诗', 'shi', '', NULL, '獨遊二首 一 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16ea8a69-f21b-42cc-ac32-f59752a88248', '獨遊二首 二', '独游二首 二', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["臨水興不盡，虛舟可同嬉。","還雲與歸鳥，若共山僧期。","世事吾不預，此心誰得知。","西峰有禪老，應見獨遊時。"]', '["臨水兴不尽，虛舟可同嬉。","還云與归鸟，若共山僧期。","世事吾不預，此心誰得知。","西峰有禪老，應见独游时。"]', '诗', 'shi', '', NULL, '獨遊二首 二 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf7d9da-1f5e-4ef9-a6be-b210aa5fcf66', '遊溪待月', '游溪待月', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["溪色思泛月，沿洄欲未歸。","殘燈逢水店，疎磬憶山扉。","夜浦魚驚少，空林鵲遶稀。","可中纔望見，撩亂擣寒衣。"]', '["溪色思泛月，沿洄欲未归。","殘灯逢水店，疎磬憶山扉。","夜浦鱼驚少，空林鵲遶稀。","可中纔望见，撩亂擣寒衣。"]', '诗', 'shi', '', NULL, '遊溪待月 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ed6f9c-5526-4c32-9bc0-bc8f3d272fdb', '西溪獨泛', '西溪独泛', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["道情何所居，素舸漫流間。","真性憐高鶴，無名羨野山。","經寒叢竹秀，入靜片雲閑。","泛泛誰爲侶，唯應共月還。"]', '["道情何所居，素舸漫流间。","真性怜高鹤，無名羨野山。","經寒叢竹秀，入静片云闲。","泛泛誰爲侶，唯應共月還。"]', '诗', 'shi', '', NULL, '西溪獨泛 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a165cb66-168f-4906-8a08-5b4586bc6df9', '早秋陪韓明府泛阮元公溪', '早秋陪韓明府泛阮元公溪', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["雨信清殘暑，蕭條古縣西。","早涼生浦溆，秋意滿高低。","前事雖堆案，閑情得泝溪。","何言戰未勝，空寂用還齊。"]', '["雨信清殘暑，蕭條古縣西。","早涼生浦溆，秋意满高低。","前事雖堆案，闲情得泝溪。","何言戰未勝，空寂用還齊。"]', '诗', 'shi', '', NULL, '早秋陪韓明府泛阮元公溪 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039f75f6-1973-49c0-9e88-35f0b4882d4f', '九日陪顏使君真卿登水樓', '九日陪顏使君真卿登水楼', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["重陽荆楚尚，高會此難陪。","偶見登龍客，同遊戲馬臺。","風文向水疊，雲態擁歌迴。","持菊煩相問，捫襟媿不才。"]', '["重陽荆楚尚，高會此难陪。","偶见登龙客，同游戲马台。","风文向水叠，云態擁歌迴。","持菊煩相问，捫襟媿不才。"]', '诗', 'shi', '', NULL, '九日陪顏使君真卿登水樓 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f259d08-91cd-4faa-8740-f77e3d195e4a', '與盧孟明別後宿南湖對月', '與盧孟明別後宿南湖对月', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["五湖生夜月，千里滿寒流。","曠望煙霞盡，淒涼天地秋。","相思路渺渺，獨夢水悠悠。","何處空江上，裴回送客舟。"]', '["五湖生夜月，千里满寒流。","曠望煙霞尽，淒涼天地秋。","相思路渺渺，独梦水悠悠。","何处空江上，裴回送客舟。"]', '诗', 'shi', '', NULL, '與盧孟明別後宿南湖對月 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bc58364-1fb9-43f1-91ce-02bf101db06b', '自義亭驛送李長史縱夜泊臨平東湖', '自義亭驛送李长史縱夜泊臨平东湖', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["長亭賓馭散，岐路起悲風。","千里勤王事，驅車明月中。","寒生洞庭水，夜度塞門鴻。","處處堪傷別，歸來山又空。"]', '["长亭賓馭散，岐路起悲风。","千里勤王事，驱车明月中。","寒生洞庭水，夜度塞门鴻。","处处堪傷別，归来山又空。"]', '诗', 'shi', '', NULL, '自義亭驛送李長史縱夜泊臨平東湖 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a134d9d7-4a3c-4354-94c4-d28cbaf074b5', '出遊', '出游', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["少時不見山，便覺無奇趣。","狂發從亂歌，情來任閑步。","此心誰共證，笑向風吹樹。"]', '["少时不见山，便覺無奇趣。","狂發從亂歌，情来任闲步。","此心誰共證，笑向风吹樹。"]', '诗', 'shi', '', NULL, '出遊 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d1bf2bd-7722-4904-b05b-a1f54223b410', '界石守風望天竺靈隱二寺', '界石守风望天竺靈隐二寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山頂東西寺，江中旦暮潮。","歸心不可到，松路在青霄。"]', '["山頂东西寺，江中旦暮潮。","归心不可到，松路在青霄。"]', '诗', 'shi', '', NULL, '界石守風望天竺靈隱二寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('482a0d82-c168-405d-86f4-083b0a5279f0', '奉和顏使君真卿修韻海畢州中重宴', '奉和顏使君真卿修韻海畢州中重宴', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["世學高南郡，身封盛魯邦。","九流宗韻海，七字揖文江。","借賞雲歸堞，留歡月在窗。","不知名教樂，千載與誰雙。"]', '["世学高南郡，身封盛魯邦。","九流宗韻海，七字揖文江。","借賞云归堞，留歡月在窗。","不知名教乐，千載與誰雙。"]', '诗', 'shi', '', NULL, '奉和顏使君真卿修韻海畢州中重宴 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b53657-010b-4711-969f-c489cace7eb5', '晦日陪顏使君白蘋洲集', '晦日陪顏使君白蘋洲集', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["南朝分古郡，山水似湘東。","堤月吳風在，湔裾楚客同。","桂寒初結斾，蘋小欲成叢。","時晦佳游促，高歌聽未終。"]', '["南朝分古郡，山水似湘东。","堤月吳风在，湔裾楚客同。","桂寒初結斾，蘋小欲成叢。","时晦佳游促，高歌听未終。"]', '诗', 'shi', '', NULL, '晦日陪顏使君白蘋洲集 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c514d273-5ffb-4e9e-97a1-ca88a4089ca9', '冬至日陪裴端公使君清水堂集', '冬至日陪裴端公使君清水堂集', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["亞歲崇佳宴，華軒照淥波。","渚芳迎氣早，山翠向晴多。","推往知時訓，書祥辨政和。","從公惜日短，留賞夜如何。"]', '["亞歲崇佳宴，华軒照淥波。","渚芳迎氣早，山翠向晴多。","推往知时訓，书祥辨政和。","從公惜日短，留賞夜如何。"]', '诗', 'shi', '', NULL, '冬至日陪裴端公使君清水堂集 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e251843e-76da-430c-949e-eb57d8fdf72a', '陪盧判官水堂夜宴', '陪盧判官水堂夜宴', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["暑氣當宵盡，裴回坐月前。","靜依山堞近，涼入水扉偏。","久是棲林客，初逢佐幕賢。","愛君高野意，烹茗釣淪漣。"]', '["暑氣當宵尽，裴回坐月前。","静依山堞近，涼入水扉偏。","久是棲林客，初逢佐幕賢。","愛君高野意，烹茗釣淪漣。"]', '诗', 'shi', '', NULL, '陪盧判官水堂夜宴 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e1a7b90-3797-4d42-b417-955929adf2b8', '新秋同盧侍御薛員外白蘋洲月夜', '新秋同盧侍御薛員外白蘋洲月夜', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["隔暑蘋洲近，迎涼欲泛舟。","榮從憲府至，喜會夕郎遊。","氣奪滄浪色，風欺汗漫流。","誰言三伏夜，獨此月前秋。"]', '["隔暑蘋洲近，迎涼欲泛舟。","榮從憲府至，喜會夕郎游。","氣奪滄浪色，风欺汗漫流。","誰言三伏夜，独此月前秋。"]', '诗', 'shi', '', NULL, '新秋同盧侍御薛員外白蘋洲月夜 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba140ceb-52a5-4e61-8638-2752d36c2b5d', '夏日集裴錄事北亭避暑', '夏日集裴錄事北亭避暑', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["前林夏雨歇，爲我生涼風。","一室煩暑外，衆山清景中。","忘歸親野水，適性許雲鴻。","蕭散都曹吏，還將靜者同。"]', '["前林夏雨歇，爲我生涼风。","一室煩暑外，衆山清景中。","忘归親野水，適性許云鴻。","蕭散都曹吏，還將静者同。"]', '诗', 'shi', '', NULL, '夏日集裴錄事北亭避暑 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9089124b-cc0b-4c73-9ed6-0fde025402c5', '與王錄事會張徵君姊妹鍊師院翫雪兼懷清會上人', '與王錄事會張徵君姊妹鍊師院翫雪兼懷清會上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["何意廉從事，還來會默仙。","寒空驚雪徧，春意入歌偏。","瑤草三花發，瓊林七葉連。","飄颻過柳寺，應滿譯經前。"]', '["何意廉從事，還来會默仙。","寒空驚雪徧，春意入歌偏。","瑤草三花發，瓊林七葉連。","飄颻過柳寺，應满譯經前。"]', '诗', 'shi', '', NULL, '與王錄事會張徵君姊妹鍊師院翫雪兼懷清會上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e11e0e1-e387-49ca-82ca-9192b10275ba', '和李侍御萼歲初夜集處士書閣', '和李侍御萼歲初夜集处士书閣', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["遲賢心置閣，高意此郊居。","古徑行春早，新窗見月初。","放歌還倚瑟，講道亦觀書。","爲我留禪位，來逢此會疎。"]', '["遲賢心置閣，高意此郊居。","古徑行春早，新窗见月初。","放歌還倚瑟，講道亦观书。","爲我留禪位，来逢此會疎。"]', '诗', 'shi', '', NULL, '和李侍御萼歲初夜集處士書閣 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67ee9790-feb6-464f-9867-7bb5deca29a3', '湯評事衡水亭會覺禪師', '湯評事衡水亭會覺禪師', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山侶相逢少，清晨會水亭。","雪晴松葉翠，煙暖藥苗青。","靜對滄洲鶴，閑看古寺經。","應憐叩關子，了義共心冥。"]', '["山侶相逢少，清晨會水亭。","雪晴松葉翠，煙暖藥苗青。","静对滄洲鹤，闲看古寺經。","應怜叩关子，了義共心冥。"]', '诗', 'shi', '', NULL, '湯評事衡水亭會覺禪師 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ab2763a-0c33-4c93-8fa5-c19bd50904cd', '與朝陽山人張朝夜集湖亭賦得各言其志', '與朝陽山人張朝夜集湖亭賦得各言其志', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["洞庭孤月在，秋色望無邊。","零露積衰草，寒螿鳴古田。","茫茫區中想，寂寂塵外緣。","從此悟浮世，胡爲傷暮年。"]', '["洞庭孤月在，秋色望無邊。","零露積衰草，寒螿鳴古田。","茫茫區中想，寂寂塵外緣。","從此悟浮世，胡爲傷暮年。"]', '诗', 'shi', '', NULL, '與朝陽山人張朝夜集湖亭賦得各言其志 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c17be4a5-897c-4042-968b-bd47ab088643', '晦夜李侍御萼宅集招潘述湯衡海上人飲茶賦', '晦夜李侍御萼宅集招潘述湯衡海上人饮茶賦', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["晦夜不生月，琴軒猶爲開。","墻東隱者在，淇上逸僧來。","茗愛傳花飲，詩看卷素裁。","風流高此會，曉景屢裴回。"]', '["晦夜不生月，琴軒猶爲开。","墻东隐者在，淇上逸僧来。","茗愛傳花饮，诗看卷素裁。","风流高此會，晓景屢裴回。"]', '诗', 'shi', '', NULL, '晦夜李侍御萼宅集招潘述湯衡海上人飲茶賦 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1827e6bc-7165-4d01-be72-2dba106bde6b', '寄昱上人上方居', '寄昱上人上方居', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["厭向人間住，逢山欲懶歸。","片雲閑似我，日日在禪扉。","地靜松陰徧，門空鳥語稀。","夜涼疎磬盡，師友自相依。"]', '["厭向人间住，逢山欲懶归。","片云闲似我，日日在禪扉。","地静松陰徧，门空鸟語稀。","夜涼疎磬尽，師友自相依。"]', '诗', 'shi', '', NULL, '寄昱上人上方居 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e620d71-ca49-4c19-bb6d-1c8666de7ad5', '夏日與綦毋居士昱上人納涼', '夏日與綦毋居士昱上人納涼', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["爲依爐峰住，境勝增道情。","涼日暑不變，空門風自清。","坐援香實近，轉愛綠蕪生。","宗炳青霞士，如何知我名。"]', '["爲依爐峰住，境勝增道情。","涼日暑不变，空门风自清。","坐援香實近，轉愛綠蕪生。","宗炳青霞士，如何知我名。"]', '诗', 'shi', '', NULL, '夏日與綦毋居士昱上人納涼 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cf38d83-ee7f-4f5d-b670-c2115430cb34', '建元寺集皇甫侍御書閣', '建元寺集皇甫侍御书閣', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["不因居佛里，無事得相逢。","名重朝端望，身高俗外蹤。","機閑看淨水，境寂聽疎鐘。","宣室恩長在，知君志未從。"]', '["不因居佛里，無事得相逢。","名重朝端望，身高俗外蹤。","機闲看淨水，境寂听疎鐘。","宣室恩长在，知君志未從。"]', '诗', 'shi', '', NULL, '建元寺集皇甫侍御書閣 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af34f329-2874-4117-977d-b34dd5625b48', '郭北尋徐主簿別業', '郭北尋徐主簿別業', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["近依城北住，幽遠少人知。","積雪行深巷，閑雲繞古籬。","竹花冬更發，橙實晚仍垂。","還共巖中鶴，今朝下淥池。"]', '["近依城北住，幽远少人知。","積雪行深巷，闲云繞古籬。","竹花冬更發，橙實晚仍垂。","還共巖中鹤，今朝下淥池。"]', '诗', 'shi', '', NULL, '郭北尋徐主簿別業 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20899a0e-5908-485d-93da-593e01c572da', '題報德寺清幽上人西峰', '題報德寺清幽上人西峰', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["陳世凋亡後，仁祠識舊山。","帝鄉喬木在，空見白雲還。","雙塔寒林外，三陵暮雨間。","此中難戰勝，君獨啓禪關。"]', '["陳世凋亡後，仁祠識旧山。","帝乡喬木在，空见白云還。","雙塔寒林外，三陵暮雨间。","此中难戰勝，君独啓禪关。"]', '诗', 'shi', '', NULL, '題報德寺清幽上人西峰 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a70afd0-2a5e-4580-a511-4bfe77d229f6', '題鄭谷江畔桐齋', '題鄭谷江畔桐斋', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["客齋開別住，坐占綠江濆。","流水非外物，閑雲長屬君。","浮榮未可累，曠達若爲羣。","風起高梧下，清弦日日聞。"]', '["客斋开別住，坐占綠江濆。","流水非外物，闲云长屬君。","浮榮未可累，曠達若爲羣。","风起高梧下，清弦日日闻。"]', '诗', 'shi', '', NULL, '題鄭谷江畔桐齋 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73bd06a0-e5b1-4a6e-aaf4-666792e20efa', '和閻士和李蕙冬夜重集', '和閻士和李蕙冬夜重集', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["郡理日閑曠，洗心宿香峰。","雙林秋見月，萬壑靜聞鐘。","珮玉行山翠，交麾動水容。","如何股肱守，塵外得相從。"]', '["郡理日闲曠，洗心宿香峰。","雙林秋见月，万壑静闻鐘。","珮玉行山翠，交麾动水容。","如何股肱守，塵外得相從。"]', '诗', 'shi', '', NULL, '和閻士和李蕙冬夜重集 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21729050-31ef-4fa3-8dfb-cc7ce524225c', '春日陪顏使君真卿皇甫曾西亭重會韻海諸生', '春日陪顏使君真卿皇甫曾西亭重會韻海諸生', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["爲重南臺客，朝朝會魯儒。","暄風衆木變，清景片雲無。","峰翠飄簷下，溪光照座隅。","不將簪艾隔，知與道情俱。"]', '["爲重南台客，朝朝會魯儒。","暄风衆木变，清景片云無。","峰翠飄簷下，溪光照座隅。","不將簪艾隔，知與道情俱。"]', '诗', 'shi', '', NULL, '春日陪顏使君真卿皇甫曾西亭重會韻海諸生 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c56ba10-a01b-4cff-9a74-528e69ca54d3', '寒食日同陸處士行報德寺宿解公房', '寒食日同陸处士行報德寺宿解公房', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["古寺章陵下，潛公住幾年。","安心生輭草，灌頂引春泉。","寂寂傳燈地，寥寥禁火天。","世間多暗室，白日爲誰懸。"]', '["古寺章陵下，潛公住幾年。","安心生輭草，灌頂引春泉。","寂寂傳灯地，寥寥禁火天。","世间多暗室，白日爲誰懸。"]', '诗', 'shi', '', NULL, '寒食日同陸處士行報德寺宿解公房 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a9a70f9-1a52-4e48-8327-d14e2f94af41', '兵馬曹季良宅夜集', '兵马曹季良宅夜集', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["清景不可失，尋君趣有餘。","身高避事後，道長問心初。","出處名則異，遊從跡何疎。","吟看刻盡燭，笑卷讀殘書。","露彩生筆硯，風音入庭除。","平明仙侶散，觳觫動迴車。"]', '["清景不可失，尋君趣有餘。","身高避事後，道长问心初。","出处名則異，游從跡何疎。","吟看刻尽燭，笑卷读殘书。","露彩生笔硯，风音入庭除。","平明仙侶散，觳觫动迴车。"]', '诗', 'shi', '', NULL, '兵馬曹季良宅夜集 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('498fbb85-8e95-41cf-9320-31baa99f5049', '同李侍御萼李判官集陸處士羽新宅', '同李侍御萼李判官集陸处士羽新宅', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["素風千戶敵，新語陸生能。","借宅心常遠，移籬力更弘。","釣絲初種竹，衣帶近裁藤。","戎佐推兄弟，詩流得友朋。","柳陰容過客，花徑許招僧。","不爲墻東隱，人家到未曾。"]', '["素风千戶敵，新語陸生能。","借宅心常远，移籬力更弘。","釣絲初種竹，衣带近裁藤。","戎佐推兄弟，诗流得友朋。","柳陰容過客，花徑許招僧。","不爲墻东隐，人家到未曾。"]', '诗', 'shi', '', NULL, '同李侍御萼李判官集陸處士羽新宅 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f75a1947-d95a-4243-bcc8-67e306914348', '題報恩寺惟照上人房', '題報恩寺惟照上人房', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["上界雨色乾，涼宮日遲遲。","水文披菡萏，山翠動罘罳。","中有清真子，愔愔步閑墀。","手縈頗黎縷，願證黃金姿。","旋草堦下生，看心當此時。"]', '["上界雨色乾，涼宮日遲遲。","水文披菡萏，山翠动罘罳。","中有清真子，愔愔步闲墀。","手縈頗黎縷，願證黄金姿。","旋草堦下生，看心當此时。"]', '诗', 'shi', '', NULL, '題報恩寺惟照上人房 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f33f90-b7d7-43e1-a340-33167ea05bcf', '尋天目徐君', '尋天目徐君', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["常見仙翁變姓名，豈知松子號初平。","逢人不道往來處，賣藥還將雞犬行。","獨鶴天邊俱得性，浮雲世上共無情。","三花落地君猶在，笑撫安期昨日生。"]', '["常见仙翁变姓名，豈知松子號初平。","逢人不道往来处，賣藥還將雞犬行。","独鹤天邊俱得性，浮云世上共無情。","三花落地君猶在，笑撫安期昨日生。"]', '诗', 'shi', '', NULL, '尋天目徐君 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d6c53ef-dfc3-41c7-aad3-36ef946709fa', '同李著作縱題塵外上人院', '同李著作縱題塵外上人院', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["百緣唯有什公瓶，萬法但看一字經。","從遣鳥喧心不動，任教香醉境常冥。","蓮花天晝浮雲卷，貝葉宮春好月停。","禪伴欲邀何著作，空音宜向夜中聽。"]', '["百緣唯有什公瓶，万法但看一字經。","從遣鸟喧心不动，任教香醉境常冥。","蓮花天晝浮云卷，貝葉宮春好月停。","禪伴欲邀何著作，空音宜向夜中听。"]', '诗', 'shi', '', NULL, '同李著作縱題塵外上人院 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b222621-d127-4df5-b8a9-c1499378aa19', '題周諫別業', '題周諫別業', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["隱身苕上欲如何，不著青袍愛綠蘿。","柳巷任疎容馬入，水籬從破許船過。","昂藏獨鶴閑心遠，寂歷秋花野意多。","若訪禪齋遙可見，竹窗書幌共煙波。"]', '["隐身苕上欲如何，不著青袍愛綠蘿。","柳巷任疎容马入，水籬從破許船過。","昂藏独鹤闲心远，寂歷秋花野意多。","若訪禪斋遙可见，竹窗书幌共煙波。"]', '诗', 'shi', '', NULL, '題周諫別業 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b7720d-a738-4d2b-b713-20e395c0de75', '同李中丞洪水亭夜集', '同李中丞洪水亭夜集', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["佳人但莫吹參差，正憐月色生酒巵。","山公取醉不關我，爲愛尊前白鷺鶿。"]', '["佳人但莫吹參差，正怜月色生酒巵。","山公取醉不关我，爲愛尊前白鷺鶿。"]', '诗', 'shi', '', NULL, '同李中丞洪水亭夜集 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d11823fe-453a-4fe1-a0cd-985a7a328ce9', '題秦系山人麗句亭', '題秦系山人丽句亭', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["獨將詩教領諸生，但看青山不愛名。","滿院竹聲堪愈疾，亂牀花片足忘情。"]', '["独將诗教領諸生，但看青山不愛名。","满院竹声堪愈疾，亂牀花片足忘情。"]', '诗', 'shi', '', NULL, '題秦系山人麗句亭 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b6e211-3145-43ac-989a-90646f04b0d2', '春夜集陸處士居翫月', '春夜集陸处士居翫月', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["欲賞芳菲肯待辰，忘情人訪有情人。","西林可是無清景，祗爲忘情不記春。"]', '["欲賞芳菲肯待辰，忘情人訪有情人。","西林可是無清景，祗爲忘情不記春。"]', '诗', 'shi', '', NULL, '春夜集陸處士居翫月 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc174219-f611-4024-8870-625b9f426ea5', '寄題雲門寺梵月無側房', '寄題云门寺梵月無側房', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["越山千萬雲門絕，西僧貌古還名月。","清朝掃石行道歸，林下眠禪看松雪。"]', '["越山千万云门絕，西僧貌古還名月。","清朝掃石行道归，林下眠禪看松雪。"]', '诗', 'shi', '', NULL, '寄題雲門寺梵月無側房 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d861c19-984d-4c03-b441-167e99ca9c2c', '法華寺上方題江上人禪空', '法华寺上方題江上人禪空', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["路入松聲遠更奇，山光水色共參差。","中峰禪寂一僧在，坐對梁朝老桂枝。"]', '["路入松声远更奇，山光水色共參差。","中峰禪寂一僧在，坐对梁朝老桂枝。"]', '诗', 'shi', '', NULL, '法華寺上方題江上人禪空 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8712a9d5-1263-4584-9e47-f6e0234ca731', '冬日山行過薛徵君', '冬日山行過薛徵君', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["我行倦修坂，四顧無平陸。","雨霽鳴鷹鸇，天寒聚麋鹿。","幽人訪名士，家在南岡曲。","菜實縈小園，稻花遶山屋。","深居寡憂悔，勝境怡耳目。","徵心尚與我，永言謝浮俗。"]', '["我行倦修坂，四顧無平陸。","雨霽鳴鷹鸇，天寒聚麋鹿。","幽人訪名士，家在南岡曲。","菜實縈小园，稻花遶山屋。","深居寡憂悔，勝境怡耳目。","徵心尚與我，永言謝浮俗。"]', '诗', 'shi', '', NULL, '冬日山行過薛徵君 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8e32064-bcb3-41ca-ad12-5a40f34bb4a0', '往丹陽尋陸處士不遇', '往丹陽尋陸处士不遇', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["遠客殊未歸，我來幾惆悵。","叩關一日不見人，繞屋寒花笑相向。","寒花寂寂徧荒阡，柳色蕭蕭愁暮蟬。","行人無數不相識，獨立雲陽古驛邊。","鳳翅山中思本寺，魚竿村口望歸船。","歸船不見見寒煙，離心遠水共悠然。","他日相期那可定，閑僧著處即經年。"]', '["远客殊未归，我来幾惆悵。","叩关一日不见人，繞屋寒花笑相向。","寒花寂寂徧荒阡，柳色蕭蕭愁暮蟬。","行人無數不相識，独立云陽古驛邊。","鳳翅山中思本寺，鱼竿村口望归船。","归船不见见寒煙，離心远水共悠然。","他日相期那可定，闲僧著处即經年。"]', '诗', 'shi', '', NULL, '往丹陽尋陸處士不遇 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1906765-01c9-4567-857d-716acaf87341', '集湯評事衡湖上望微雨', '集湯評事衡湖上望微雨', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["蒼涼遠景中，雨色緣山有。","雲送滿洞庭，風吹繞楊柳。","蕭蕭解輕袂，盡日隨林叟。"]', '["蒼涼远景中，雨色緣山有。","云送满洞庭，风吹繞楊柳。","蕭蕭解轻袂，尽日隨林叟。"]', '诗', 'shi', '', NULL, '集湯評事衡湖上望微雨 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2dc5eb-1d86-45ff-bf5f-11d0844c3c52', '九日與陸處士羽飲茶', '九日與陸处士羽饮茶', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["九日山僧院，東籬菊也黃。","俗人多泛酒，誰解助茶香。"]', '["九日山僧院，东籬菊也黄。","俗人多泛酒，誰解助茶香。"]', '诗', 'shi', '', NULL, '九日與陸處士羽飲茶 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('021c0196-f295-4ddb-b2c9-d6c54735c1cb', '夜過康錄事造會兄弟', '夜過康錄事造會兄弟', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["愛君門館夜來清，瓊樹雙枝是弟兄。","月在詩家偏足思，風過客位更多情。"]', '["愛君门館夜来清，瓊樹雙枝是弟兄。","月在诗家偏足思，风過客位更多情。"]', '诗', 'shi', '', NULL, '夜過康錄事造會兄弟 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41f0ddee-825d-4060-9ef9-b05888155f32', '題沈少府書齋', '題沈少府书斋', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["不下南昌縣，書齋每日閑。","野花當砌落，溪鳥遂人還。","有興常臨水，無時不見山。","千峰數可盡，不出小窗間。"]', '["不下南昌縣，书斋每日闲。","野花當砌落，溪鸟遂人還。","有兴常臨水，無时不见山。","千峰數可尽，不出小窗间。"]', '诗', 'shi', '', NULL, '題沈少府書齋 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35811b12-3828-42e8-8bc1-384b8cdfc57b', '春夜與諸公同宴呈陸郎中', '春夜與諸公同宴呈陸郎中', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["南國宴佳賓，交情老倍親。","月慙紅淚燭，花笑白頭人。","寶瑟絚餘怨，瓊枝不讓春。","更聞歌子夜，桃李豔妝新。"]', '["南国宴佳賓，交情老倍親。","月慙紅泪燭，花笑白头人。","寶瑟絚餘怨，瓊枝不讓春。","更闻歌子夜，桃李豔妝新。"]', '诗', 'shi', '', NULL, '春夜與諸公同宴呈陸郎中 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e549f0c3-e351-42ba-b739-c49b62bb8680', '九日阻雨簡高侍御', '九日阻雨簡高侍御', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["江上重雲起，何曾裛□塵。","不能成落帽，翻欲更摧巾。","素髮閑依枕，黃花暗待人。","且應攜下價，芒屨就諸鄰。"]', '["江上重云起，何曾裛□塵。","不能成落帽，翻欲更摧巾。","素髮闲依枕，黄花暗待人。","且應携下價，芒屨就諸鄰。"]', '诗', 'shi', '', NULL, '九日阻雨簡高侍御 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fab5260-1455-49e8-868a-9ac4fb558bfd', '晚春尋桃源觀', '晚春尋桃源观', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["武陵何處訪仙鄉，古觀雲根路已荒。","細草擁壇人跡絕，落花沈磵水流香。","山深有雨寒猶在，松老無風韻亦長。","全覺此身離俗境，玄機亦可照迷方。"]', '["武陵何处訪仙乡，古观云根路已荒。","細草擁壇人跡絕，落花沈磵水流香。","山深有雨寒猶在，松老無风韻亦长。","全覺此身離俗境，玄機亦可照迷方。"]', '诗', 'shi', '', NULL, '晚春尋桃源觀 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4bef6d-003b-4b4b-9add-8e87825166cd', '同盧使君幼平郊外送閻侍御歸臺', '同盧使君幼平郊外送閻侍御归台', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["留餞飛旌駐，離亭草色間。","柏臺今上客，竹使舊朝班。","日落東西水，天寒遠近山。","古江分楚望，殘柳入隋關。","戀闕心常積，迴軒日不閑。","芳辰倚門道，猶得及春還。"]', '["留餞飞旌駐，離亭草色间。","柏台今上客，竹使旧朝班。","日落东西水，天寒远近山。","古江分楚望，殘柳入隋关。","戀闕心常積，迴軒日不闲。","芳辰倚门道，猶得及春還。"]', '诗', 'shi', '', NULL, '同盧使君幼平郊外送閻侍御歸臺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1478521e-b545-4d8c-9775-c9063f3f7c70', '送梁拾遺肅歸朝', '送梁拾遺肅归朝', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["明主重文諫，才臣出江東。","束書辭東山，改服臨北風。","萬里望皇邑，九重當曙空。","天開芙蓉闕，日上蒲桃宮。","天子初未起，金閨籍先通。","身逢軒轅世，名貴鴛鸞中。","故人榮此別，何用悲絲桐。"]', '["明主重文諫，才臣出江东。","束书辞东山，改服臨北风。","万里望皇邑，九重當曙空。","天开芙蓉闕，日上蒲桃宮。","天子初未起，金閨籍先通。","身逢軒轅世，名貴鴛鸾中。","故人榮此別，何用悲絲桐。"]', '诗', 'shi', '', NULL, '送梁拾遺肅歸朝 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62514170-aa7c-4664-afd8-6bddb4b6c65e', '奉陪楊使君頊送段校書赴南海幕', '奉陪楊使君頊送段校书赴南海幕', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["碩賢靜廣州，信爲天下貞。","屈茲大將佐，藉彼延閣英。","聲動柳吳興，郊餞意不輕。","吾知段夫子，高論關蒼生。","處以得爲藩，出則道可行。","遙知南樓會，新景當詩情。","天高林瘴洗，秋遠海色清。","時泰罷飛檄，唯應頌公成。"]', '["碩賢静廣州，信爲天下貞。","屈茲大將佐，藉彼延閣英。","声动柳吳兴，郊餞意不轻。","吾知段夫子，高論关蒼生。","处以得爲藩，出則道可行。","遙知南楼會，新景當诗情。","天高林瘴洗，秋远海色清。","时泰罷飞檄，唯應頌公成。"]', '诗', 'shi', '', NULL, '奉陪楊使君頊送段校書赴南海幕 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832673b1-038f-4eda-bc92-10b938233652', '送陸侍御士佳赴上京', '送陸侍御士佳赴上京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["長安三千里，喜行不言永。","清路黃塵飛，大河滄流靜。","更懷西川府，主公昔和鼎。","伊鬱瑤瑟情，威遲花驄影。","此時已難別，日又無停景。","出餞闕相從，心隨過前嶺。"]', '["长安三千里，喜行不言永。","清路黄塵飞，大河滄流静。","更懷西川府，主公昔和鼎。","伊鬱瑤瑟情，威遲花驄影。","此时已难別，日又無停景。","出餞闕相從，心隨過前嶺。"]', '诗', 'shi', '', NULL, '送陸侍御士佳赴上京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f2689d-0bfc-4b06-b78f-5486bd4ddad2', '奉陪顏使君真卿登峴山送張侍御嚴歸臺', '奉陪顏使君真卿登峴山送張侍御嚴归台', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["峴首千里情，北轅自茲發。","煙霞正登覽，簪筆限趨謁。","黃鶴望天衢，白雲歸帝闕。","客心南浦柳，離思西樓月。","留賞景不延，感時芳易歇。","他晨有山信，一爲訪林樾。"]', '["峴首千里情，北轅自茲發。","煙霞正登覽，簪笔限趨謁。","黄鹤望天衢，白云归帝闕。","客心南浦柳，離思西楼月。","留賞景不延，感时芳易歇。","他晨有山信，一爲訪林樾。"]', '诗', 'shi', '', NULL, '奉陪顏使君真卿登峴山送張侍御嚴歸臺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8161a068-be19-4104-a253-41c822f3774b', '酬元主簿子球別贈', '酬元主簿子球別贈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["故人方遠適，訪我陳別情。","此夜偶禪室，一言了無生。","覽君緘中寶，如搴清玉瑛。","胡爲蘊高價，歲晚徒營營。","辭秩貧且病，何人見艱貞。","出無黃金橐，空歌白苧行。","威遲策駑馬，獨望故關樹。","渺渺千里心，春風起中路。","近聞新拜命，鸞鳳猶棲棘。","勸君寄一枝，且養冥冥翼。","甘泉多竹花，明年待君食。"]', '["故人方远適，訪我陳別情。","此夜偶禪室，一言了無生。","覽君緘中寶，如搴清玉瑛。","胡爲蘊高價，歲晚徒營營。","辞秩貧且病，何人见艱貞。","出無黄金橐，空歌白苧行。","威遲策駑马，独望故关樹。","渺渺千里心，春风起中路。","近闻新拜命，鸾鳳猶棲棘。","勸君寄一枝，且養冥冥翼。","甘泉多竹花，明年待君食。"]', '诗', 'shi', '', NULL, '酬元主簿子球別贈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2516d4b3-0226-4238-8134-d7d4e84a86d7', '荅道素上人別', '荅道素上人別', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春色徧遠道，寂寞閩中行。","碧水何渺渺，白雲亦英英。","離人不可望，日暮芳洲情。","黃鶴有逸翮，翹首白雲傾。","欲爲山中侶，肯祕遼天聲。","藍縷真子褐，葳蕤近臣纓。","以茲奪爾懷，常恐道不成。","吾門弟子中，不減惠休名。","一性研已遠，五言功更精。","從君汗漫遊，莫廢學無生。","忍草肯搖落，禪枝不枯榮。","采采慰長路，知吾心不輕。","幻情有去住，真性無離別。","留取老桂枝，歸來共攀折。"]', '["春色徧远道，寂寞閩中行。","碧水何渺渺，白云亦英英。","離人不可望，日暮芳洲情。","黄鹤有逸翮，翹首白云傾。","欲爲山中侶，肯祕遼天声。","藍縷真子褐，葳蕤近臣纓。","以茲奪爾懷，常恐道不成。","吾门弟子中，不減惠休名。","一性研已远，五言功更精。","從君汗漫游，莫廢学無生。","忍草肯搖落，禪枝不枯榮。","采采慰长路，知吾心不轻。","幻情有去住，真性無離別。","留取老桂枝，归来共攀折。"]', '诗', 'shi', '', NULL, '荅道素上人別 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc888ce8-b4db-485c-9855-061b240845e0', '霅溪館送韓明府章辭滿歸', '霅溪館送韓明府章辞满归', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["洛令從告還，故人東門餞。","惠愛三年積，軒車一夜遠。","曉月離館空，秋風故山晚。","榮君有嘉薦，顧我阻遊衍。","宿昔峰頂心，依依不可卷。"]', '["洛令從告還，故人东门餞。","惠愛三年積，軒车一夜远。","晓月離館空，秋风故山晚。","榮君有嘉薦，顧我阻游衍。","宿昔峰頂心，依依不可卷。"]', '诗', 'shi', '', NULL, '霅溪館送韓明府章辭滿歸 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33cf667a-649b-4f76-9009-48b6172cf325', '送穆寂赴舉', '送穆寂赴舉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["天子錫玄纁，傾山禮隱淪。","君拋青霞去，榮資觀國賓。","劒光既陸離，瓊彩何璘玢。","夙駕別情遠，商弦秋意新。","冥冥鴻鵠姿，數尺看蒼旻。","殘寇近宋郊，西行惡飆塵。","立身素耿介，處難思經綸。","春府搜才日，高科得一人。"]', '["天子錫玄纁，傾山禮隐淪。","君拋青霞去，榮資观国賓。","劒光既陸離，瓊彩何璘玢。","夙駕別情远，商弦秋意新。","冥冥鴻鵠姿，數尺看蒼旻。","殘寇近宋郊，西行惡飆塵。","立身素耿介，处难思經綸。","春府搜才日，高科得一人。"]', '诗', 'shi', '', NULL, '送穆寂赴舉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f59e15b-fd8d-48a8-a994-e478501e2d0e', '送張彝歸長沙', '送張彝归长沙', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["早聞凌雲彩，謂在鴛鷺儔。","華髮始相遇，滄江仍旅遊。","策名忘苟進，澹慮輕所求。","常服遠遊誡，緬懷經世謀。","片帆背風渚，萬里還湘洲。","別望荆雲積，歸心漢水流。","蘭苕行采采，桂櫂思悠悠。","宿昔無機者，爲君動離憂。"]', '["早闻凌云彩，謂在鴛鷺儔。","华髮始相遇，滄江仍旅游。","策名忘苟進，澹慮轻所求。","常服远游誡，緬懷經世謀。","片帆背风渚，万里還湘洲。","別望荆云積，归心漢水流。","蘭苕行采采，桂櫂思悠悠。","宿昔無機者，爲君动離憂。"]', '诗', 'shi', '', NULL, '送張彝歸長沙 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eacea3d6-d9cd-4f35-836d-8b27480a3fc2', '秋日毘陵南寺送潘述之揚州', '秋日毘陵南寺送潘述之揚州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["孤客秋易傷，嘶蟬靜仍續。","佳晨亦已屢，歡會常不足。","禪地非路岐，我心豈羈束。","情生遠別時，坐恨清景促。","望中千里隔，暮歸西山曲。","蕭條月中道，彩蒨原上綠。","不見同心人，幽懷增躑躅。"]', '["孤客秋易傷，嘶蟬静仍續。","佳晨亦已屢，歡會常不足。","禪地非路岐，我心豈羈束。","情生远別时，坐恨清景促。","望中千里隔，暮归西山曲。","蕭條月中道，彩蒨原上綠。","不见同心人，幽懷增躑躅。"]', '诗', 'shi', '', NULL, '秋日毘陵南寺送潘述之揚州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50bd8261-d9b9-4f9b-9c4e-7520bfb16325', '春日又送潘述之揚州', '春日又送潘述之揚州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["別渚望邗城，岐路春日徧。","柔風吹楊柳，芳景流郊甸。","日日東林期，今夕異鄉縣。","文房曠佳士，禪室阻清盼。","離恨奪賞心，不得諧所願。","莫憶山中人，碧雲遙可見。"]', '["別渚望邗城，岐路春日徧。","柔风吹楊柳，芳景流郊甸。","日日东林期，今夕異乡縣。","文房曠佳士，禪室阻清盼。","離恨奪賞心，不得諧所願。","莫憶山中人，碧云遙可见。"]', '诗', 'shi', '', NULL, '春日又送潘述之揚州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aca00475-41bd-4e9e-a4f6-5419b625d36d', '新秋送盧判官', '新秋送盧判官', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["故人念宿昔，欲別增遠情。","入座炎氣屏，爲君秋景清。","繇來空山客，不怨離弦聲。","唯有暮蟬起，相思碧雲生。"]', '["故人念宿昔，欲別增远情。","入座炎氣屏，爲君秋景清。","繇来空山客，不怨離弦声。","唯有暮蟬起，相思碧云生。"]', '诗', 'shi', '', NULL, '新秋送盧判官 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd23f806-a8a0-4636-8a7c-03be30ef8f7d', '奉送袁高使君詔徵赴行在效曹劉體', '奉送袁高使君詔徵赴行在效曹劉體', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["皇心亭毒廣，蝥賊皆陶甄。","未刈蚩尤旗，方同軒后年。","天子幸漢中，轘轅阻氛煙。","璽書召幕牧，名在列岳仙。","國難倚長城，廟謀資大賢。","清損休汝騎，仁留述職篇。","遐路渺天末，繁笳思河邊。","飾徒促遠期，祗命赴急宣。","謏才豈足稱，深仁顧何偏。","那堪臨流意，千里望旗旃。"]', '["皇心亭毒廣，蝥賊皆陶甄。","未刈蚩尤旗，方同軒后年。","天子幸漢中，轘轅阻氛煙。","璽书召幕牧，名在列岳仙。","国难倚长城，廟謀資大賢。","清損休汝騎，仁留述職篇。","遐路渺天末，繁笳思河邊。","飾徒促远期，祗命赴急宣。","謏才豈足稱，深仁顧何偏。","那堪臨流意，千里望旗旃。"]', '诗', 'shi', '', NULL, '奉送袁高使君詔徵赴行在效曹劉體 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d659d5-e351-4d2f-9bca-2918e6873fb4', '奉送陸中丞長源詔徵入朝', '奉送陸中丞长源詔徵入朝', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["詔下酇侯幕，徵賢寵上勳。","才當持漢典，道可至堯君。","藩牧今榮餞，詩流此盛文。","水從吳渚別，樹向楚門分。","宿寺期嘉月，看山識故雲。","歸心復何奈，怊悵在江濆。"]', '["詔下酇侯幕，徵賢寵上勳。","才當持漢典，道可至堯君。","藩牧今榮餞，诗流此盛文。","水從吳渚別，樹向楚门分。","宿寺期嘉月，看山識故云。","归心复何奈，怊悵在江濆。"]', '诗', 'shi', '', NULL, '奉送陸中丞長源詔徵入朝 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12bba4b4-3689-4142-9366-1334d7305fc8', '奉送李中丞道昌入朝', '奉送李中丞道昌入朝', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["文憲中司盛，恩榮外鎮崇。","諸侯皆取則，八使獨推功。","詔喜新銜鳳，車看舊飾熊。","去思今武子，餘教昔文翁。","清在如江水，仁留是國風。","光徵二千石，掃第望司空。"]', '["文憲中司盛，恩榮外鎮崇。","諸侯皆取則，八使独推功。","詔喜新銜鳳，车看旧飾熊。","去思今武子，餘教昔文翁。","清在如江水，仁留是国风。","光徵二千石，掃第望司空。"]', '诗', 'shi', '', NULL, '奉送李中丞道昌入朝 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf59638-deea-4b7e-b6e6-e90266fe4a70', '冬日送顏延之明府撫州覲叔父', '冬日送顏延之明府撫州覲叔父', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["臨川千里別，惆悵上津橋。","日暮人歸盡，山空雪未消。","鄉雲心渺渺，楚水路遙遙。","林下方歡會，山中獨寂寥。","天寒驚斷鴈，江信望迴潮。","歲晚流芳歇，思君在此宵。"]', '["臨川千里別，惆悵上津橋。","日暮人归尽，山空雪未消。","乡云心渺渺，楚水路遙遙。","林下方歡會，山中独寂寥。","天寒驚斷鴈，江信望迴潮。","歲晚流芳歇，思君在此宵。"]', '诗', 'shi', '', NULL, '冬日送顏延之明府撫州覲叔父 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a15bf243-f953-4f89-b66f-9143b5e47645', '送關小師還金陵', '送关小師還金陵', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["如何有歸思，愛別欲忘難。","白鷺沙洲晚，青龍水寺寒。","蕉花鋪淨地，桂子落空壇。","持此心爲境，應堪月夜看。"]', '["如何有归思，愛別欲忘难。","白鷺沙洲晚，青龙水寺寒。","蕉花鋪淨地，桂子落空壇。","持此心爲境，應堪月夜看。"]', '诗', 'shi', '', NULL, '送關小師還金陵 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78063f93-fa73-41bd-91fb-55554f27c210', '峴山送裴秀才赴舉', '峴山送裴秀才赴舉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["漢家招秀士，峴上送君行。","萬里見秋色，兩河傷遠情。","王師出西鎬，虜寇避東平。","天府登名後，迴看楚水清。"]', '["漢家招秀士，峴上送君行。","万里见秋色，兩河傷远情。","王師出西鎬，虜寇避东平。","天府登名後，迴看楚水清。"]', '诗', 'shi', '', NULL, '峴山送裴秀才赴舉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a759495-20b9-4da4-8905-bd32aa2be24c', '酬別襄陽詩僧少微', '酬別襄陽诗僧少微', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["證心何有夢，示說夢歸頻。","文字齎秦本，詩騷學楚人。","蘭開衣上色，柳向手中春。","別後須相見，浮雲是我身。"]', '["證心何有梦，示说梦归頻。","文字齎秦本，诗騷学楚人。","蘭开衣上色，柳向手中春。","別後須相见，浮云是我身。"]', '诗', 'shi', '', NULL, '酬別襄陽詩僧少微 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbad6d4f-0e8c-4418-acd9-c215f801476a', '送契上人遊揚州', '送契上人游揚州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["西陵古江口，遠見東揚州。","淥水不同泛，春山應獨遊。","尋僧白巖寺，望月謝家樓。","宿昔心期在，人寰非久留。"]', '["西陵古江口，远见东揚州。","淥水不同泛，春山應独游。","尋僧白巖寺，望月謝家楼。","宿昔心期在，人寰非久留。"]', '诗', 'shi', '', NULL, '送契上人遊揚州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86bc6eb7-4e17-4174-9a17-877b3f6b8dbd', '送德清衛明府赴選', '送德清衛明府赴選', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["八使慎求能，東人獨薦君。","身猶千里限，名已九霄聞。","遠路翻喜別，離言暫惜分。","鳳門多士會，擁佩入卿雲。"]', '["八使慎求能，东人独薦君。","身猶千里限，名已九霄闻。","远路翻喜別，離言暫惜分。","鳳门多士會，擁佩入卿云。"]', '诗', 'shi', '', NULL, '送德清衛明府赴選 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3571ccea-faa3-42ec-bb60-33cbb4d2f112', '送鄭孝廉淮西覲省', '送鄭孝廉淮西覲省', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["離袂翠華滿，晨羞欲早行。","春風生楚樹，曉角發隋城。","野靄濕衣彩，江鴻增客情。","征途不用戒，坐見白波清。"]', '["離袂翠华满，晨羞欲早行。","春风生楚樹，晓角發隋城。","野靄濕衣彩，江鴻增客情。","征途不用戒，坐见白波清。"]', '诗', 'shi', '', NULL, '送鄭孝廉淮西覲省 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14619596-c358-46df-9d2e-73055d921797', '送沈秀才之閩中', '送沈秀才之閩中', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["越客不成歌，春風起淥波。","嶺重寒不到，海近瘴偏多。","野戍桄榔發，人家翡翠過。","翻疑此中好，君問定如何。"]', '["越客不成歌，春风起淥波。","嶺重寒不到，海近瘴偏多。","野戍桄榔發，人家翡翠過。","翻疑此中好，君问定如何。"]', '诗', 'shi', '', NULL, '送沈秀才之閩中 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09aaf32b-3623-4c87-a46e-36a12b7a31d3', '送清會上人遊京', '送清會上人游京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["佳遊限衰疾，一笑向西風。","思見青門外，曾臨素滻東。","峰明雲際寺，日出露寒宮。","行道禪長在，香塵不染空。"]', '["佳游限衰疾，一笑向西风。","思见青门外，曾臨素滻东。","峰明云際寺，日出露寒宮。","行道禪长在，香塵不染空。"]', '诗', 'shi', '', NULL, '送清會上人遊京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af62f9e2-faf7-410c-8315-5a1e186e475e', '送沈居士還太原', '送沈居士還太原', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["辭宮因世難，家族盛南朝。","名重郊居賦，才高獨酌謠。","浪花飄一葉，峰色向三條。","高逸雖成性，弓旌肯忘招。"]', '["辞宮因世难，家族盛南朝。","名重郊居賦，才高独酌謠。","浪花飄一葉，峰色向三條。","高逸雖成性，弓旌肯忘招。"]', '诗', 'shi', '', NULL, '送沈居士還太原 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31c51111-e82a-452f-bf20-7ba6be083999', '同顏使君真卿峴山送李法曹陽冰西上獻書時會有詔徵赴京', '同顏使君真卿峴山送李法曹陽冰西上獻书时會有詔徵赴京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["漢日中郎妙，周王太史才。","雲書捧日去，鶴版下天來。","草見吳洲發，花思御苑開。","羊公惜風景，欲別幾遲迴。"]', '["漢日中郎妙，周王太史才。","云书捧日去，鹤版下天来。","草见吳洲發，花思御苑开。","羊公惜风景，欲別幾遲迴。"]', '诗', 'shi', '', NULL, '同顏使君真卿峴山送李法曹陽冰西上獻書時會有詔徵赴京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e20e345-189b-456a-b2ea-96e2bf078290', '兵後送姚太祝赴選', '兵後送姚太祝赴選', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["兩河兵已偃，處處見歸舟。","日夜故人散，江臯芳樹秋。","楚雲傷遠思，秦月憶佳遊。","名動春官籍，翩翩才少儔。"]', '["兩河兵已偃，处处见归舟。","日夜故人散，江臯芳樹秋。","楚云傷远思，秦月憶佳游。","名动春官籍，翩翩才少儔。"]', '诗', 'shi', '', NULL, '兵後送姚太祝赴選 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('786d2b48-9685-4b38-8d5d-01d29ad520ad', '兵後送薛居士移家安吉', '兵後送薛居士移家安吉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["舊遊經喪亂，道在復何人。","寒草心易折，閑雲性常真。","交情別後見，詩句比來新。","向我桃州住，惜君東嶺春。"]', '["旧游經喪亂，道在复何人。","寒草心易折，闲云性常真。","交情別後见，诗句比来新。","向我桃州住，惜君东嶺春。"]', '诗', 'shi', '', NULL, '兵後送薛居士移家安吉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98313de0-45fd-415a-8f3f-696c724b8b81', '送鄥傪之洪州覲兄弟', '送鄥傪之洪州覲兄弟', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["年少足詩情，西江楚月清。","書囊山翠濕，琴匣雪花輕。","久別經離亂，新正憶弟兄。","贈君題樂府，爲是豫章行。"]', '["年少足诗情，西江楚月清。","书囊山翠濕，琴匣雪花轻。","久別經離亂，新正憶弟兄。","贈君題乐府，爲是豫章行。"]', '诗', 'shi', '', NULL, '送鄥傪之洪州覲兄弟 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38c3862f-78a6-4d3c-b1d6-27327b5eeeff', '送乾封李成', '送乾封李成', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["羽檄飛未息，離情遠近同。","感君繇泛瑟，關我是征鴻。","眇默歸人盡，疎蕪夜渡空。","還期當歲晚，獨在路行中。"]', '["羽檄飞未息，離情远近同。","感君繇泛瑟，关我是征鴻。","眇默归人尽，疎蕪夜渡空。","還期當歲晚，独在路行中。"]', '诗', 'shi', '', NULL, '送乾封李成 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc1a9ede-8c1a-4380-9307-a5a5c23e7b01', '送崔判官還揚子', '送崔判官還揚子', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["輕傳祗遠役，依依下姑亭。","秋聲滿楊柳，暮色繞郊坰。","煙水搖歸思，山當楚驛青。"]', '["轻傳祗远役，依依下姑亭。","秋声满楊柳，暮色繞郊坰。","煙水搖归思，山當楚驛青。"]', '诗', 'shi', '', NULL, '送崔判官還揚子 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0651c69-b3f0-46c1-a65c-b11b67e530a2', '奉酬袁使君西樓餞秦山人與晝同赴李侍御招三韻', '奉酬袁使君西楼餞秦山人與晝同赴李侍御招三韻', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["秋風怨別情，江守上西城。","竹暑寒流淺，琴窗宿雨晴。","治書招遠意，知共楚狂行。"]', '["秋风怨別情，江守上西城。","竹暑寒流淺，琴窗宿雨晴。","治书招远意，知共楚狂行。"]', '诗', 'shi', '', NULL, '奉酬袁使君西樓餞秦山人與晝同赴李侍御招三韻 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de64380f-bcb1-48b3-b6af-1709de80b037', '送清涼上人', '送清涼上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["何意欲歸山，道高繇境勝。","花空覺性了，月盡知心證。","永夜出禪吟，清猨自相應。"]', '["何意欲归山，道高繇境勝。","花空覺性了，月尽知心證。","永夜出禪吟，清猨自相應。"]', '诗', 'shi', '', NULL, '送清涼上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09758709-4129-4b11-a298-0cd001955934', '送李丞使宣州', '送李丞使宣州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["結駟何翩翩，落葉暗寒渚。","夢裏春穀泉，愁中洞庭雨。","聊持剡山茗，以代宜城醑。"]', '["結駟何翩翩，落葉暗寒渚。","梦裏春穀泉，愁中洞庭雨。","聊持剡山茗，以代宜城醑。"]', '诗', 'shi', '', NULL, '送李丞使宣州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47837c8d-2791-4ba9-bb56-3080ef8e8b43', '送至洪沙彌遊越', '送至洪沙彌游越', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["知爾學無生，不應傷此別。","相逢宿我寺，獨往遊靈越。","早晚花會中，經行剡山月。"]', '["知爾学無生，不應傷此別。","相逢宿我寺，独往游靈越。","早晚花會中，經行剡山月。"]', '诗', 'shi', '', NULL, '送至洪沙彌遊越 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f5dfe65-9c56-453b-a118-2787a226fe2e', '送皇甫侍御曾還丹陽別業', '送皇甫侍御曾還丹陽別業', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["雲陽別夜憶春耕，花發菱湖問去程。","積水悠揚何處夢，亂山稠疊此時情。","將離有月教弦斷，贈遠無蘭覺意輕。","朝右要君持漢典，明年北墅可須營。"]', '["云陽別夜憶春耕，花發菱湖问去程。","積水悠揚何处梦，亂山稠叠此时情。","將離有月教弦斷，贈远無蘭覺意轻。","朝右要君持漢典，明年北墅可須營。"]', '诗', 'shi', '', NULL, '送皇甫侍御曾還丹陽別業 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b92bbe-b7be-466c-a95a-8bda7783c6b3', '白蘋洲送洛陽李丞使還', '白蘋洲送洛陽李丞使還', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["蘋洲北望楚山重，千里迴軺止一封。","臨水情來還共載，看花醉去更相從。","罷宮風渚何時別，寄隱雲陽幾處逢。","後會那應似疇昔，年年覺老雪山容。"]', '["蘋洲北望楚山重，千里迴軺止一封。","臨水情来還共載，看花醉去更相從。","罷宮风渚何时別，寄隐云陽幾处逢。","後會那應似疇昔，年年覺老雪山容。"]', '诗', 'shi', '', NULL, '白蘋洲送洛陽李丞使還 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d956bc46-82d6-4c9b-9f8d-f936709f89f9', '送履霜上人還金陵西山', '送履霜上人還金陵西山', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["攜錫西山步綠莎，禪心未了奈情何。","湘宮水寺清秋夜，月落風悲松柏多。"]', '["携錫西山步綠莎，禪心未了奈情何。","湘宮水寺清秋夜，月落风悲松柏多。"]', '诗', 'shi', '', NULL, '送履霜上人還金陵西山 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('276fd7e4-4cd7-4b9b-ad89-672baa15492f', '送辨聰上人還廣陵', '送辨聰上人還廣陵', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["莫學休公學遠公，了心須與我心同。","隋家古柳數株在，看取人間萬事空。"]', '["莫学休公学远公，了心須與我心同。","隋家古柳數株在，看取人间万事空。"]', '诗', 'shi', '', NULL, '送辨聰上人還廣陵 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b892cd02-1217-41d7-ac42-c323c69650e4', '送清勵上人遊福建', '送清勵上人游福建', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["禪子自矜禪性成，將來擬照建溪清。","南看閩樹花不落，更取何緣了妄情。"]', '["禪子自矜禪性成，將来擬照建溪清。","南看閩樹花不落，更取何緣了妄情。"]', '诗', 'shi', '', NULL, '送清勵上人遊福建 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aff5d0b-5559-4355-a080-5054655f2f3c', '送顧道士遊洞庭山', '送顧道士游洞庭山', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["見說洞庭無上路，春遊亂踏五靈芝。","含桃風起花狼籍，正是仙翁碁散時。"]', '["见说洞庭無上路，春游亂踏五靈芝。","含桃风起花狼籍，正是仙翁碁散时。"]', '诗', 'shi', '', NULL, '送顧道士遊洞庭山 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11b06602-4ba1-43f6-a5b9-46dc196f22bc', '送邢台州濟', '送邢台州濟', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["海上仙山屬使君，石橋琪樹古來聞。","他時畫出白團扇，乞取天台一片雲。"]', '["海上仙山屬使君，石橋琪樹古来闻。","他时畫出白團扇，乞取天台一片云。"]', '诗', 'shi', '', NULL, '送邢台州濟 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba9a88f0-988c-497b-bc44-1bf935190697', '送柳察諫議叔', '送柳察諫議叔', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["東城南陌強經過，怨別無心亦放歌。","明日院公應問我，閑雲常在石門多。"]', '["东城南陌強經過，怨別無心亦放歌。","明日院公應问我，闲云常在石门多。"]', '诗', 'shi', '', NULL, '送柳察諫議叔 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68d1f205-0598-4395-94cf-34b1a0045cd1', '送柳淡扶侍赴洪州', '送柳淡扶侍赴洪州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["中林許師友，忽阻夙心期。","自顧青緺好，來將黃鶴辭。","少年輕遠涉，世道得無欺。","煙雨孤舟上，晨昏千里時。","離魂渺天末，相望在江湄。","無限江南柳，春風卷亂絲。"]', '["中林許師友，忽阻夙心期。","自顧青緺好，来將黄鹤辞。","少年轻远涉，世道得無欺。","煙雨孤舟上，晨昏千里时。","離魂渺天末，相望在江湄。","無限江南柳，春风卷亂絲。"]', '诗', 'shi', '', NULL, '送柳淡扶侍赴洪州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8a801ae-24da-4893-bc08-9c0b357326cc', '同李司直題武丘寺兼留諸公與陸羽之無錫', '同李司直題武丘寺兼留諸公與陸羽之無錫', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["陵寢成香阜，禪枝出白楊。","劒池留故事，月樹即他方。","應世緣須別，栖心趣不忘。","還將陸居士，晨發泛歸航。"]', '["陵寢成香阜，禪枝出白楊。","劒池留故事，月樹即他方。","應世緣須別，栖心趣不忘。","還將陸居士，晨發泛归航。"]', '诗', 'shi', '', NULL, '同李司直題武丘寺兼留諸公與陸羽之無錫 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9adfe182-8f7b-4fd7-bef7-78b34ca4c684', '夏日題鄭谷江上納涼館', '夏日題鄭谷江上納涼館', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["迢遙山意外，清風又對君。","若爲於此地，翻作路岐分。","別館琴徒語，前洲鶴自羣。"]', '["迢遙山意外，清风又对君。","若爲於此地，翻作路岐分。","別館琴徒語，前洲鹤自羣。"]', '诗', 'shi', '', NULL, '夏日題鄭谷江上納涼館 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1439bee2-2d1c-48b2-82c3-b404a9fdacbc', '太湖館送殷秀才赴舉', '太湖館送殷秀才赴舉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春風洞庭路，搖蕩暮天多。","衰疾見芳草，別離傷遠波。","詩名推首薦，賦甲擬前科。","數日聞天府，山衣製芰荷。"]', '["春风洞庭路，搖蕩暮天多。","衰疾见芳草，別離傷远波。","诗名推首薦，賦甲擬前科。","數日闻天府，山衣製芰荷。"]', '诗', 'shi', '', NULL, '太湖館送殷秀才赴舉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dc1a905-638b-4ee0-b6cf-8b958bc3ea64', '送重鈞上人遊天台', '送重鈞上人游天台', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["漸看華頂出，幽賞意隨生。","十里行松色，千重過水聲。","海容雲正盡，山色雨初晴。","事事將心證，知君道可成。"]', '["漸看华頂出，幽賞意隨生。","十里行松色，千重過水声。","海容云正尽，山色雨初晴。","事事將心證，知君道可成。"]', '诗', 'shi', '', NULL, '送重鈞上人遊天台 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7c5039b-ea20-46df-ae06-1e116034b1d3', '早春送顏主簿遊越東兼謁元中丞', '早春送顏主簿游越东兼謁元中丞', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["輕舸趣不已，東風吹綠蘋。","欲看梅市雪，知賞柳家春。","別意傾吳醑，芳聲動越人。","山陰三月會，內史得嘉賓。"]', '["轻舸趣不已，东风吹綠蘋。","欲看梅市雪，知賞柳家春。","別意傾吳醑，芳声动越人。","山陰三月會，內史得嘉賓。"]', '诗', 'shi', '', NULL, '早春送顏主簿遊越東兼謁元中丞 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d0a92b4-67ac-47af-9d70-774548dda771', '同顏使君清明日遊因送蕭主簿', '同顏使君清明日游因送蕭主簿', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["誰知賞嘉節，別異忽相和。","暮色汀洲徧，春情楊柳多。","高城戀旌斾，極浦宿風波。","惆悵支山月，今宵不再過。"]', '["誰知賞嘉節，別異忽相和。","暮色汀洲徧，春情楊柳多。","高城戀旌斾，極浦宿风波。","惆悵支山月，今宵不再過。"]', '诗', 'shi', '', NULL, '同顏使君清明日遊因送蕭主簿 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377688d7-b1be-44c4-b3fc-56d953d4f6d9', '送道琚上人還金陵', '送道琚上人還金陵', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一與鍾山別，山中得信稀。","經年求法後，及夏問安歸。","野實充甘膳，池花當綵衣。","慈親莫返拜，外禮欲無爲。"]', '["一與鍾山別，山中得信稀。","經年求法後，及夏问安归。","野實充甘膳，池花當綵衣。","慈親莫返拜，外禮欲無爲。"]', '诗', 'shi', '', NULL, '送道琚上人還金陵 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efc703bb-6916-4269-bf9c-01513fd90d14', '送裴邕之上京', '送裴邕之上京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["辭山偶世清，挾策忽西行。","帆過隨江疾，衣霑楚雪輕。","尚文須獻賦，重道莫論兵。","東觀今多事，應高白馬生。"]', '["辞山偶世清，挾策忽西行。","帆過隨江疾，衣霑楚雪轻。","尚文須獻賦，重道莫論兵。","东观今多事，應高白马生。"]', '诗', 'shi', '', NULL, '送裴邕之上京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e059389c-abce-49e0-bba6-87e5e560defa', '送珍上人還天竺兼寄廣通上人秦山人', '送珍上人還天竺兼寄廣通上人秦山人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["江寺名天竺，多居躡遠蹤。","春帆依柳浦，輕履上蓮峰。","禪子兼三隱，空書共一封。","因君達山信，應向白雲逢。"]', '["江寺名天竺，多居躡远蹤。","春帆依柳浦，轻履上蓮峰。","禪子兼三隐，空书共一封。","因君達山信，應向白云逢。"]', '诗', 'shi', '', NULL, '送珍上人還天竺兼寄廣通上人秦山人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8284383b-63d9-4bad-b667-0cd6978c2612', '送張孝廉赴舉', '送張孝廉赴舉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["名在諸生右，家經見素風。","春田休學稼，秋賦出儒宮。","別路殘雲濕，離情晚桂叢。","明年石渠署，應繼叔孫通。"]', '["名在諸生右，家經见素风。","春田休学稼，秋賦出儒宮。","別路殘云濕，離情晚桂叢。","明年石渠署，應繼叔孫通。"]', '诗', 'shi', '', NULL, '送張孝廉赴舉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36cbe323-2fe4-47b1-a0d1-0bb272df2c02', '送劉司法之越', '送劉司法之越', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["蕭蕭鳴夜角，驅馬背城濠。","雨後寒流急，秋來朔吹高。","三山期望海，八月欲觀濤。","幾日西陵路，應逢謝法曹。"]', '["蕭蕭鳴夜角，驱马背城濠。","雨後寒流急，秋来朔吹高。","三山期望海，八月欲观濤。","幾日西陵路，應逢謝法曹。"]', '诗', 'shi', '', NULL, '送劉司法之越 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2b9a51-a60d-4fc4-ba23-3406eae1408d', '送簡栖上人之建州覲使君舅', '送簡栖上人之建州覲使君舅', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["亂峰江上色，羨爾及秋行。","釋氏推真子，郗家許貴甥。","氎花新雨淨，帆葉好風輕。","千里依元舅，迴潮亦有情。"]', '["亂峰江上色，羨爾及秋行。","釋氏推真子，郗家許貴甥。","氎花新雨淨，帆葉好风轻。","千里依元舅，迴潮亦有情。"]', '诗', 'shi', '', NULL, '送簡栖上人之建州覲使君舅 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df2fd6f1-6d5b-4373-92b9-2967698bc927', '登開元寺樓送崔少府還平望驛', '登开元寺楼送崔少府還平望驛', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["登望思慮積，長亭樹連連。","悠揚下樓日，杳映傍帆煙。","入夜四郊靜，南湖月待船。"]', '["登望思慮積，长亭樹連連。","悠揚下楼日，杳映傍帆煙。","入夜四郊静，南湖月待船。"]', '诗', 'shi', '', NULL, '登開元寺樓送崔少府還平望驛 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a182ef9-a9de-4c03-a818-799a013d041a', '送王居士遊越', '送王居士游越', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["野性配雲泉，詩情屬風景。","愛作爛熳遊，閑尋東路永。","何山最好望，須上蕭然嶺。"]', '["野性配云泉，诗情屬风景。","愛作爛熳游，闲尋东路永。","何山最好望，須上蕭然嶺。"]', '诗', 'shi', '', NULL, '送王居士遊越 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('015123de-e5f5-4475-aecf-499c38f45d16', '雜言重送皇甫侍御曾', '杂言重送皇甫侍御曾', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["人獨歸，日將暮。","孤帆帶孤嶼，遠水連遠樹。","難作別時心，還看別時路。"]', '["人独归，日將暮。","孤帆带孤嶼，远水連远樹。","难作別时心，還看別时路。"]', '诗', 'shi', '', NULL, '雜言重送皇甫侍御曾 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('210c23f4-db88-4ca0-bd10-b8c533055b38', '送演上人之撫州覲使君叔', '送演上人之撫州覲使君叔', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["臨川內史憐諸謝，爾在生緣比惠宗。","遠別應將秦本去，幽尋定有楚僧逢。","停船夜坐親孤月，把錫秋行入亂峰。","便道須過大師寺，白蓮池上訪高蹤。"]', '["臨川內史怜諸謝，爾在生緣比惠宗。","远別應將秦本去，幽尋定有楚僧逢。","停船夜坐親孤月，把錫秋行入亂峰。","便道須過大師寺，白蓮池上訪高蹤。"]', '诗', 'shi', '', NULL, '送演上人之撫州覲使君叔 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e5f47ff-0f41-439a-ae00-fbae21bd80c4', '送大寶上人歸楚山', '送大寶上人归楚山', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["厭上烏橋送別頻，湖光爛熳望行人。","欲將夜舸陪嘉月，肯住空林伴老身。","獨鶴翩翻飛不定，歸雲蕭散會無因。","從何得道懷惆悵，莫是人間屢見春。"]', '["厭上烏橋送別頻，湖光爛熳望行人。","欲將夜舸陪嘉月，肯住空林伴老身。","独鹤翩翻飞不定，归云蕭散會無因。","從何得道懷惆悵，莫是人间屢见春。"]', '诗', 'shi', '', NULL, '送大寶上人歸楚山 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6bfdacd-f332-425e-8612-db56bc69fbda', '送侯秀才南遊', '送侯秀才南游', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["芳草隨君自有情，不關山色與猨聲。","爲看嚴子灘頭石，曾憶題詩不著名。"]', '["芳草隨君自有情，不关山色與猨声。","爲看嚴子灘头石，曾憶題诗不著名。"]', '诗', 'shi', '', NULL, '送侯秀才南遊 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7808f40-425c-47f1-9d9b-61e5658bea45', '別洞庭維諒上人', '別洞庭維諒上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["白雲關我不關他，此物留君情最多。","情著春風生橘樹，歸心不怕洞庭波。"]', '["白云关我不关他，此物留君情最多。","情著春风生橘樹，归心不怕洞庭波。"]', '诗', 'shi', '', NULL, '別洞庭維諒上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb6f927-4a3a-4d3a-971f-1367fde21539', '康造錄事宅送太祝姪之虔吉訪兄弟', '康造錄事宅送太祝姪之虔吉訪兄弟', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["阮咸別曲四座愁，賴是春風不是秋。","漫漫江行訪兄弟，猨聲幾夜宿蘆洲。"]', '["阮咸別曲四座愁，賴是春风不是秋。","漫漫江行訪兄弟，猨声幾夜宿蘆洲。"]', '诗', 'shi', '', NULL, '康造錄事宅送太祝姪之虔吉訪兄弟 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcda5207-1ae4-4a31-bba0-da6f28c8bbf1', '冬日梅溪送裴方舟宣州', '冬日梅溪送裴方舟宣州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["平明匹馬上村橋，花發梅溪雪未消。","日短天寒愁送客，楚山無限路遙遙。"]', '["平明匹马上村橋，花發梅溪雪未消。","日短天寒愁送客，楚山無限路遙遙。"]', '诗', 'shi', '', NULL, '冬日梅溪送裴方舟宣州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76f65785-3e98-4acc-a7f8-5c6cc6388ec9', '送韋向睦州謁獨孤使君汜', '送韋向睦州謁独孤使君汜', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["才子南看多遠情，閑舟蕩漾任春行。","新安江色長如此，何似新安太守清。"]', '["才子南看多远情，闲舟蕩漾任春行。","新安江色长如此，何似新安太守清。"]', '诗', 'shi', '', NULL, '送韋向睦州謁獨孤使君汜 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ca2bb2-4712-4f83-86ff-eeeb52518694', '送至嚴山人歸山', '送至嚴山人归山', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["初到人間柳始陰，山書昨夜報春深。","朝朝花落幾株樹，惱殺禪僧未證心。"]', '["初到人间柳始陰，山书昨夜報春深。","朝朝花落幾株樹，惱殺禪僧未證心。"]', '诗', 'shi', '', NULL, '送至嚴山人歸山 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ac60a5c-acf7-4c2b-95c0-2bdab8cf6e60', '送僧遊揚州', '送僧游揚州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["平明擇鉢向風輕，正及隋堤柳色行。","知爾禪心還似我，故宮春物肯傷情。"]', '["平明擇鉢向风轻，正及隋堤柳色行。","知爾禪心還似我，故宮春物肯傷情。"]', '诗', 'shi', '', NULL, '送僧遊揚州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e38e013-8ee1-4e25-a76f-55e772083dcd', '對陸迅飲天目山茶因寄元居士晟', '对陸迅饮天目山茶因寄元居士晟', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["喜見幽人會，初開野客茶。","日成東井葉，露採北山芽。","文火香偏勝，寒泉味轉嘉。","投鐺湧作沫，著椀聚生花。","稍與禪經近，聊將睡網賒。","知君在天目，此意日無涯。"]', '["喜见幽人會，初开野客茶。","日成东井葉，露採北山芽。","文火香偏勝，寒泉味轉嘉。","投鐺湧作沫，著椀聚生花。","稍與禪經近，聊將睡網賒。","知君在天目，此意日無涯。"]', '诗', 'shi', '', NULL, '對陸迅飲天目山茶因寄元居士晟 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f260386-6918-4ec1-baa6-50b92076f515', '渡前溪', '渡前溪', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["不意入前溪，愛溪從錯落。","清清鑑不足，非是深難度。"]', '["不意入前溪，愛溪從錯落。","清清鑑不足，非是深难度。"]', '诗', 'shi', '', NULL, '渡前溪 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b5edc93-e6c9-4e0e-8a09-3583554645a5', '送靈澈', '送靈澈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["我欲長生夢，無心解傷別。","千里萬里心，只似眼前月。"]', '["我欲长生梦，無心解傷別。","千里万里心，只似眼前月。"]', '诗', 'shi', '', NULL, '送靈澈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaeabc88-36d3-4e27-a3ac-9f63a4120216', '寄路溫州', '寄路溫州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["欲問采靈藥，如何學無生。","愛鶴頗似君，且非求仙情。"]', '["欲问采靈藥，如何学無生。","愛鹤頗似君，且非求仙情。"]', '诗', 'shi', '', NULL, '寄路溫州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('465dbedf-6abe-4394-9cb6-23532cbf8679', '浣紗女', '浣紗女', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["清淺白沙灘，綠蒲尚堪把。","家住水東西，浣紗明月下。"]', '["清淺白沙灘，綠蒲尚堪把。","家住水东西，浣紗明月下。"]', '诗', 'shi', '', NULL, '浣紗女 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e951a6ba-1dbc-40e5-ba83-45ca87bc7f76', '待山月', '待山月', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["夜夜憶故人，長教山月待。","今宵故人至，山月知何在。"]', '["夜夜憶故人，长教山月待。","今宵故人至，山月知何在。"]', '诗', 'shi', '', NULL, '待山月 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c920f1b-b029-4445-bcfe-461caf31fa7c', '雜興', '杂兴', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["人生分已定，富貴豈妄來。","不見海底泥，飛上成塵埃。"]', '["人生分已定，富貴豈妄来。","不见海底泥，飞上成塵埃。"]', '诗', 'shi', '', NULL, '雜興 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb49477-b27a-4765-8627-9a4684b7a23f', '舂陵登望', '舂陵登望', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["西底空流水，東垣但聚雲。","最傷梅嶺望，花雪正紛紛。"]', '["西底空流水，东垣但聚云。","最傷梅嶺望，花雪正紛紛。"]', '诗', 'shi', '', NULL, '舂陵登望 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbed233e-2aee-485e-ba31-d4a59b6671a5', '投知己', '投知己', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["若爲令憶洞庭春，上有閑雲可隱身。","無限白雲山要買，不知山價出何人。"]', '["若爲令憶洞庭春，上有闲云可隐身。","無限白云山要買，不知山價出何人。"]', '诗', 'shi', '', NULL, '投知己 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d3ba142-1e93-4213-8400-17d45daff7f7', '兵後餘不亭重送盧孟明遊江西', '兵後餘不亭重送盧孟明游江西', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["攜手曾此分，怳如隔胡越。","倫侯古封邑，榮盛風雨歇。","飢鼯號空亭，野草生故轍。","如何此路岐，更作千年別。","馮軾望遠道，春山無斷絕。","朝行入郢樹，夜泊依楚月。","佳士持操高，揚才日昭晰。","離言何所贈，盈滿有虧缺。","時節傷蟪蛄，芳菲忌鶗鴂。","予思鹿門隱，心跡貴冥滅。","頹顏反芝朮，昔貌成冰雪。","歲晏期爾來，銷聲坐巖穴。"]', '["携手曾此分，怳如隔胡越。","倫侯古封邑，榮盛风雨歇。","飢鼯號空亭，野草生故轍。","如何此路岐，更作千年別。","馮軾望远道，春山無斷絕。","朝行入郢樹，夜泊依楚月。","佳士持操高，揚才日昭晰。","離言何所贈，盈满有虧缺。","时節傷蟪蛄，芳菲忌鶗鴂。","予思鹿门隐，心跡貴冥滅。","頹顏反芝朮，昔貌成冰雪。","歲晏期爾来，銷声坐巖穴。"]', '诗', 'shi', '', NULL, '兵後餘不亭重送盧孟明遊江西 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e005974a-ab48-4e6c-a41a-67b352683ae0', '別山詩', '別山诗', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山翁亦好禪，借我風溪樹。","採藥多近峰，汲泉有春渡。","幽僧時相偶，仙子或與晤。","自許戰勝心，彌高獨遊步。","如何區中事，奪我林棲趣。","辭山下復上，戀石行仍顧。","宿昔情或乖，庶幾跡無誤。","松聲莫相誚，此心冥去住。"]', '["山翁亦好禪，借我风溪樹。","採藥多近峰，汲泉有春渡。","幽僧时相偶，仙子或與晤。","自許戰勝心，彌高独游步。","如何區中事，奪我林棲趣。","辞山下复上，戀石行仍顧。","宿昔情或乖，庶幾跡無誤。","松声莫相誚，此心冥去住。"]', '诗', 'shi', '', NULL, '別山詩 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3facf68-cd48-43d3-8e23-db28e701b9bd', '同袁高使君送李判官使迴', '同袁高使君送李判官使迴', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["庾公歡此別，路遠意猶賒。","爲出塘邊柳，榮歸府中花。","馳陽照古堞，遙思凝寒笳。","延步下前渚，泝觴流淺沙。","湖光引行色，輕舸傍殘霞。"]', '["庾公歡此別，路远意猶賒。","爲出塘邊柳，榮归府中花。","驰陽照古堞，遙思凝寒笳。","延步下前渚，泝觴流淺沙。","湖光引行色，轻舸傍殘霞。"]', '诗', 'shi', '', NULL, '同袁高使君送李判官使迴 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('512e5fd2-e9ca-4ee1-999c-e3e1e0862758', '陪顏使君餞宣諭蕭常侍', '陪顏使君餞宣諭蕭常侍', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["江濤凋瘵後，遠使發天都。","昏墊宸心及，哀矜詔命敷。","恤民驅急傳，訪舊枉征艫。","外鎮藩條最，中朝顧問殊。","文皆正風俗，名共溢寰區。","已事方懷闕，歸期早戒塗。","繁笳咽水閣，高蓋擁雲衢。","暮色生千嶂，秋聲入五湖。","離歌猶宛轉，歸馭已踟躇。","今夕庾公意，西樓月亦孤。"]', '["江濤凋瘵後，远使發天都。","昏墊宸心及，哀矜詔命敷。","恤民驱急傳，訪旧枉征艫。","外鎮藩條最，中朝顧问殊。","文皆正风俗，名共溢寰區。","已事方懷闕，归期早戒塗。","繁笳咽水閣，高蓋擁云衢。","暮色生千嶂，秋声入五湖。","離歌猶宛轉，归馭已踟躇。","今夕庾公意，西楼月亦孤。"]', '诗', 'shi', '', NULL, '陪顏使君餞宣諭蕭常侍 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f3eb80-91a3-4b42-93c4-e1a73fc51a94', '奉陪顏使君修韻海畢東溪泛舟餞諸文士', '奉陪顏使君修韻海畢东溪泛舟餞諸文士', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["諸侯崇魯學，羔鴈日成羣。","外史刊新韻，中郎定古文。","菁華兼百氏，縑素備三墳。","國語思開物，王言欲致君。","研精業已就，懽宴惜應分。","獨望西山去，將身寄白雲。"]', '["諸侯崇魯学，羔鴈日成羣。","外史刊新韻，中郎定古文。","菁华兼百氏，縑素備三墳。","国語思开物，王言欲致君。","研精業已就，懽宴惜應分。","独望西山去，將身寄白云。"]', '诗', 'shi', '', NULL, '奉陪顏使君修韻海畢東溪泛舟餞諸文士 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c60e0bd-891b-41da-8db2-3091534cd6b8', '今上初登極歲送皇甫孝廉赴選', '今上初登極歲送皇甫孝廉赴選', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["行應會府春，欲勸及芳辰。","北極天文正，東風漢律新。","少年逢聖代，歡笑別情親。","況是勳庸後，恩榮襲爾身。"]', '["行應會府春，欲勸及芳辰。","北極天文正，东风漢律新。","少年逢聖代，歡笑別情親。","況是勳庸後，恩榮襲爾身。"]', '诗', 'shi', '', NULL, '今上初登極歲送皇甫孝廉赴選 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9268c26-7928-4e10-b09b-8b24f7f1d2b3', '同楊使君白蘋洲送陸侍御士佳入朝', '同楊使君白蘋洲送陸侍御士佳入朝', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["久愛吳興客，來依道德藩。","旋師聞杕杜，歸路憶轘轅。","舊佩蒼玉在，新歌白芷繁。","今朝天地靜，北望重飛翻。"]', '["久愛吳兴客，来依道德藩。","旋師闻杕杜，归路憶轘轅。","旧佩蒼玉在，新歌白芷繁。","今朝天地静，北望重飞翻。"]', '诗', 'shi', '', NULL, '同楊使君白蘋洲送陸侍御士佳入朝 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0012dca7-d278-450b-a531-c9636d0d774b', '雪夜送海上人常州覲叔父上人殷仲文後', '雪夜送海上人常州覲叔父上人殷仲文後', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["繼世風流在，傳心向一燈。","望雲裁衲慣，翫雪步花能。","交戰情忘久，銷魂別未曾。","明朝阮家集，知有竹林僧。"]', '["繼世风流在，傳心向一灯。","望云裁衲慣，翫雪步花能。","交戰情忘久，銷魂別未曾。","明朝阮家集，知有竹林僧。"]', '诗', 'shi', '', NULL, '雪夜送海上人常州覲叔父上人殷仲文後 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('934abcb8-a86f-4831-a0f0-c3fc0155548e', '送常清上人還舒州', '送常清上人還舒州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["灊人思爾法，楚信有迴船。","估客親宵語，閑鷗偶晝禪。","經聲含石瀲，麈尾拂江煙。","常說歸山意，誅茅廬霍前。"]', '["灊人思爾法，楚信有迴船。","估客親宵語，闲鷗偶晝禪。","經声含石瀲，麈尾拂江煙。","常说归山意，誅茅廬霍前。"]', '诗', 'shi', '', NULL, '送常清上人還舒州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('019a61c7-f187-40a0-b282-fe86c6c98531', '峴山送崔子向之宣州謁裴使君', '峴山送崔子向之宣州謁裴使君', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["楚思入詩清，晨登峴山情。","秋天水西寺，古木宛陵城。","琴匣應將往，書車亦共行。","吾知江太守，一顧重君名。"]', '["楚思入诗清，晨登峴山情。","秋天水西寺，古木宛陵城。","琴匣應將往，书车亦共行。","吾知江太守，一顧重君名。"]', '诗', 'shi', '', NULL, '峴山送崔子向之宣州謁裴使君 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af7c624d-780d-47a0-8eb0-0449c042c261', '送嚴明府入關謁黎京兆', '送嚴明府入关謁黎京兆', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春日異秋風，何爲怨別同。","潮迴芳渚沒，花落晝山空。","旅候聞嘶馬，殘陽望斷鴻。","應思右內史，相見直城中。"]', '["春日異秋风，何爲怨別同。","潮迴芳渚沒，花落晝山空。","旅候闻嘶马，殘陽望斷鴻。","應思右內史，相见直城中。"]', '诗', 'shi', '', NULL, '送嚴明府入關謁黎京兆 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fb350ba-d5ef-4d2f-a497-c7d0e3fc8023', '送丘秀才遊越', '送丘秀才游越', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山情與詩思，爛熳欲何從。","夜舸誰相逐，空江月自逢。","春期越草秀，晴憶剡雲濃。","便擬將輕錫，攜居入亂峰。"]', '["山情與诗思，爛熳欲何從。","夜舸誰相逐，空江月自逢。","春期越草秀，晴憶剡云濃。","便擬將轻錫，携居入亂峰。"]', '诗', 'shi', '', NULL, '送丘秀才遊越 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311e2f12-cb56-4e03-bc1c-b313e27be91b', '送楊校書還濟源', '送楊校书還濟源', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["妖烽昨日靜，故里近嵩丘。","楚月搖歸夢，江楓見早秋。","鄉心無遠道，北信減離憂。","禪子還無事，辭君買沃州。"]', '["妖烽昨日静，故里近嵩丘。","楚月搖归梦，江楓见早秋。","乡心無远道，北信減離憂。","禪子還無事，辞君買沃州。"]', '诗', 'shi', '', NULL, '送楊校書還濟源 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('284f2674-7f1d-437f-bb78-3a2a13fe71b5', '送楊遂初赴選', '送楊遂初赴選', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["秋風吹別袂，客思在長安。","若得臨觴醉，何須減瑟彈。","秉心凌竹柏，仗信越波瀾。","春會文昌府，思君每北看。"]', '["秋风吹別袂，客思在长安。","若得臨觴醉，何須減瑟彈。","秉心凌竹柏，仗信越波瀾。","春會文昌府，思君每北看。"]', '诗', 'shi', '', NULL, '送楊遂初赴選 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('413da56f-7ee5-4dea-995b-9a713ded91f5', '送贇上人還京', '送贇上人還京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["久遊春草盡，還寄北船歸。","沙鳥窺中食，江雲入淨衣。","秦原山色近，楚寺磬聲微。","見說翻經館，多聞似者稀。"]', '["久游春草尽，還寄北船归。","沙鸟窺中食，江云入淨衣。","秦原山色近，楚寺磬声微。","见说翻經館，多闻似者稀。"]', '诗', 'shi', '', NULL, '送贇上人還京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a60433a7-b5b1-4ef1-95b6-62b28dc2c19f', '送廣通上人遊江西', '送廣通上人游江西', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["香爐七嶺秀，秋色九江清。","自古多禪隱，吾常愛此行。","尋師經鄂渚，受請到青城。","離別人間事，何關道者情。"]', '["香爐七嶺秀，秋色九江清。","自古多禪隐，吾常愛此行。","尋師經鄂渚，受請到青城。","離別人间事，何关道者情。"]', '诗', 'shi', '', NULL, '送廣通上人遊江西 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccc82c46-f8e8-4870-8ec4-07c89144fa67', '送羅判官還壽州幕', '送羅判官還壽州幕', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["君章才五色，知爾得家風。","故里旋歸駕，壽春思奉戎。","天寒長蛇伏，飆烈文虎雄。","定頌張征虜，桓桓戡難功。"]', '["君章才五色，知爾得家风。","故里旋归駕，壽春思奉戎。","天寒长蛇伏，飆烈文虎雄。","定頌張征虜，桓桓戡难功。"]', '诗', 'shi', '', NULL, '送羅判官還壽州幕 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd6dc609-00ed-4d26-9b1c-797f0d1c67d7', '送李秀才赴婺州招', '送李秀才赴婺州招', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山開江色上，孤賞去應遲。","綠水迎吳榜，秋風入楚詞。","猨清獨宿處，木落遠行時。","見說東陽守，登樓爲爾期。"]', '["山开江色上，孤賞去應遲。","綠水迎吳榜，秋风入楚词。","猨清独宿处，木落远行时。","见说东陽守，登楼爲爾期。"]', '诗', 'shi', '', NULL, '送李秀才赴婺州招 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6163842c-cd07-4922-884f-b8ca285e40dd', '送薛逢之宣州謁廢使', '送薛逢之宣州謁廢使', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["六月鵬盡化，鴻飛獨冥冥。","秋烽家不定，險路客頻經。","牛渚何時到，漁船幾處停。","遙知詠史夜，謝守月中聽。"]', '["六月鵬尽化，鴻飞独冥冥。","秋烽家不定，險路客頻經。","牛渚何时到，漁船幾处停。","遙知詠史夜，謝守月中听。"]', '诗', 'shi', '', NULL, '送薛逢之宣州謁廢使 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20125a58-e28c-4901-9bbc-2ed9be1531b2', '送德守二叔姪上人還國清寺覲師', '送德守二叔姪上人還国清寺覲師', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["道賢齊二阮，俱向竹林歸。","古偈穿花線，春裝卷葉衣。","僧墟迴水寺，佛隴啓山扉。","愛別吾何有，人心強有違。"]', '["道賢齊二阮，俱向竹林归。","古偈穿花線，春裝卷葉衣。","僧墟迴水寺，佛隴啓山扉。","愛別吾何有，人心強有違。"]', '诗', 'shi', '', NULL, '送德守二叔姪上人還國清寺覲師 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7a61698-8744-4ba7-ad8e-6e8aae32456e', '同明府章送沈秀才還石門山讀書', '同明府章送沈秀才還石门山读书', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["身爲郢令客，心許楚山雲。","文墨應經世，林泉漫誘君。","欲隨樵子去，惜與道流分。","肯謝申公輩，治詩事漢文。"]', '["身爲郢令客，心許楚山云。","文墨應經世，林泉漫誘君。","欲隨樵子去，惜與道流分。","肯謝申公輩，治诗事漢文。"]', '诗', 'shi', '', NULL, '同明府章送沈秀才還石門山讀書 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76464b7b-6cdb-42fb-9397-4e8d3d49c93e', '送吉判官還京赴崔尹幕', '送吉判官還京赴崔尹幕', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["江南梅雨天，別思極春前。","長路飛鳴鶴，離帆聚散煙。","清晨趨九陌，秋色望三邊。","見說王都尹，山陽辟一賢。"]', '["江南梅雨天，別思極春前。","长路飞鳴鹤，離帆聚散煙。","清晨趨九陌，秋色望三邊。","见说王都尹，山陽辟一賢。"]', '诗', 'shi', '', NULL, '送吉判官還京赴崔尹幕 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a68ed2-a27f-4015-9a26-9c5724c4af71', '送裴判官赴商幕', '送裴判官赴商幕', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["商洛近京師，才難赴幕時。","離歌紛白紵，候騎擁青絲。","會喜疲人息，應逢猾虜衰。","看君策高足，自此煙霄期。"]', '["商洛近京師，才难赴幕时。","離歌紛白紵，候騎擁青絲。","會喜疲人息，應逢猾虜衰。","看君策高足，自此煙霄期。"]', '诗', 'shi', '', NULL, '送裴判官赴商幕 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce2d35e0-f4b0-4409-971e-f7c02826fb65', '送李喻之處士洪州謁曹王', '送李喻之处士洪州謁曹王', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["獨思賢王府，遂作豫章行。","雄鎮廬霍秀，高秋江漢清。","見聞驚苦節，艱故傷遠情。","西邸延嘉士，遺才得正平。"]', '["独思賢王府，遂作豫章行。","雄鎮廬霍秀，高秋江漢清。","见闻驚苦節，艱故傷远情。","西邸延嘉士，遺才得正平。"]', '诗', 'shi', '', NULL, '送李喻之處士洪州謁曹王 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af0a0f75-4479-4a74-8b39-22d17c99f0c6', '送唐贊善遊越', '送唐贊善游越', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["田園臨漢水，離亂寄隨關。","今日煙塵盡，東西又未還。","長亭百越外，孤櫂五湖間。","何處遊芳草，雲門千萬山。"]', '["田园臨漢水，離亂寄隨关。","今日煙塵尽，东西又未還。","长亭百越外，孤櫂五湖间。","何处游芳草，云门千万山。"]', '诗', 'shi', '', NULL, '送唐贊善遊越 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58425418-7cca-4d94-959e-0a9fdff1b95a', '送韋秀才', '送韋秀才', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["晨裝行墮葉，萬里望桑乾。","舊說涇關險，猶聞易水寒。","黃雲戰後積，白草暮來看。","近得君苗信，時教旅思寬。"]', '["晨裝行墮葉，万里望桑乾。","旧说涇关險，猶闻易水寒。","黄云戰後積，白草暮来看。","近得君苗信，时教旅思寬。"]', '诗', 'shi', '', NULL, '送韋秀才 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83140b82-3e31-4b2b-84de-197885e41511', '送陳秀才赴舉', '送陳秀才赴舉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["諸侯懼削地，選士皆不羈。","休隱脫荷芰，將鳴矜羽儀。","甲科爭玉片，詩句擬花枝。","君實三楚秀，承家有清規。"]', '["諸侯懼削地，選士皆不羈。","休隐脫荷芰，將鳴矜羽儀。","甲科爭玉片，诗句擬花枝。","君實三楚秀，承家有清規。"]', '诗', 'shi', '', NULL, '送陳秀才赴舉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('930f9898-6d9f-4812-b0f4-03a05b803b34', '烏程李明府水堂同盧使君幼平送奘上人遊五臺', '烏程李明府水堂同盧使君幼平送奘上人游五台', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["身將劉令隱，經共謝公翻。","有此宗師在，應知我法存。","問心常寂樂，爲別豈傷魂。","獨訪華泉去，秋風入雁門。"]', '["身將劉令隐，經共謝公翻。","有此宗師在，應知我法存。","问心常寂乐，爲別豈傷魂。","独訪华泉去，秋风入雁门。"]', '诗', 'shi', '', NULL, '烏程李明府水堂同盧使君幼平送奘上人遊五臺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2a82c4d-8c7d-4c02-a5a8-3268bd1c085d', '送李季良北歸', '送李季良北归', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["風吹殘柳絲，孤客欲歸時。","掩抑楚弦絕，離披湘葉衰。","前軍猶轉戰，故國杳難期。","北望鴈門雪，空吟平子詩。"]', '["风吹殘柳絲，孤客欲归时。","掩抑楚弦絕，離披湘葉衰。","前軍猶轉戰，故国杳难期。","北望鴈门雪，空吟平子诗。"]', '诗', 'shi', '', NULL, '送李季良北歸 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f51d1cab-f27a-4c80-9ad2-38f00f169ec9', '送淳于秀才蘭陵覲省', '送淳于秀才蘭陵覲省', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["歡言欲忘別，風信忽相驚。","柳浦歸人思，蘭陵春草生。","擷芳心未及，視枕戀常盈。","此去非長路，還如千里情。"]', '["歡言欲忘別，风信忽相驚。","柳浦归人思，蘭陵春草生。","擷芳心未及，視枕戀常盈。","此去非长路，還如千里情。"]', '诗', 'shi', '', NULL, '送淳于秀才蘭陵覲省 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54229a02-6078-4090-a29b-54f58859bbb4', '送至洪沙彌赴上元受戒', '送至洪沙彌赴上元受戒', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["不肯資章甫，勝衣被木蘭。","今隨秣陵信，欲及蔡州壇。","野寺鐘聲遠，春山戒足寒。","歸來次第學，應見後心難。"]', '["不肯資章甫，勝衣被木蘭。","今隨秣陵信，欲及蔡州壇。","野寺鐘声远，春山戒足寒。","归来次第学，應见後心难。"]', '诗', 'shi', '', NULL, '送至洪沙彌赴上元受戒 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45f72bee-0bd1-4aaa-beb7-2e56674558d4', '九日同盧使君幼平吳興郊外送李司倉赴選', '九日同盧使君幼平吳兴郊外送李司倉赴選', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["重陽千騎出，送客爲踟躕。","曠野多搖落，寒山滿路隅。","晴空懸蒨斾，秋色起菱湖。","幾日登司會，揚才盛五都。"]', '["重陽千騎出，送客爲踟躕。","曠野多搖落，寒山满路隅。","晴空懸蒨斾，秋色起菱湖。","幾日登司會，揚才盛五都。"]', '诗', 'shi', '', NULL, '九日同盧使君幼平吳興郊外送李司倉赴選 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('743b9ff6-ef74-4619-a1fb-8b677a3baa9d', '送盧孟明還上都', '送盧孟明還上都', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["江臯北風至，歸客獨傷魂。","楚水逢鄉雁，平陵憶故園。","征驂嘶別館，落日隱寒原。","應及秦川望，春華滿國門。"]', '["江臯北风至，归客独傷魂。","楚水逢乡雁，平陵憶故园。","征驂嘶別館，落日隐寒原。","應及秦川望，春华满国门。"]', '诗', 'shi', '', NULL, '送盧孟明還上都 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9acd6b1e-d9d2-4074-b391-695f47562b0d', '送李少賓赴舉', '送李少賓赴舉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["豈謂江南別，心如塞上行。","苦雲搖陣色，亂木攪秋聲。","周谷雨未散，漢河流尚橫。","春司遲爾策，方用靜妖兵。"]', '["豈謂江南別，心如塞上行。","苦云搖陣色，亂木攪秋声。","周谷雨未散，漢河流尚橫。","春司遲爾策，方用静妖兵。"]', '诗', 'shi', '', NULL, '送李少賓赴舉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2c15180-6f0d-4087-934d-79fd364e25b9', '留別閻士和', '留別閻士和', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["不慣人間別，多應忘別時。","逢山又逢水，只畏却來遲。"]', '["不慣人间別，多應忘別时。","逢山又逢水，只畏却来遲。"]', '诗', 'shi', '', NULL, '留別閻士和 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ad0278-c239-4721-bf78-53385b0905f4', '送李道士', '送李道士', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["常隨山上下，忽限江南北。","共是忘情人，何繇肯相憶。"]', '["常隨山上下，忽限江南北。","共是忘情人，何繇肯相憶。"]', '诗', 'shi', '', NULL, '送李道士 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd7e63d-8c05-4af2-9018-05064797df28', '送裴參軍還下邳舊居', '送裴參軍還下邳旧居', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["北望煙鋪驃騎營，虜烽無火楚天晴。","此時千里西歸客，泗上春風得及耕。"]', '["北望煙鋪驃騎營，虜烽無火楚天晴。","此时千里西归客，泗上春风得及耕。"]', '诗', 'shi', '', NULL, '送裴參軍還下邳舊居 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd9e26f7-052e-4c53-8746-6af2a42e9d72', '送文會上人還富陽', '送文會上人還富陽', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["悠悠渺渺屬寒波，故寺思歸意若何。","長憶孤洲二三月，春山偏愛富春多。"]', '["悠悠渺渺屬寒波，故寺思归意若何。","长憶孤洲二三月，春山偏愛富春多。"]', '诗', 'shi', '', NULL, '送文會上人還富陽 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aa24cb9-01be-4fbb-bee5-3d54ba38ffeb', '送維諒上人歸洞庭', '送維諒上人归洞庭', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["從來湖上勝人間，遠愛浮雲獨自還。","孤月空天見心地，寥寥一水鏡中山。"]', '["從来湖上勝人间，远愛浮云独自還。","孤月空天见心地，寥寥一水镜中山。"]', '诗', 'shi', '', NULL, '送維諒上人歸洞庭 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a820f5-686d-4ce1-94d9-58e2edc15f00', '九月八日送蕭少府歸洪州', '九月八日送蕭少府归洪州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["明日重陽今日歸，布帆絲雨望霏霏。","行過鶴渚知堪住，家在龍沙意有違。"]', '["明日重陽今日归，布帆絲雨望霏霏。","行過鹤渚知堪住，家在龙沙意有違。"]', '诗', 'shi', '', NULL, '九月八日送蕭少府歸洪州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2da814-75d0-4dd9-a34f-1582f214b923', '同顏魯公泛舟送皇甫侍御曾', '同顏魯公泛舟送皇甫侍御曾', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["維舟若許暫從容，送過重江不厭重。","霜簡別來今始見，雪山歸去又難逢。"]', '["維舟若許暫從容，送過重江不厭重。","霜簡別来今始见，雪山归去又难逢。"]', '诗', 'shi', '', NULL, '同顏魯公泛舟送皇甫侍御曾 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ea160b-27f5-4da1-919d-776f3626a246', '送孫侍御遊越', '送孫侍御游越', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["不知持斧客，吟會是何情。","丹陛恩猶在，滄洲賞暫行。","江橈隨月泛，山策逐雪行。","佳句傳零雨，詩流許盛名。"]', '["不知持斧客，吟會是何情。","丹陛恩猶在，滄洲賞暫行。","江橈隨月泛，山策逐雪行。","佳句傳零雨，诗流許盛名。"]', '诗', 'shi', '', NULL, '送孫侍御遊越 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76bc3b65-fb42-4452-9609-867bebe7fb03', '送顏處士還長沙覲省', '送顏处士還长沙覲省', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["西候風信起，三湘孤客心。","天寒漢水廣，鄉遠楚雲深。","服綵將侍膳，擷芳思滿襟。","歸人忘艱阻，別恨獨何任。"]', '["西候风信起，三湘孤客心。","天寒漢水廣，乡远楚云深。","服綵將侍膳，擷芳思满襟。","归人忘艱阻，別恨独何任。"]', '诗', 'shi', '', NULL, '送顏處士還長沙覲省 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc20a02-5750-4224-98ff-908761c51854', '送還本上人遊江西', '送還本上人游江西', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["欲廣分何教，心將江漢期。","雲招望寺處，月待泝杯時。","真侶誰傷別，降猨汝自悲。","多應過廬阜，幽賞却來遲。"]', '["欲廣分何教，心將江漢期。","云招望寺处，月待泝杯时。","真侶誰傷別，降猨汝自悲。","多應過廬阜，幽賞却来遲。"]', '诗', 'shi', '', NULL, '送還本上人遊江西 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86d12ea5-2998-4a34-bd94-c4497c385889', '送路少府使京兼覲侍御兄', '送路少府使京兼覲侍御兄', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["國賦推能吏，今朝發貢湖。","佇瞻雙闕鳳，思見柏臺烏。","樹向秦關遠，江分楚驛孤。","榮君有兄弟，相繼騁長途。"]', '["国賦推能吏，今朝發貢湖。","佇瞻雙闕鳳，思见柏台烏。","樹向秦关远，江分楚驛孤。","榮君有兄弟，相繼騁长途。"]', '诗', 'shi', '', NULL, '送路少府使京兼覲侍御兄 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66692e37-82e5-42af-a89b-3a95b6a18bb5', '於武原從送盧士舉', '於武原從送盧士舉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["落日獨歸客，空山匹馬嘶。","蕭條古關外，岐路更東西。","大澤雲寂寂，長亭雨淒淒。","君還到湘水，寒夜滿猨啼。"]', '["落日独归客，空山匹马嘶。","蕭條古关外，岐路更东西。","大澤云寂寂，长亭雨淒淒。","君還到湘水，寒夜满猨啼。"]', '诗', 'shi', '', NULL, '於武原從送盧士舉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77de2bc3-e57f-4aa7-b682-6d1fd1e5a629', '送烏程李明府得陟狀赴京', '送烏程李明府得陟狀赴京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["驛吏滿江城，深仁見此情。","士林推玉振，公府薦冰清。","爲政移風久，承恩就日行。","仲容綸綍貴，南巷有光榮。"]', '["驛吏满江城，深仁见此情。","士林推玉振，公府薦冰清。","爲政移风久，承恩就日行。","仲容綸綍貴，南巷有光榮。"]', '诗', 'shi', '', NULL, '送烏程李明府得陟狀赴京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42b6ff28-fc0b-4301-858b-f9cfde4b7e95', '送裴秀才往會稽山讀書', '送裴秀才往會稽山读书', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一身齎萬卷，編室寄煙蘿。","硯滴穿池小，書衣種楮多。","吟詩山響荅，泛瑟竹聲和。","鶴板求儒術，深居意若何。"]', '["一身齎万卷，編室寄煙蘿。","硯滴穿池小，书衣種楮多。","吟诗山响荅，泛瑟竹声和。","鹤板求儒術，深居意若何。"]', '诗', 'shi', '', NULL, '送裴秀才往會稽山讀書 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6360624e-cef8-4329-a0b3-93f1bba833d6', '送崔詹事論之上都', '送崔詹事論之上都', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["金虎城池在，銅龍劒珮新。","重看前浦柳，猶憶舊洲蘋。","遠思秦雲暮，歸心臘月春。","青園昔遊處，惆悵別離人。"]', '["金虎城池在，銅龙劒珮新。","重看前浦柳，猶憶旧洲蘋。","远思秦云暮，归心臘月春。","青园昔游处，惆悵別離人。"]', '诗', 'shi', '', NULL, '送崔詹事論之上都 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e5f0de-6788-4f52-ab8b-0bf7bac1d8e8', '京口送盧孟明還揚州', '京口送盧孟明還揚州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["蕭蕭北風起，孤櫂下江濆。","暮客去來盡，春流南北分。","萋萋御亭草，渺渺蕪城雲。","相送目千里，空山獨望君。"]', '["蕭蕭北风起，孤櫂下江濆。","暮客去来尽，春流南北分。","萋萋御亭草，渺渺蕪城云。","相送目千里，空山独望君。"]', '诗', 'shi', '', NULL, '京口送盧孟明還揚州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('803f49d8-542b-4f21-bdbc-2111b7c5916a', '送沙彌大智遊五臺', '送沙彌大智游五台', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["童年隨法侶，家世本儒流。","章句三生學，清涼萬里遊。","雲歸龍沼暗，木落鴈門秋。","長老應相問，傳予向祖州。"]', '["童年隨法侶，家世本儒流。","章句三生学，清涼万里游。","云归龙沼暗，木落鴈门秋。","长老應相问，傳予向祖州。"]', '诗', 'shi', '', NULL, '送沙彌大智遊五臺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eb38dff-a8cc-4790-9e6f-810abaf53f82', '送稟上人遊越', '送稟上人游越', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["雲泉誰不賞，獨見爾情高。","投石輕龍窟，臨流笑鷺濤。","折荷爲片席，灑水淨方袍。","剡路逢禪侶，多應問我曹。"]', '["云泉誰不賞，独见爾情高。","投石轻龙窟，臨流笑鷺濤。","折荷爲片席，灑水淨方袍。","剡路逢禪侶，多應问我曹。"]', '诗', 'shi', '', NULL, '送稟上人遊越 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('596683bb-2f3e-41d2-9999-5bbdc0835442', '送潘秀才之舒州', '送潘秀才之舒州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["楚水清風生，揚舲泛月行。","荻洲寒露彩，雷岸曙潮聲。","東道思才子，西人望客卿。","從來金谷集，相繼有詩名。"]', '["楚水清风生，揚舲泛月行。","荻洲寒露彩，雷岸曙潮声。","东道思才子，西人望客卿。","從来金谷集，相繼有诗名。"]', '诗', 'shi', '', NULL, '送潘秀才之舒州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c276f673-4007-40ed-8fc4-a6dfec5a8266', '送王山人遊廬山', '送王山人游廬山', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["千里訪靈奇，山資亦相隨。","葉舟過鶴市，花漏宿龍池。","峰頂應閑散，人間足別離。","白雲將世事，吾見爾心知。"]', '["千里訪靈奇，山資亦相隨。","葉舟過鹤市，花漏宿龙池。","峰頂應闲散，人间足別離。","白云將世事，吾见爾心知。"]', '诗', 'shi', '', NULL, '送王山人遊廬山 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86facd49-87e1-43d5-b741-b14a0877bb74', '送道契上人之越覲大夫叔', '送道契上人之越覲大夫叔', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["楚僧推後輩，唐本學新經。","外國傳香氎，何人施竹瓶。","秋風別李寺，春日向柯亭。","大阮今爲郡，看君眼最青。"]', '["楚僧推後輩，唐本学新經。","外国傳香氎，何人施竹瓶。","秋风別李寺，春日向柯亭。","大阮今爲郡，看君眼最青。"]', '诗', 'shi', '', NULL, '送道契上人之越覲大夫叔 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f148b8dd-998d-4959-989b-01c5fcf57fed', '送沙彌長文遊京', '送沙彌长文游京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["白版年猶小，黃花褐已通。","若爲詩思逸，早欲似休公。","邁俗多真氣，傳家有素風。","應須學心地，宗旨在關東。"]', '["白版年猶小，黄花褐已通。","若爲诗思逸，早欲似休公。","邁俗多真氣，傳家有素风。","應須学心地，宗旨在关东。"]', '诗', 'shi', '', NULL, '送沙彌長文遊京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64cd7b89-72d8-476e-aa56-fcf28d28ce5c', '秋日送擇高上人往江西謁曹王', '秋日送擇高上人往江西謁曹王', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["超然獨遊趣，無限別山情。","予病不同賞，雲閑應共行。","齋容秋水照，香氎早風輕。","曾被陳王識，遙知江上迎。"]', '["超然独游趣，無限別山情。","予病不同賞，云闲應共行。","斋容秋水照，香氎早风轻。","曾被陳王識，遙知江上迎。"]', '诗', 'shi', '', NULL, '秋日送擇高上人往江西謁曹王 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7309e31f-5147-4cd7-a2b6-82ff85bb4977', '送如獻上人遊長安', '送如獻上人游长安', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["關中四子教猶存，見說新經待爾翻。","爲法應過七祖寺，忘名不到五侯門。","閑尋鄠杜看脩竹，獨上風涼望古原。","高逸詩情無別怨，春遊從遣落花繁。"]', '["关中四子教猶存，见说新經待爾翻。","爲法應過七祖寺，忘名不到五侯门。","闲尋鄠杜看脩竹，独上风涼望古原。","高逸诗情無別怨，春游從遣落花繁。"]', '诗', 'shi', '', NULL, '送如獻上人遊長安 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12715327-00ab-42f0-938f-7ac575c4369c', '日曜上人還潤州', '日曜上人還潤州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["送君何處最堪思，孤月停空欲別時。","露茗猶芳邀重會，寒花落盡不成期。","鶴令先去看山近，雲礙初飛到寺遲。","莫倚禪功放心定，蕭家陵樹誤人悲。"]', '["送君何处最堪思，孤月停空欲別时。","露茗猶芳邀重會，寒花落尽不成期。","鹤令先去看山近，云礙初飞到寺遲。","莫倚禪功放心定，蕭家陵樹誤人悲。"]', '诗', 'shi', '', NULL, '日曜上人還潤州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efa5ff8-f211-4b7f-a230-83cef869fafc', '寺院聽胡笳送李殷', '寺院听胡笳送李殷', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一奏胡笳客未停，野僧還欲廢禪聽。","難將此意臨江別，無限春風葭菼青。"]', '["一奏胡笳客未停，野僧還欲廢禪听。","难將此意臨江別，無限春风葭菼青。"]', '诗', 'shi', '', NULL, '寺院聽胡笳送李殷 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd17e316-87b9-4a64-bdc6-d5cb619bf5e4', '送僧繹', '送僧繹', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["斜日搖揚在柳絲，孤亭寂寂水逶迤。","誰堪別後行人盡，唯有春風起路岐。"]', '["斜日搖揚在柳絲，孤亭寂寂水逶迤。","誰堪別後行人尽，唯有春风起路岐。"]', '诗', 'shi', '', NULL, '送僧繹 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcca4847-f95e-4271-9aea-ea04f166f8dc', '荅裴評事澄荻花間送梁肅拾遺', '荅裴評事澄荻花间送梁肅拾遺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["波上荻花非雪花，風吹撩亂滿袈裟。","如今歲晏無芳草，獨對離樽作物華。"]', '["波上荻花非雪花，风吹撩亂满袈裟。","如今歲晏無芳草，独对離樽作物华。"]', '诗', 'shi', '', NULL, '荅裴評事澄荻花間送梁肅拾遺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d2875fd-05b7-4db6-b58d-fe69e2f1df9b', '送勝雲小師', '送勝云小師', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["昨日雪山記爾名，吾今坐石已三生。","少年道性易流動，莫遣秋風入別情。"]', '["昨日雪山記爾名，吾今坐石已三生。","少年道性易流动，莫遣秋风入別情。"]', '诗', 'shi', '', NULL, '送勝雲小師 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49b136e1-ba54-4338-9959-9aac45592250', '誚士和別', '誚士和別', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["今日同，明日隔，何事悠悠久爲客。","君憐溪上去來雲，我羨磷磷水中石。"]', '["今日同，明日隔，何事悠悠久爲客。","君怜溪上去来云，我羨磷磷水中石。"]', '诗', 'shi', '', NULL, '誚士和別 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4243ce-d7ea-4524-b1bc-afdbccb75945', '送吳馮遊京', '送吳馮游京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["北期何意促，蕙草夜來繁。","清月思淮水，春風望國門。","此時休旋逸，萬里忽飛翻。","若憶山陰會，孤琴爲我援。"]', '["北期何意促，蕙草夜来繁。","清月思淮水，春风望国门。","此时休旋逸，万里忽飞翻。","若憶山陰會，孤琴爲我援。"]', '诗', 'shi', '', NULL, '送吳馮遊京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c49dce5-ed9c-43dc-8375-bed3229dc819', '送僧遊宣州', '送僧游宣州', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["楚山千里一僧行，念爾初緣道未成。","莫向舒姑泉口泊，此中嗚咽爲傷情。"]', '["楚山千里一僧行，念爾初緣道未成。","莫向舒姑泉口泊，此中嗚咽爲傷情。"]', '诗', 'shi', '', NULL, '送僧遊宣州 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aff696be-a91f-4e19-8ecd-6b09c57adb35', '宿支硎寺上房', '宿支硎寺上房', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["上方精舍遠，共宿白雲端。","寂寞千峰夜，蕭條萬木寒。","山光霜下見，松色月中看。","却與西林別，歸心即欲闌。"]', '["上方精舍远，共宿白云端。","寂寞千峰夜，蕭條万木寒。","山光霜下见，松色月中看。","却與西林別，归心即欲闌。"]', '诗', 'shi', '', NULL, '宿支硎寺上房 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3373f5d-d110-4172-8558-4046a87b0f55', '荅胡處士', '荅胡处士', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["西山禪隱比來聞，長道唯應我與君。","書上無名心忘却，人間聚散似浮雲。"]', '["西山禪隐比来闻，长道唯應我與君。","书上無名心忘却，人间聚散似浮云。"]', '诗', 'shi', '', NULL, '荅胡處士 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd73d42-2f25-42c4-9a56-8b325c82f841', '荅張烏程', '荅張烏程', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["莫道謫官無主人，秣陵才令日相親。","前溪更有忘憂處，荷葉田田間白蘋。"]', '["莫道謫官無主人，秣陵才令日相親。","前溪更有忘憂处，荷葉田田间白蘋。"]', '诗', 'shi', '', NULL, '荅張烏程 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('546f24ef-4889-4f0d-90b0-279554000dfb', '酬張明府', '酬張明府', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["愛君詩思動禪心，使我休吟待鶴吟。","更說郡中黃霸在，朝朝無事許招尋。"]', '["愛君诗思动禪心，使我休吟待鹤吟。","更说郡中黄霸在，朝朝無事許招尋。"]', '诗', 'shi', '', NULL, '酬張明府 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed7d4ae-8389-4ede-bfd0-9fdb439b1d33', '勞山居寄呈吳處士', '勞山居寄呈吳处士', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["官居鼎鼐古今無，名士才臣獨一余。","賢閣御題龍墨燦，詔歸補衮在須臾。"]', '["官居鼎鼐古今無，名士才臣独一余。","賢閣御題龙墨燦，詔归補衮在須臾。"]', '诗', 'shi', '', NULL, '勞山居寄呈吳處士 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97dd72e9-9042-4c92-943e-9632baf2097b', '從軍行五首 一', '從軍行五首 一', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["候騎出紛紛，元戎霍冠軍。","漢鞞秋聒地，羌火晝燒雲。","萬里戈城合，三邊羽檄分。","烏孫驅未盡，肯顧遼陽勳。"]', '["候騎出紛紛，元戎霍冠軍。","漢鞞秋聒地，羌火晝燒云。","万里戈城合，三邊羽檄分。","烏孫驱未尽，肯顧遼陽勳。"]', '诗', 'shi', '', NULL, '從軍行五首 一 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a5d1655-e201-4e9e-ac7a-ae583c563707', '從軍行五首 二', '從軍行五首 二', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["韓斾拂丹霄，漢軍新破遼。","紅塵驅鹵簿，白羽擁嫖姚。","戰苦軍猶樂，功高將不驕。","至今丁零塞，朔吹空蕭蕭。"]', '["韓斾拂丹霄，漢軍新破遼。","紅塵驱鹵簿，白羽擁嫖姚。","戰苦軍猶乐，功高將不驕。","至今丁零塞，朔吹空蕭蕭。"]', '诗', 'shi', '', NULL, '從軍行五首 二 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('191fa949-63bc-435b-8ed6-950484a6ac87', '從軍行五首 三', '從軍行五首 三', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["百萬逐呼韓，頻年不解鞍。","兵屯絕漠暗，馬飲濁河乾。","破虜功未錄，勞師力已殫。","須防肘腋下，飛禍出無端。"]', '["百万逐呼韓，頻年不解鞍。","兵屯絕漠暗，马饮濁河乾。","破虜功未錄，勞師力已殫。","須防肘腋下，飞禍出無端。"]', '诗', 'shi', '', NULL, '從軍行五首 三 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37cec46c-16fe-40f9-8610-845d552c562f', '從軍行五首 四', '從軍行五首 四', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["飛將下天來，奇謀閫外裁。","水心龍劒動，地肺鴈山開。","望氣燕師銳，當鋒虜陣摧。","從今射鵰騎，不敢過雲堆。"]', '["飞將下天来，奇謀閫外裁。","水心龙劒动，地肺鴈山开。","望氣燕師銳，當鋒虜陣摧。","從今射鵰騎，不敢過云堆。"]', '诗', 'shi', '', NULL, '從軍行五首 四 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05b15565-3921-4c2a-b7c9-a1fb6ff8cd58', '從軍行五首 五', '從軍行五首 五', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["黃紙君王詔，青泥校尉書。","誓師張虎落，選將擐犀渠。","霧暗津蒲失，天寒塞柳疎。","橫行十萬騎，欲掃虜塵餘。"]', '["黄紙君王詔，青泥校尉书。","誓師張虎落，選將擐犀渠。","霧暗津蒲失，天寒塞柳疎。","橫行十万騎，欲掃虜塵餘。"]', '诗', 'shi', '', NULL, '從軍行五首 五 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5272bdd9-1aec-4937-b764-a6c1294b4205', '隴頭水二首 一', '隴头水二首 一', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["隴頭水欲絕，隴水不堪聞。","碎影搖槍壘，寒聲咽幔軍。","素從鹽海積，綠帶柳城分。","日落天邊望，逶迤入寒雲。"]', '["隴头水欲絕，隴水不堪闻。","碎影搖槍壘，寒声咽幔軍。","素從鹽海積，綠带柳城分。","日落天邊望，逶迤入寒云。"]', '诗', 'shi', '', NULL, '隴頭水二首 一 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83527647-593d-4e2e-94d4-fdc41689c95d', '隴頭水二首 二', '隴头水二首 二', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["秦隴逼氐羌，征人去未央。","如何幽咽水，併欲斷君腸。","西注悲窮漠，東分憶故鄉。","旅魂聲攪亂，無夢到咸陽。"]', '["秦隴逼氐羌，征人去未央。","如何幽咽水，併欲斷君腸。","西注悲窮漠，东分憶故乡。","旅魂声攪亂，無梦到咸陽。"]', '诗', 'shi', '', NULL, '隴頭水二首 二 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9439ec50-08ff-4eef-a2e4-7da211440b49', '塞下曲二首 一', '塞下曲二首 一', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["寒塞無因見落梅，胡人吹入笛聲來。","勞勞亭上春應度，夜夜城南戰未迴。"]', '["寒塞無因见落梅，胡人吹入笛声来。","勞勞亭上春應度，夜夜城南戰未迴。"]', '诗', 'shi', '', NULL, '塞下曲二首 一 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59a6c0a-3019-4d54-9a34-f7fbed9e13bc', '塞下曲二首 二', '塞下曲二首 二', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["都護今年破武威，胡沙萬里鳥空飛。","旄竿瀚海掃雲出，氈騎天山蹋雪歸。"]', '["都護今年破武威，胡沙万里鸟空飞。","旄竿瀚海掃云出，氈騎天山蹋雪归。"]', '诗', 'shi', '', NULL, '塞下曲二首 二 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f885a40-7601-4ae1-b885-afa5562f07c5', '覽史', '覽史', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["黃綺皆皓髮，秦時隱商山。","嘉謀匡帝道，高步遊天關。","不愛珪組紲，却思林壑還。","放歌長松下，日與孤雲閑。"]', '["黄綺皆皓髮，秦时隐商山。","嘉謀匡帝道，高步游天关。","不愛珪組紲，却思林壑還。","放歌长松下，日與孤云闲。"]', '诗', 'shi', '', NULL, '覽史 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e99c18-4408-46a5-aaac-9875ef05cb68', '詠史', '詠史', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["獨負高世資，冥冥寄浮俗。","卞子去不歸，何人辯荆玉。","鬻舂意不淺，汚迹身豈辱。","鸞鎩樂迍邅，虬蟠甘窘束。","五噫譎且正，可以見心曲。"]', '["独負高世資，冥冥寄浮俗。","卞子去不归，何人辯荆玉。","鬻舂意不淺，汚迹身豈辱。","鸾鎩乐迍邅，虬蟠甘窘束。","五噫譎且正，可以见心曲。"]', '诗', 'shi', '', NULL, '詠史 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9812eed-7e8d-4680-bfcd-187b20b1889f', '詠史', '詠史', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["田氏門下客，馮公衆中賤。","一朝市義還，百代名獨擅。","始知下客不可輕，能使主人功業成。","借問高車與珠履，何如卑賤一書生。"]', '["田氏门下客，馮公衆中賤。","一朝市義還，百代名独擅。","始知下客不可轻，能使主人功業成。","借问高车與珠履，何如卑賤一书生。"]', '诗', 'shi', '', NULL, '詠史 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ff6d91f-2f0b-403e-be77-1763e842d62f', '讀張曲江集', '读張曲江集', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["相公乃天蓋，人文佐生成。","立程正頹靡，繹思何縱橫。","春杼弄緗綺，陽林敷玉英。","飄然飛動姿，邈矣高簡情。","後輩驚失步，前修敢爭衡。","始欣耳目遠，再使機慮清。","體正力已全，理精識何妙。","昔年歌陽春，徒推郢中調。","今朝聽鸞鳳，豈獨羨門嘯。","帝命鎮雄州，待濟寄上流。","才兼荆衡秀，氣助瀟湘秋。","逸蕩子山匹，經奇文暢儔。","沈吟未終卷，變態紛難數。","曜耳代明璫，襲衣同芳杜。","愔愔聞玉磬，寤寐在靈府。"]', '["相公乃天蓋，人文佐生成。","立程正頹靡，繹思何縱橫。","春杼弄緗綺，陽林敷玉英。","飄然飞动姿，邈矣高簡情。","後輩驚失步，前修敢爭衡。","始欣耳目远，再使機慮清。","體正力已全，理精識何妙。","昔年歌陽春，徒推郢中調。","今朝听鸾鳳，豈独羨门嘯。","帝命鎮雄州，待濟寄上流。","才兼荆衡秀，氣助瀟湘秋。","逸蕩子山匹，經奇文暢儔。","沈吟未終卷，变態紛难數。","曜耳代明璫，襲衣同芳杜。","愔愔闻玉磬，寤寐在靈府。"]', '诗', 'shi', '', NULL, '讀張曲江集 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77ee5e3c-0aea-4164-b277-091b9534e0aa', '奉酬陸使君見過各賦院中一物得江蘺', '奉酬陸使君见過各賦院中一物得江蘺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["江蘺生古砌，花每落禪床。","嘉客未採掇，空門自馨香。","名因詩目見，色對道心忘。","不遇陸內史，誰知殊衆芳。"]', '["江蘺生古砌，花每落禪床。","嘉客未採掇，空门自馨香。","名因诗目见，色对道心忘。","不遇陸內史，誰知殊衆芳。"]', '诗', 'shi', '', NULL, '奉酬陸使君見過各賦院中一物得江蘺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d800b4ee-588c-43a4-a256-61c32096c664', '賦得謝墅送王長史', '賦得謝墅送王长史', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["世業西山墅，移家長我身。","蕭疎遺樹老，寂寞廢田春。","車巷傷前轍，籬溝憶舊隣。","何堪再過日，更送北歸人。"]', '["世業西山墅，移家长我身。","蕭疎遺樹老，寂寞廢田春。","车巷傷前轍，籬溝憶旧隣。","何堪再過日，更送北归人。"]', '诗', 'shi', '', NULL, '賦得謝墅送王長史 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cee75e7-ed9f-4d4e-b7a6-4686a2aa4806', '夏日同崔使君論登城樓賦得遠山', '夏日同崔使君論登城楼賦得远山', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["遠山湖上小，青翠望依稀。","纔向窗中列，還從林表微。","色濃春草在，峰起夏雲歸。","不是蓬萊島，如何人去稀。"]', '["远山湖上小，青翠望依稀。","纔向窗中列，還從林表微。","色濃春草在，峰起夏云归。","不是蓬萊島，如何人去稀。"]', '诗', 'shi', '', NULL, '夏日同崔使君論登城樓賦得遠山 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc22f815-b1f7-4503-8bef-4ca8376cfbc1', '詠數探得七', '詠數探得七', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["鄒子譚天歲，黃童對日年。","求真初作傳，鍊魄已成仙。","鶴駕迎緱嶺，星橋下蜀川。","逢君竹林客，相對弄清絃。"]', '["鄒子譚天歲，黄童对日年。","求真初作傳，鍊魄已成仙。","鹤駕迎緱嶺，星橋下蜀川。","逢君竹林客，相对弄清絃。"]', '诗', 'shi', '', NULL, '詠數探得七 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87a7ee00-8b78-4550-8957-93f9d006b994', '奉同顏使君真卿送李侍御萼賦得荻塘路', '奉同顏使君真卿送李侍御萼賦得荻塘路', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["落日車遙遙，客心在歸路。","細草暗回塘，春泉縈古渡。","遺蹤歎蕪沒，遠道悲去住。","寂寞荻花空，行人別無數。"]', '["落日车遙遙，客心在归路。","細草暗回塘，春泉縈古渡。","遺蹤歎蕪沒，远道悲去住。","寂寞荻花空，行人別無數。"]', '诗', 'shi', '', NULL, '奉同顏使君真卿送李侍御萼賦得荻塘路 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a02583c-9b2a-4e41-a7fa-6524219e97eb', '賦顏氏古今一事得晉仙傳送顏逸', '賦顏氏古今一事得晉仙傳送顏逸', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["曾看顏氏傳，多記晉時仙。","却憶桐君老，俱還桂父年。","青春留鬢髮，白日向雲煙。","遠別賷遺簡，囊中有幾篇。"]', '["曾看顏氏傳，多記晉时仙。","却憶桐君老，俱還桂父年。","青春留鬢髮，白日向云煙。","远別賷遺簡，囊中有幾篇。"]', '诗', 'shi', '', NULL, '賦顏氏古今一事得晉仙傳送顏逸 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('745f741a-151f-48c7-94c9-bb8a314c197e', '賦得石梁泉送崔逵', '賦得石梁泉送崔逵', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["架石通霞壁，懸崖散碧沙。","天晴虹影渡，風細練文斜。","舉陟幽期阻，沿洄客意賒。","河梁非此路，別恨亦無涯。"]', '["架石通霞壁，懸崖散碧沙。","天晴虹影渡，风細練文斜。","舉陟幽期阻，沿洄客意賒。","河梁非此路，別恨亦無涯。"]', '诗', 'shi', '', NULL, '賦得石梁泉送崔逵 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6dd43ba-4310-41c8-9583-27c6d53d28b6', '賦得夜雨滴空堦送陸羽歸龍山', '賦得夜雨滴空堦送陸羽归龙山', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["閑堦夜雨滴，偏入別情中。","斷續清猨應，淋漓候館空。","氣令煩慮散，時與早秋同。","歸客龍山道，東來雜好風。"]', '["闲堦夜雨滴，偏入別情中。","斷續清猨應，淋漓候館空。","氣令煩慮散，时與早秋同。","归客龙山道，东来杂好风。"]', '诗', 'shi', '', NULL, '賦得夜雨滴空堦送陸羽歸龍山 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9f435e-e8c4-45c1-b7a2-e1244e002fa4', '賦得燈心送李侍御萼', '賦得灯心送李侍御萼', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["燈心生衆草，因有始知芳。","綵妓窗偏麗，金桃動更香。","花驚春未盡，焰喜夜初長。","別後空離室，何人借末光。"]', '["灯心生衆草，因有始知芳。","綵妓窗偏丽，金桃动更香。","花驚春未尽，焰喜夜初长。","別後空離室，何人借末光。"]', '诗', 'shi', '', NULL, '賦得燈心送李侍御萼 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30bb80ff-ab37-4cce-ba84-6183bdd55787', '賦得竹如意送詳師赴講', '賦得竹如意送詳師赴講', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["縹竹湘南美，吾師尚毀形。","仍留負霜節，不變在林青。","每入楊枝手，因談貝葉經。","誰期沃州講，持此別東亭。"]', '["縹竹湘南美，吾師尚毀形。","仍留負霜節，不变在林青。","每入楊枝手，因談貝葉經。","誰期沃州講，持此別东亭。"]', '诗', 'shi', '', NULL, '賦得竹如意送詳師赴講 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc5531b-5101-49ed-937b-19ec3037906e', '聽素法師講法華經', '听素法師講法华經', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["法子出西秦，名齊漆道人。","纔敷藥草義，便見雪山春。","護講龍來遠，聞經鶴下頻。","應機如一雨，誰不滌心塵。"]', '["法子出西秦，名齊漆道人。","纔敷藥草義，便见雪山春。","護講龙来远，闻經鹤下頻。","應機如一雨，誰不滌心塵。"]', '诗', 'shi', '', NULL, '聽素法師講法華經 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('458df517-cfbb-4932-b3d9-2a9e0f9f1efd', '詠敭上人座右畫松', '詠敭上人座右畫松', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["寫得長松意，千尋數尺中。","翠陰疑背日，寒色欲生風。","真樹孤標在，高人立操同。","一枝遙可折，吾欲問生公。"]', '["寫得长松意，千尋數尺中。","翠陰疑背日，寒色欲生风。","真樹孤標在，高人立操同。","一枝遙可折，吾欲问生公。"]', '诗', 'shi', '', NULL, '詠敭上人座右畫松 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c53cc0fc-164a-4d47-bd2d-3183e60716dc', '夏日登觀農樓和崔使君', '夏日登观農楼和崔使君', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["片雨拂簷楹，煩襟四坐清。","霏微過麥隴，蕭散傍莎城。","靜愛和花落，幽聞入竹聲。","朝觀趣無限，高詠寄深情。"]', '["片雨拂簷楹，煩襟四坐清。","霏微過麦隴，蕭散傍莎城。","静愛和花落，幽闻入竹声。","朝观趣無限，高詠寄深情。"]', '诗', 'shi', '', NULL, '夏日登觀農樓和崔使君 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70fd00a6-8f6b-45c5-9233-8df1c067af27', '妙喜寺逵公院賦得夜磬送呂評事', '妙喜寺逵公院賦得夜磬送呂評事', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一磬寒山至，凝心轉清越。","細和虛籟盡，疎繞懸泉發。","在夜吟更長，停空韻難絕。","幽僧悟深定，歸客忘遠別。","寂歷無性中，真聲何起滅。"]', '["一磬寒山至，凝心轉清越。","細和虛籟尽，疎繞懸泉發。","在夜吟更长，停空韻难絕。","幽僧悟深定，归客忘远別。","寂歷無性中，真声何起滅。"]', '诗', 'shi', '', NULL, '妙喜寺逵公院賦得夜磬送呂評事 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0e7fc56-c2c2-4369-9056-a8a2c2eb5b59', '詠小瀑布', '詠小瀑布', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["瀑布小更奇，潺湲二三尺。","細脉穿亂沙，叢聲咽危石。","初因智者賞，果會幽人跡。","不向定中聞，那知我心寂。"]', '["瀑布小更奇，潺湲二三尺。","細脉穿亂沙，叢声咽危石。","初因智者賞，果會幽人跡。","不向定中闻，那知我心寂。"]', '诗', 'shi', '', NULL, '詠小瀑布 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e95ac284-a766-4f68-86cb-2d3c5ed2f343', '僊女臺', '僊女台', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["寂寂舊桑田，誰家女得僊。","應無雞犬在，空有子孫傳。","古木花猶發，荒臺路未遷。","暮來雲一片，疑是欲歸年。"]', '["寂寂旧桑田，誰家女得僊。","應無雞犬在，空有子孫傳。","古木花猶發，荒台路未遷。","暮来云一片，疑是欲归年。"]', '诗', 'shi', '', NULL, '僊女臺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cdca8d5-33d5-42ee-9563-65705d230d25', '靈澈上人何山寺七賢石詩', '靈澈上人何山寺七賢石诗', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["七石配七賢，隱僧山上移。","石性殊磊落，君子又高奇。","跂禪服宜壞，坐客冠可隳。","夜倚月樹影，晝傾風竹枝。","集質患追琢，表頑用磷緇。","佚火玉亦害，塊然長在茲。"]', '["七石配七賢，隐僧山上移。","石性殊磊落，君子又高奇。","跂禪服宜壞，坐客冠可隳。","夜倚月樹影，晝傾风竹枝。","集質患追琢，表頑用磷緇。","佚火玉亦害，塊然长在茲。"]', '诗', 'shi', '', NULL, '靈澈上人何山寺七賢石詩 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('620ec4d0-eaf2-420b-a6bd-6eff4dfa685e', '潘丞孩子', '潘丞孩子', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["愛子性情奇，初生玉樹枝。","人曾天上見，名向月中知。","我識嬰兒意，何須待佩觿。"]', '["愛子性情奇，初生玉樹枝。","人曾天上见，名向月中知。","我識嬰兒意，何須待佩觿。"]', '诗', 'shi', '', NULL, '潘丞孩子 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3438d68-b266-4d5a-a52d-9640ecfa2f93', '南池雜詠五首 水月', '南池杂詠五首 水月', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["夜夜池上觀，禪身坐月邊。","虛無色可取，皎潔意難傳。","若向空心了，長如影正圓。"]', '["夜夜池上观，禪身坐月邊。","虛無色可取，皎潔意难傳。","若向空心了，长如影正圓。"]', '诗', 'shi', '', NULL, '南池雜詠五首 水月 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1528b27-d4f2-458c-b755-c60c0e53a111', '南池雜詠五首 溪雲', '南池杂詠五首 溪云', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["舒卷意何窮，縈流復帶空。","有形不累物，無迹去隨風。","莫怪長相逐，飄然與我同。"]', '["舒卷意何窮，縈流复带空。","有形不累物，無迹去隨风。","莫怪长相逐，飄然與我同。"]', '诗', 'shi', '', NULL, '南池雜詠五首 溪雲 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3099b9b0-2454-4e75-8d51-947f01a3485f', '南池雜詠五首 虛舟', '南池杂詠五首 虛舟', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["虛舟動又靜，忽似去逢時。","觸物知無迕，爲梁幸見遺。","因風到此岸，非有濟川期。"]', '["虛舟动又静，忽似去逢时。","觸物知無迕，爲梁幸见遺。","因风到此岸，非有濟川期。"]', '诗', 'shi', '', NULL, '南池雜詠五首 虛舟 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bec7d92-c885-42f1-a4d4-31bd72bb5c03', '南池雜詠五首 寒山', '南池杂詠五首 寒山', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["侵空撩亂色，獨愛我中峰。","無事負輕策，閑行躡幽踪。","衆山搖落盡，寒翠更重重。"]', '["侵空撩亂色，独愛我中峰。","無事負轻策，闲行躡幽踪。","衆山搖落尽，寒翠更重重。"]', '诗', 'shi', '', NULL, '南池雜詠五首 寒山 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('129eea93-a072-40f8-82e4-ee1c7a10d040', '南池雜詠五首 寒竹', '南池杂詠五首 寒竹', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["褭褭孤生竹，獨立山中雪。","蒼翠搖動風，嬋娟帶寒月。","狂花不相似，還共凌冬發。"]', '["褭褭孤生竹，独立山中雪。","蒼翠搖动风，嬋娟带寒月。","狂花不相似，還共凌冬發。"]', '诗', 'shi', '', NULL, '南池雜詠五首 寒竹 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58c91a06-3e08-4d81-892e-7ae8afc5f409', '望遠村', '望远村', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["林杪不可分，水步遙難辨。","一片山翠邊，依稀見村遠。"]', '["林杪不可分，水步遙难辨。","一片山翠邊，依稀见村远。"]', '诗', 'shi', '', NULL, '望遠村 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e7b894-4ed6-400a-aa0b-f59da5d838d6', '惜暮景', '惜暮景', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["疎陰花不動，片景松梢度。","夏日舊來長，佳遊何易暮。"]', '["疎陰花不动，片景松梢度。","夏日旧来长，佳游何易暮。"]', '诗', 'shi', '', NULL, '惜暮景 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf14fe00-0553-4519-9482-37eceabce9d1', '效古', '效古', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["日出天地正，煌煌闢晨曦。","六龍驅羣動，古今無盡時。","夸父亦何愚，競走先自疲。","飲乾咸池水，折盡扶桑枝。","渴死化爝火，嗟嗟徒爾爲。","空留鄧林在，折盡令人嗤。"]', '["日出天地正，煌煌闢晨曦。","六龙驱羣动，古今無尽时。","夸父亦何愚，競走先自疲。","饮乾咸池水，折尽扶桑枝。","渴死化爝火，嗟嗟徒爾爲。","空留鄧林在，折尽令人嗤。"]', '诗', 'shi', '', NULL, '效古 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c40a679-b659-4773-8737-7b37a226dcc3', '古別離', '古別離', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["太湖三山口，吳王在時道。","寂寞千載心，無人見春草。","誰識緘怨者，持此傷懷抱。","孤舟畏狂風，一點宿煙島。","望所思兮若何，月蕩漾兮空波。","雲離離兮北斷，鴻眇眇兮南多。","身去兮天畔，心折兮湖岸。","春風胡爲兮塞路，使我歸夢兮撩亂。"]', '["太湖三山口，吳王在时道。","寂寞千載心，無人见春草。","誰識緘怨者，持此傷懷抱。","孤舟畏狂风，一点宿煙島。","望所思兮若何，月蕩漾兮空波。","云離離兮北斷，鴻眇眇兮南多。","身去兮天畔，心折兮湖岸。","春风胡爲兮塞路，使我归梦兮撩亂。"]', '诗', 'shi', '', NULL, '古別離 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('965c0cc3-6966-41d7-b599-eb83a6ee328d', '擬長安春詞', '擬长安春词', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春信在河源，春風蕩妾魂。","春歌雜鶗鴂，春夢繞轘轅。","春絮愁偏滿，春絲悶更繁。","春期不可定，春曲嬾新翻。"]', '["春信在河源，春风蕩妾魂。","春歌杂鶗鴂，春梦繞轘轅。","春絮愁偏满，春絲悶更繁。","春期不可定，春曲嬾新翻。"]', '诗', 'shi', '', NULL, '擬長安春詞 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f7aa672-9a8a-4334-b044-48ade354289d', '效古', '效古', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["思君轉戰度交河，強弄胡琴不成曲。","日落應愁隴底難，春來定夢江南數。","萬丈游絲是妾心，惹蝶縈花亂相續。"]', '["思君轉戰度交河，強弄胡琴不成曲。","日落應愁隴底难，春来定梦江南數。","万丈游絲是妾心，惹蝶縈花亂相續。"]', '诗', 'shi', '', NULL, '效古 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('317b0c79-babb-40a4-986a-2a05ee5511b5', '昭君怨', '昭君怨', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["自倚嬋娟望主恩，誰知美惡忽相翻。","黃金不買漢宮貌，青塚空埋胡地魂。"]', '["自倚嬋娟望主恩，誰知美惡忽相翻。","黄金不買漢宮貌，青塚空埋胡地魂。"]', '诗', 'shi', '', NULL, '昭君怨 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6df100f-c72d-43ce-ab45-c264abb61961', '銅雀妓', '銅雀妓', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["強開尊酒向陵看，憶得君王舊日懽。","不覺餘歌悲自斷，非關豔曲轉聲難。"]', '["強开尊酒向陵看，憶得君王旧日懽。","不覺餘歌悲自斷，非关豔曲轉声难。"]', '诗', 'shi', '', NULL, '銅雀妓 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5511ce66-c137-479b-b99f-b0a1df5c479d', '長門怨', '长门怨', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春風日日閉長門，搖蕩春心似夢魂。","誰遣花開只笑妾，不如桃李正無言。"]', '["春风日日閉长门，搖蕩春心似梦魂。","誰遣花开只笑妾，不如桃李正無言。"]', '诗', 'shi', '', NULL, '長門怨 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf69e622-5338-4418-8989-d15d34df68a7', '哭吳縣房聳明府', '哭吳縣房聳明府', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["仁人邁厚德，可謂名實全。","撫迹若疎曠，會心極精研。","履危節詎屈，著論識不偏。","恨以榮級淺，嘉猷未及宣。","伊人期遠大，志業難比肩。","昭世既合幷，吾君藉陶甄。","奈何明明理，與善徒空詮。","徵教或稽聖，窮源反問天。","一官自吳邑，六翮委江壖。","始是牽絲日，翻成撤瑟年。","金膏果不就，玉珮長此捐。","倚伏信冥昧，夭修驚後先。","安知忘情子，愛網素已褰。","爲有深仁感，遂令真性遷。","心悲空林下，淚灑秋景前。","夫子寡兄弟，撫孤傷藐然。","傾雲爲慘結，弔鶴共聯翩。","割念命歸駕，訣詞向空筵。","樹桃陰始合，愛客位常懸。","幡然遠行時，崇望歸朝旋。","悟茲懽宴隔，哀被歲月延。","書帶變芳草，履痕移綠錢。","冥期儻可逢，生盡會無緣。","幸願示因業，代君運精專。","相思轉寂寞，獨往西林泉。","欲見故人心，時閱所贈篇。","素高陶靖節，今重楚先賢。","芳躅將遺愛，可爲終古傳。"]', '["仁人邁厚德，可謂名實全。","撫迹若疎曠，會心極精研。","履危節詎屈，著論識不偏。","恨以榮級淺，嘉猷未及宣。","伊人期远大，志業难比肩。","昭世既合幷，吾君藉陶甄。","奈何明明理，與善徒空詮。","徵教或稽聖，窮源反问天。","一官自吳邑，六翮委江壖。","始是牽絲日，翻成撤瑟年。","金膏果不就，玉珮长此捐。","倚伏信冥昧，夭修驚後先。","安知忘情子，愛網素已褰。","爲有深仁感，遂令真性遷。","心悲空林下，泪灑秋景前。","夫子寡兄弟，撫孤傷藐然。","傾云爲慘結，弔鹤共聯翩。","割念命归駕，訣词向空筵。","樹桃陰始合，愛客位常懸。","幡然远行时，崇望归朝旋。","悟茲懽宴隔，哀被歲月延。","书带变芳草，履痕移綠錢。","冥期儻可逢，生尽會無緣。","幸願示因業，代君運精專。","相思轉寂寞，独往西林泉。","欲见故人心，时閱所贈篇。","素高陶靖節，今重楚先賢。","芳躅將遺愛，可爲終古傳。"]', '诗', 'shi', '', NULL, '哭吳縣房聳明府 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5db6676b-b9f6-40e8-805a-6b41df421081', '哭覺上人', '哭覺上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["憶君南適越，不作買山期。","昨得耶溪信，翻爲逝水悲。","神交如可見，生盡杳難思。","白日東林下，空懷步影時。"]', '["憶君南適越，不作買山期。","昨得耶溪信，翻爲逝水悲。","神交如可见，生尽杳难思。","白日东林下，空懷步影时。"]', '诗', 'shi', '', NULL, '哭覺上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6159289b-17fb-4d40-91eb-2a78ab7836ef', '題餘不溪廢寺', '題餘不溪廢寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["武原離亂後，真界積塵埃。","殘月生秋水，悲風起故臺。","居人今已盡，棲鴿暝還來。","不到無生理，應堪賦七哀。"]', '["武原離亂後，真界積塵埃。","殘月生秋水，悲风起故台。","居人今已尽，棲鴿暝還来。","不到無生理，應堪賦七哀。"]', '诗', 'shi', '', NULL, '題餘不溪廢寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a081af9-da14-448e-90b1-7768a2b7ba88', '同李洗馬入餘不溪經辛將軍故城', '同李洗马入餘不溪經辛將軍故城', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["慘慘寒城望，將軍下世時。","高墉暮草遍，大樹野風悲。","壁壘今惟在，勳庸近可思。","蒼然古溪上，川逝共悽其。"]', '["慘慘寒城望，將軍下世时。","高墉暮草遍，大樹野风悲。","壁壘今惟在，勳庸近可思。","蒼然古溪上，川逝共悽其。"]', '诗', 'shi', '', NULL, '同李洗馬入餘不溪經辛將軍故城 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2ef3d8-c8f1-48d7-a74c-cca3dc21e258', '憶天台', '憶天台', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["箬溪朝雨散，雲色似天台。","應是東風便，吹從海上來。","靈山遊汗漫，仙石過莓苔。","誤到人間世，經年不早迴。"]', '["箬溪朝雨散，云色似天台。","應是东风便，吹從海上来。","靈山游汗漫，仙石過莓苔。","誤到人间世，經年不早迴。"]', '诗', 'shi', '', NULL, '憶天台 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf875959-7cd6-466b-b8ce-1b7489a678b6', '萬回寺', '万回寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["萬里稱逆化，愚惷性亦全。","紫紱拖身上，妖姬安膝前。","見他拘坐寂，故我是眠禪。","吾知至人心，杳若青冥天。"]', '["万里稱逆化，愚惷性亦全。","紫紱拖身上，妖姬安膝前。","见他拘坐寂，故我是眠禪。","吾知至人心，杳若青冥天。"]', '诗', 'shi', '', NULL, '萬回寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ac50c7c-8aae-43ac-a75c-ffcc573f3e18', '禪詩', '禪诗', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["萬法出無門，紛紛使智昏。","徒稱誰氏子，獨立天地元。","實際且何有，物先安可存。","須知不動念，照山萬重源。"]', '["万法出無门，紛紛使智昏。","徒稱誰氏子，独立天地元。","實際且何有，物先安可存。","須知不动念，照山万重源。"]', '诗', 'shi', '', NULL, '禪詩 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a630a4e0-d48a-4c21-9b16-d04a15f7a68e', '哀教', '哀教', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["本師不得已，強爲我著書。","知盡百慮遣，名存萬象拘。","如何工言子，終日論虛無。","伊人獨冥冥，時人以爲愚。"]', '["本師不得已，強爲我著书。","知尽百慮遣，名存万象拘。","如何工言子，終日論虛無。","伊人独冥冥，时人以爲愚。"]', '诗', 'shi', '', NULL, '哀教 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad05f3da-4b0a-47f7-8521-9ccb311f94ae', '聞鐘', '闻鐘', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["古寺寒山上，遠鐘揚好風。","聲餘月樹動，響盡霜天空。","永夜一禪子，泠然心境中。"]', '["古寺寒山上，远鐘揚好风。","声餘月樹动，响尽霜天空。","永夜一禪子，泠然心境中。"]', '诗', 'shi', '', NULL, '聞鐘 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('386d0201-97d3-491c-8c69-2ffa31bacd83', '溪上月', '溪上月', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["秋水月娟娟，初生色界天。","蟾光散浦溆，素影動淪漣。","何事無心見，虧盈向夜禪。"]', '["秋水月娟娟，初生色界天。","蟾光散浦溆，素影动淪漣。","何事無心见，虧盈向夜禪。"]', '诗', 'shi', '', NULL, '溪上月 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d90ebdd-324e-40ef-9365-70b499cea039', '山雪', '山雪', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["夕陽在西峰，疊翠縈殘雪。","狂風卷絮迴，驚猨攀玉折。","何意山中人，誤報山花發。"]', '["夕陽在西峰，叠翠縈殘雪。","狂风卷絮迴，驚猨攀玉折。","何意山中人，誤報山花發。"]', '诗', 'shi', '', NULL, '山雪 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92cc0e07-5194-4e9f-950c-2f9ed7a62ab0', '江上風', '江上风', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["江風西復東，飄暴忽何窮。","初生虛無際，稍起蕩漾中。","應吹夏口檣竿折，定蹙湓城浪花咽。","今朝莫怪沙岸明，昨夜聲狂卷成雪。"]', '["江风西复东，飄暴忽何窮。","初生虛無際，稍起蕩漾中。","應吹夏口檣竿折，定蹙湓城浪花咽。","今朝莫怪沙岸明，昨夜声狂卷成雪。"]', '诗', 'shi', '', NULL, '江上風 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f50085c3-cb5a-4c1f-8b96-31fde4920e2c', '山雨', '山雨', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一片雨，山半晴。","長風吹落西山上，滿樹蕭蕭心耳清。","雲鶴驚亂下，水香凝不然。","風迴雨定芭蕉濕，一滴時時入晝禪。"]', '["一片雨，山半晴。","长风吹落西山上，满樹蕭蕭心耳清。","云鹤驚亂下，水香凝不然。","风迴雨定芭蕉濕，一滴时时入晝禪。"]', '诗', 'shi', '', NULL, '山雨 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f0efffd-61e5-412c-9804-789f66959bbc', '問遙山禪老', '问遙山禪老', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["天與松子壽，獨飲日月精。","復令顏子賢，胡爲夭其生。","吾將尋河源，上天問天何不平。","我將詰仙老，大道無私誰強名。","仙老難逢天不近，世人何人解應盡。","明朝欲向翅頭山，問取禪公此義還。"]', '["天與松子壽，独饮日月精。","复令顏子賢，胡爲夭其生。","吾將尋河源，上天问天何不平。","我將詰仙老，大道無私誰強名。","仙老难逢天不近，世人何人解應尽。","明朝欲向翅头山，问取禪公此義還。"]', '诗', 'shi', '', NULL, '問遙山禪老 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d5e4e6-c84a-438d-b8e1-21b9fd7ef71d', '禪思', '禪思', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["真我性無主，誰爲塵識昏。","奈何求其本，若拔大木根。","妄以一念動，勢如千波翻。","傷哉子桑扈，蟲臂徒虛言。","神威興外論，宗邪生異源。","空何妨色在，妙豈廢身存。","寂滅本非寂，諠譁曾未諠。","嗟嗟世上禪，不共智者論。"]', '["真我性無主，誰爲塵識昏。","奈何求其本，若拔大木根。","妄以一念动，勢如千波翻。","傷哉子桑扈，蟲臂徒虛言。","神威兴外論，宗邪生異源。","空何妨色在，妙豈廢身存。","寂滅本非寂，諠譁曾未諠。","嗟嗟世上禪，不共智者論。"]', '诗', 'shi', '', NULL, '禪思 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('491b93f3-1668-4472-ab79-9c71145eefd1', '支公詩', '支公诗', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["支公養馬復養鶴，率性無機多脫畧。","天生支公與凡異，凡情不到支公地。","得道繇來天上仙，爲僧却下人間寺。","道家諸子論自然，此公唯許逍遙篇。","山陰詩友喧四座，佳句縱橫不廢禪。"]', '["支公養马复養鹤，率性無機多脫畧。","天生支公與凡異，凡情不到支公地。","得道繇来天上仙，爲僧却下人间寺。","道家諸子論自然，此公唯許逍遙篇。","山陰诗友喧四座，佳句縱橫不廢禪。"]', '诗', 'shi', '', NULL, '支公詩 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('882a0ebe-aac5-43ee-8624-0c3cf9e0a00d', '述夢', '述梦', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["夢中歸見西陵雪，渺渺茫茫行路絕。","覺來還在剡東峰，鄉心繚繞愁夜鐘。","寺北禪岡猶記得，夢歸長見山重重。"]', '["梦中归见西陵雪，渺渺茫茫行路絕。","覺来還在剡东峰，乡心繚繞愁夜鐘。","寺北禪岡猶記得，梦归长见山重重。"]', '诗', 'shi', '', NULL, '述夢 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b882bbc-71d0-4c8a-b54a-5c6ac07663bf', '赤松', '赤松', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["緣岸蒙籠出見天，晴沙瀝瀝水濺濺。","何處羽人長洗藥，殘花無數逐流泉。"]', '["緣岸蒙籠出见天，晴沙瀝瀝水濺濺。","何处羽人长洗藥，殘花無數逐流泉。"]', '诗', 'shi', '', NULL, '赤松 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ea657a9-5995-425b-803d-06ac1e9ae43e', '戲題松樹', '戲題松樹', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["爲愛松聲聽不足，每逢松樹遂忘還。","翛然此外更何事，笑向閑雲似我閑。"]', '["爲愛松声听不足，每逢松樹遂忘還。","翛然此外更何事，笑向闲云似我闲。"]', '诗', 'shi', '', NULL, '戲題松樹 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99f504d7-10b6-413d-ae97-7a1661073a0b', '戲題二首 一', '戲題二首 一', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["看飲逢歌日屢曛，我身何似繫浮雲。","時人不解野僧意，歸去溪頭作鳥羣。"]', '["看饮逢歌日屢曛，我身何似繫浮云。","时人不解野僧意，归去溪头作鸟羣。"]', '诗', 'shi', '', NULL, '戲題二首 一 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6043558f-9f5b-4088-8b8c-745cc729a923', '戲題二首 二', '戲題二首 二', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["喧喧共在是非間，終日誰知我自閑。","偶客狂歌何所爲，欲於人事強相關。"]', '["喧喧共在是非间，終日誰知我自闲。","偶客狂歌何所爲，欲於人事強相关。"]', '诗', 'shi', '', NULL, '戲題二首 二 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d517da-12c9-4384-a682-2036be0a8f55', '雜寓興', '杂寓兴', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["嗟嗟號呶子，世稱謫僊儔。","媚俗被鮫綃，欺天薦昫脩。","奔景謂可致，馳齡言易流。","燕昭昧往事，嬴政亡前籌。","三山果不見，九僊忽悠悠。","君看牛山樂，君見麋浦遊。","昨日千金子，聯綿成古丘。","吾將攬明月，照爾生死流。","至樂享爰居，慙貽達者尤。","冥冥光塵內，機喪成海漚。"]', '["嗟嗟號呶子，世稱謫僊儔。","媚俗被鮫綃，欺天薦昫脩。","奔景謂可致，驰齡言易流。","燕昭昧往事，嬴政亡前籌。","三山果不见，九僊忽悠悠。","君看牛山乐，君见麋浦游。","昨日千金子，聯綿成古丘。","吾將攬明月，照爾生死流。","至乐享爰居，慙貽達者尤。","冥冥光塵內，機喪成海漚。"]', '诗', 'shi', '', NULL, '雜寓興 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7afccab-7a02-4075-813c-d8dce3eb01e2', '雜興六首 一', '杂兴六首 一', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["吾觀談天客，工言喪其精。","萬物資廣庇，此中何有情。","若爲昧顏跖，修短怨太清。","高論讓鄒子，放詞徵屈生。","請從象外推，至論尤明明。"]', '["吾观談天客，工言喪其精。","万物資廣庇，此中何有情。","若爲昧顏跖，修短怨太清。","高論讓鄒子，放词徵屈生。","請從象外推，至論尤明明。"]', '诗', 'shi', '', NULL, '雜興六首 一 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9471382-2f72-4409-b7b5-7e10909b5019', '雜興六首 二', '杂兴六首 二', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["短齡役長世，擾擾悟不早。","嬪女身後空，歡娛夢中好。","從教西陵樹，千載傷懷抱。","鶴駕何冥冥，鼇洲去浩浩。","柔顏感三花，凋發悲蔓草。","月中伐桂人是誰，翻使年年不衰老。"]', '["短齡役长世，擾擾悟不早。","嬪女身後空，歡娛梦中好。","從教西陵樹，千載傷懷抱。","鹤駕何冥冥，鼇洲去浩浩。","柔顏感三花，凋發悲蔓草。","月中伐桂人是誰，翻使年年不衰老。"]', '诗', 'shi', '', NULL, '雜興六首 二 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c320b71e-2a0e-4b3b-bd6b-c9843bc7ee05', '雜興六首 三', '杂兴六首 三', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["誰高齊公子，泣聽雍門琴。","死且何足傷，殊非達人心。"]', '["誰高齊公子，泣听雍门琴。","死且何足傷，殊非達人心。"]', '诗', 'shi', '', NULL, '雜興六首 三 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee47c307-2b14-4a7f-b10b-3ec948ad6c32', '雜興六首 四', '杂兴六首 四', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["獨高庭中鶴，意遠貴氛埃。","有時青冥遊，顧我還下來。"]', '["独高庭中鹤，意远貴氛埃。","有时青冥游，顧我還下来。"]', '诗', 'shi', '', NULL, '雜興六首 四 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('782de211-6463-4a98-81cb-0736555c285b', '雜興六首 五', '杂兴六首 五', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["白雲琅玕色，一片生虛無。","此物若無心，若何卷還舒。"]', '["白云琅玕色，一片生虛無。","此物若無心，若何卷還舒。"]', '诗', 'shi', '', NULL, '雜興六首 五 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47edc7e9-a2c5-4de2-aaaf-d21d57740345', '雜興六首 六', '杂兴六首 六', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["疎散遂吾性，栖山更無機。","寥寥高松下，獨有閑雲歸。","精意不可道，冥然還掩扉。"]', '["疎散遂吾性，栖山更無機。","寥寥高松下，独有闲云归。","精意不可道，冥然還掩扉。"]', '诗', 'shi', '', NULL, '雜興六首 六 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a1757d3-f95c-47b3-9951-523538ecd61e', '偶然五首 一', '偶然五首 一', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["樂禪心似蕩，吾道不相妨。","獨悟歌還笑，誰言老更狂。"]', '["乐禪心似蕩，吾道不相妨。","独悟歌還笑，誰言老更狂。"]', '诗', 'shi', '', NULL, '偶然五首 一 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3879732f-c0c2-47a0-9fa3-b0a206bdbc89', '偶然五首 二', '偶然五首 二', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["偶然寂無喧，吾了心性源。","可嫌蟲食木，不笑鳥能言。"]', '["偶然寂無喧，吾了心性源。","可嫌蟲食木，不笑鸟能言。"]', '诗', 'shi', '', NULL, '偶然五首 二 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02acfec5-03e9-49af-b5e4-c152825dd52f', '偶然五首 三', '偶然五首 三', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["隱心不隱跡，却欲住人寰。","欠樹移春樹，無山看畫山。","居喧我未錯，真意在其間。"]', '["隐心不隐跡，却欲住人寰。","欠樹移春樹，無山看畫山。","居喧我未錯，真意在其间。"]', '诗', 'shi', '', NULL, '偶然五首 三 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f29f9b32-c701-48c3-8e06-9407d2cc25f5', '偶然五首 四', '偶然五首 四', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["虜語嫌不學，胡音從不翻。","說禪顛倒是，樂殺金王孫。"]', '["虜語嫌不学，胡音從不翻。","说禪顛倒是，乐殺金王孫。"]', '诗', 'shi', '', NULL, '偶然五首 四 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7dd7349-0416-4fc8-b53d-0852f0203054', '偶然五首 五', '偶然五首 五', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["真隱須無矯，忘名要似愚。","只將兩條事，空却漢潛夫。"]', '["真隐須無矯，忘名要似愚。","只將兩條事，空却漢潛夫。"]', '诗', 'shi', '', NULL, '偶然五首 五 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bcd1f4a-bc89-4a92-8d79-ef19bd749b88', '問天', '问天', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["天公何時有，談者皆不經。","誰道賢人死，今爲傅說星。"]', '["天公何时有，談者皆不經。","誰道賢人死，今爲傅说星。"]', '诗', 'shi', '', NULL, '問天 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16981157-528b-44dd-99cc-19ce8bcd0aea', '寓言', '寓言', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["吾道本無我，未曾嫌世人。","如今到城市，彌覺此心真。"]', '["吾道本無我，未曾嫌世人。","如今到城市，彌覺此心真。"]', '诗', 'shi', '', NULL, '寓言 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b8187d-90ba-42e9-8dfc-ad713c764a6c', '前溪作', '前溪作', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春歌已寂寂，古水自涓涓。","徒誤時人輩，傷心作逝川。"]', '["春歌已寂寂，古水自涓涓。","徒誤时人輩，傷心作逝川。"]', '诗', 'shi', '', NULL, '前溪作 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d995d252-549e-40f9-9c51-2bb792ed9354', '戲作', '戲作', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["乞我百萬金，封我異姓王。","不如獨悟時，大笑放清狂。"]', '["乞我百万金，封我異姓王。","不如独悟时，大笑放清狂。"]', '诗', 'shi', '', NULL, '戲作 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6513f4d-5abd-4043-80cb-7b9567995dab', '浮雲三章 一', '浮云三章 一', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["浮雲浮雲，集於扶桑。","扶桑茫茫，日暮之光。","匪日之暮，浮雲之汙。","嗟我懷人，憂心如蠹。"]', '["浮云浮云，集於扶桑。","扶桑茫茫，日暮之光。","匪日之暮，浮云之汙。","嗟我懷人，憂心如蠹。"]', '诗', 'shi', '', NULL, '浮雲三章 一 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c988c1d2-dc41-441e-ac83-39bf1441b663', '浮雲三章 二', '浮云三章 二', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["浮雲浮雲，集於咸池。","咸池微微，日昃之時。","匪日之昃，浮雲之惑。","嗟我懷人，憂心如織。"]', '["浮云浮云，集於咸池。","咸池微微，日昃之时。","匪日之昃，浮云之惑。","嗟我懷人，憂心如织。"]', '诗', 'shi', '', NULL, '浮雲三章 二 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71677a05-d3f4-4e2c-82a1-6d2212d84729', '浮雲三章 三', '浮云三章 三', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["浮雲浮雲，集於高舂。","高舂濛濛，日夕之容。","匪日之夕，浮雲之積。","嗟我懷人，憂心如[惄]。"]', '["浮云浮云，集於高舂。","高舂濛濛，日夕之容。","匪日之夕，浮云之積。","嗟我懷人，憂心如[惄]。"]', '诗', 'shi', '', NULL, '浮雲三章 三 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ff78979-1ada-457d-906b-d0aa39930a5d', '寓言', '寓言', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["人生百年我過半，天生才定不可換。","東海釣鼇鼇不食，南山坐石石欲爛。"]', '["人生百年我過半，天生才定不可換。","东海釣鼇鼇不食，南山坐石石欲爛。"]', '诗', 'shi', '', NULL, '寓言 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fb18e55-2551-4e0c-a120-3b2f469fd78b', '若邪春興', '若邪春兴', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春生若邪水，雨後漫流通。","芳草行無盡，清源去不窮。","野煙迷極浦，斜日起微風。","數處乘流望，依稀似剡中。"]', '["春生若邪水，雨後漫流通。","芳草行無尽，清源去不窮。","野煙迷極浦，斜日起微风。","數处乘流望，依稀似剡中。"]', '诗', 'shi', '', NULL, '若邪春興 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ccb3c7e-54b1-4d83-aae8-cc761e4354c7', '晨登樂遊原望終南積雪', '晨登乐游原望終南積雪', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["凌晨擁弊裘，徑上古原頭。","雪霽山疑近，天高思若浮。","瓊峰埋積翠，玉嶂掩飛流。","曜彩含朝日，搖光奪寸眸。","寒空標瑞色，爽氣襲皇州。","清眺何人得，終當獨再遊。"]', '["凌晨擁弊裘，徑上古原头。","雪霽山疑近，天高思若浮。","瓊峰埋積翠，玉嶂掩飞流。","曜彩含朝日，搖光奪寸眸。","寒空標瑞色，爽氣襲皇州。","清眺何人得，終當独再游。"]', '诗', 'shi', '', NULL, '晨登樂遊原望終南積雪 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95317f6-6e5d-4942-b589-01c5468f332f', '送商季臯', '送商季臯', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["比來知爾有詩名，莫恨東歸學未成。","新豐有酒爲我飲，消取故園傷別情。"]', '["比来知爾有诗名，莫恨东归学未成。","新豐有酒爲我饮，消取故园傷別情。"]', '诗', 'shi', '', NULL, '送商季臯 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91e038db-986c-4ca4-93bb-f9455fa6250b', '弔靈均詞', '弔靈均词', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["昧天道兮有無，聽汨渚兮躊躇。","期靈均兮若存，問神理兮何如。","願君精兮爲月，出孤影兮示予。","天獨何兮有君，君在萬兮不羣。","既冰心兮皎潔，上問天兮胡不聞。","天不聞，神莫覩。","若雲冥冥兮雷霆怒，蕭條杳眇兮餘草莽。","古山春兮爲誰，今猨哀兮何思。","風激烈兮楚竹死，國殤人悲兮雨颸颸，雨颸颸兮望君时。","光芒蕩漾兮化爲水，萬古忠貞兮徒爾爲。"]', '["昧天道兮有無，听汨渚兮躊躇。","期靈均兮若存，问神理兮何如。","願君精兮爲月，出孤影兮示予。","天独何兮有君，君在万兮不羣。","既冰心兮皎潔，上问天兮胡不闻。","天不闻，神莫覩。","若云冥冥兮雷霆怒，蕭條杳眇兮餘草莽。","古山春兮爲誰，今猨哀兮何思。","风激烈兮楚竹死，国殤人悲兮雨颸颸，雨颸颸兮望君时。","光芒蕩漾兮化爲水，万古忠貞兮徒爾爲。"]', '诗', 'shi', '', NULL, '弔靈均詞 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc4419e-d44c-457c-93bc-4f5850e012ed', '步虛詞', '步虛词', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["予因覽真訣，遂感西城君。","玉笙下青冥，人間未曾聞。","日華鍊精魄，皎皎無垢氛。","謂我有僊骨，且令餌氤氳。","俯仰媿靈顏，願隨鸞鵠羣。","俄然動風馭，縹渺歸青雲。"]', '["予因覽真訣，遂感西城君。","玉笙下青冥，人间未曾闻。","日华鍊精魄，皎皎無垢氛。","謂我有僊骨，且令餌氤氳。","俯仰媿靈顏，願隨鸾鵠羣。","俄然动风馭，縹渺归青云。"]', '诗', 'shi', '', NULL, '步虛詞 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61be085b-5ba1-4a7c-bfe8-9a37c6d608b5', '奉應顏尚書真卿觀玄真子置酒張樂舞破陣畫洞庭三山歌', '奉應顏尚书真卿观玄真子置酒張乐舞破陣畫洞庭三山歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["道流迹異人共驚，寄向畫中觀道情。","如何萬象自心出，而心澹然無所營。","手援毫，足蹈節，披縑灑墨稱麗絕。","石文亂點急管催，雲態徐揮慢歌發。","樂縱酒酣狂更好，攢峰若雨縱橫埽。","尺波澶漫意無涯，片嶺崚嶒勢將倒。","盻睞方知造境難，象忘神遇非筆端。","昨日幽奇湖上見，今朝舒卷手中看。","興餘輕拂遠天色，曾向峰東海邊識。","秋空暮景颯颯容，翻疑是真畫不得。","顏公素高山水意，常恨三山不可至。","賞君狂畫忘遠遊，不出軒墀坐蒼翠。"]', '["道流迹異人共驚，寄向畫中观道情。","如何万象自心出，而心澹然無所營。","手援毫，足蹈節，披縑灑墨稱丽絕。","石文亂点急管催，云態徐揮慢歌發。","乐縱酒酣狂更好，攢峰若雨縱橫埽。","尺波澶漫意無涯，片嶺崚嶒勢將倒。","盻睞方知造境难，象忘神遇非笔端。","昨日幽奇湖上见，今朝舒卷手中看。","兴餘轻拂远天色，曾向峰东海邊識。","秋空暮景颯颯容，翻疑是真畫不得。","顏公素高山水意，常恨三山不可至。","賞君狂畫忘远游，不出軒墀坐蒼翠。"]', '诗', 'shi', '', NULL, '奉應顏尚書真卿觀玄真子置酒張樂舞破陣畫洞庭三山歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15f50b8f-3352-47f1-9cb8-265edb790477', '荅韋山人隱起龍文藥瓢歌', '荅韋山人隐起龙文藥瓢歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["野人藥瓢天下絕，全如渾金割如月。","彪炳文章智使然，生成在我不在天。","若言有物不繇物，何意中虛道性全。","韋生能詩兼好異，獲此靈瓢遠相遺。","仙侯玉帖人漫傳，若士青囊世何秘。","一捧一開如見君，藥盛五色香氛氳。","背上驪龍蟠不睡，張鱗擺頷生風雲。","世人強知金丹道，默僊不成穢僊老。","年少紛如陌上塵，不見吾瓢盡枯槁。","聊將繫肘步何輕，便有三山孤鶴情。","東方小兒乏此物，遂令僊籍獨無名。"]', '["野人藥瓢天下絕，全如渾金割如月。","彪炳文章智使然，生成在我不在天。","若言有物不繇物，何意中虛道性全。","韋生能诗兼好異，獲此靈瓢远相遺。","仙侯玉帖人漫傳，若士青囊世何秘。","一捧一开如见君，藥盛五色香氛氳。","背上驪龙蟠不睡，張鱗擺頷生风云。","世人強知金丹道，默僊不成穢僊老。","年少紛如陌上塵，不见吾瓢尽枯槁。","聊將繫肘步何轻，便有三山孤鹤情。","东方小兒乏此物，遂令僊籍独無名。"]', '诗', 'shi', '', NULL, '荅韋山人隱起龍文藥瓢歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50704141-b942-45c4-9e93-45716a788740', '桃花石枕歌贈康從事', '桃花石枕歌贈康從事', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["卞山幽石產奇璞，荆人至死採不著。","何人琢枕持贈君，片片桃花開未落。","劒工見兮可爲劒，玉工辨兮知非石。","至寶繇來覽者稀，今君獨鑒應欲惜。","何辭售與章天真，幸得提攜近玉人。","可中棄置君不顧，天生秀色徒璘玢。","四座喧喧爭目悅，巧過造化稱一絕。","莫言昨日因錯磨，看取從來無點缺。","六月江南暑未闌，一尺花冰試枕看。","高窗正午風颯變，室中不減春天寒。","主人所重重枕德，文章外飾徒相惑。","更有堅貞不易心，與君天下爲士則。"]', '["卞山幽石產奇璞，荆人至死採不著。","何人琢枕持贈君，片片桃花开未落。","劒工见兮可爲劒，玉工辨兮知非石。","至寶繇来覽者稀，今君独鑒應欲惜。","何辞售與章天真，幸得提携近玉人。","可中棄置君不顧，天生秀色徒璘玢。","四座喧喧爭目悅，巧過造化稱一絕。","莫言昨日因錯磨，看取從来無点缺。","六月江南暑未闌，一尺花冰試枕看。","高窗正午风颯变，室中不減春天寒。","主人所重重枕德，文章外飾徒相惑。","更有堅貞不易心，與君天下爲士則。"]', '诗', 'shi', '', NULL, '桃花石枕歌贈康從事 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e93144a-6b85-4f1e-b619-9b6776d1a2ff', '張伯英草書歌', '張伯英草书歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["伯英死後生怕高，朝看手把山中毫。","先賢草律我草狂，風雲陣發愁鍾王。","須臾變態皆自我，象形類物無不可。","閬風遊雲千萬朵，驚龍蹴踏飛欲墮。","更覩鄧林花落朝，狂風亂攪何飄飄。","有時凝然筆空握，情在寥天獨飛鶴。","有時取勢氣更高，憶得春江千里濤。","張生奇絕難再遇，草罷臨風展輕素。","陰慘陽舒如有道，鬼狀魑容若可懼。","黃公酒壚興偏入，阮籍不嗔嵇亦顧。","長安酒牓醉後書，此日騁君千里步。"]', '["伯英死後生怕高，朝看手把山中毫。","先賢草律我草狂，风云陣發愁鍾王。","須臾变態皆自我，象形類物無不可。","閬风游云千万朵，驚龙蹴踏飞欲墮。","更覩鄧林花落朝，狂风亂攪何飄飄。","有时凝然笔空握，情在寥天独飞鹤。","有时取勢氣更高，憶得春江千里濤。","張生奇絕难再遇，草罷臨风展轻素。","陰慘陽舒如有道，鬼狀魑容若可懼。","黄公酒壚兴偏入，阮籍不嗔嵇亦顧。","长安酒牓醉後书，此日騁君千里步。"]', '诗', 'shi', '', NULL, '張伯英草書歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('853e4d9d-d1e5-4a68-8432-33048877cc31', '寒栖子歌', '寒栖子歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["君在廬山不知羣，有疑是鶴又是雲。","生死塵埃汙不得，眼前榮利徒紛紛。","今日惠然來訪我，酒榼書囊肩背荷。","拂除衣上餌煙霞，昨夜胥門宿蔡家。","天然不飲亦不食，拋名換姓覓不得。","且向人間作酒僊，不肯將身生羽翼。","停形爲餌天地根，世人皆死我獨存。","洗慮因吞清明籙，世人皆貪我常足。","栖子妙今道已成，手把玄樞心運冥。","能令鬼哭神效靈，身如飄風不可絆。","朝遊崆峒夕汗漫，向來坐客猶未散。","忽憶羅浮欲去時，遙指孤雲作路岐。","海上仙遊不可見，人間日落空桑枝。"]', '["君在廬山不知羣，有疑是鹤又是云。","生死塵埃汙不得，眼前榮利徒紛紛。","今日惠然来訪我，酒榼书囊肩背荷。","拂除衣上餌煙霞，昨夜胥门宿蔡家。","天然不饮亦不食，拋名換姓覓不得。","且向人间作酒僊，不肯將身生羽翼。","停形爲餌天地根，世人皆死我独存。","洗慮因吞清明籙，世人皆貪我常足。","栖子妙今道已成，手把玄樞心運冥。","能令鬼哭神效靈，身如飄风不可絆。","朝游崆峒夕汗漫，向来坐客猶未散。","忽憶羅浮欲去时，遙指孤云作路岐。","海上仙游不可见，人间日落空桑枝。"]', '诗', 'shi', '', NULL, '寒栖子歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8151068a-111c-4566-8baf-ec3d41d23356', '翔隼歌送王端公', '翔隼歌送王端公', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["古人賞神駿，如何秋隼擊。","獨立高標望霜翮，應看天宇如咫尺。","低迴拂地凌風翔，鵬雛敢下鴈斷行。","晴空四顧忽不見，有時獨出青霞傍。","窮陰萬里落寒日，氣殺草枯增奮逸。","雲塞斜飛攪葉迷，雪天直上穿花疾。","見君高情有所屬，贈別因歌翔隼曲。","離亭慘慘客散時，歌盡路長意不足。"]', '["古人賞神駿，如何秋隼擊。","独立高標望霜翮，應看天宇如咫尺。","低迴拂地凌风翔，鵬雛敢下鴈斷行。","晴空四顧忽不见，有时独出青霞傍。","窮陰万里落寒日，氣殺草枯增奮逸。","云塞斜飞攪葉迷，雪天直上穿花疾。","见君高情有所屬，贈別因歌翔隼曲。","離亭慘慘客散时，歌尽路长意不足。"]', '诗', 'shi', '', NULL, '翔隼歌送王端公 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42ee203b-9152-4f47-8101-51104acab4d5', '白雲歌寄陸中丞使君長源', '白云歌寄陸中丞使君长源', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一見西山雲，使人情意遠。","憑高發詠何超遙，道妙如君有舒卷。","縈空疊景多麗容，衆峰峰上自爲峰。","潔白不繇陰雨積，高明肯共雜煙重。","萬物有形皆有著，白雲有形無繫縛。","黃金被爍玉亦瑕，一片飄然汙不著。","或逢天上或人間，人自營營雲自閑。","忽爾飛來暫爲侶，忽然飛去莫能攀。","逸民對雲效高致，禪子逢雲增道意。","白雲遇物無偏頗，自是人心見同異。","閶闔天門宜曙看，爲纓作蓋擁千官。","從龍合沓臨清暑，就日逶迤繞露寒。","誰憐西山雲，亭亭處幽絕。","坐石長看非我羈，手中欲攬待君說。","貞白先生那得知，只向空山自怡悅。"]', '["一见西山云，使人情意远。","憑高發詠何超遙，道妙如君有舒卷。","縈空叠景多丽容，衆峰峰上自爲峰。","潔白不繇陰雨積，高明肯共杂煙重。","万物有形皆有著，白云有形無繫縛。","黄金被爍玉亦瑕，一片飄然汙不著。","或逢天上或人间，人自營營云自闲。","忽爾飞来暫爲侶，忽然飞去莫能攀。","逸民对云效高致，禪子逢云增道意。","白云遇物無偏頗，自是人心见同異。","閶闔天门宜曙看，爲纓作蓋擁千官。","從龙合沓臨清暑，就日逶迤繞露寒。","誰怜西山云，亭亭处幽絕。","坐石长看非我羈，手中欲攬待君说。","貞白先生那得知，只向空山自怡悅。"]', '诗', 'shi', '', NULL, '白雲歌寄陸中丞使君長源 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e53dd574-3be2-45ff-b260-c379d2defc6a', '裴端公使君清席賦得青桂歌送徐長史', '裴端公使君清席賦得青桂歌送徐长史', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["昔年攀桂爲留人，今朝攀桂送歸客。","秋風桃李搖落盡，爲君青青伴松柏。","謝公南樓送客還，高歌桂樹凌寒山。","應憐獨秀空林上，空賞敷華積雪間。","昨夜一枝生在月，嬋娟可望不可折。","若爲天上堪贈行，徒使亭亭照離別。"]', '["昔年攀桂爲留人，今朝攀桂送归客。","秋风桃李搖落尽，爲君青青伴松柏。","謝公南楼送客還，高歌桂樹凌寒山。","應怜独秀空林上，空賞敷华積雪间。","昨夜一枝生在月，嬋娟可望不可折。","若爲天上堪贈行，徒使亭亭照離別。"]', '诗', 'shi', '', NULL, '裴端公使君清席賦得青桂歌送徐長史 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ca0bb55-8e8a-4a81-ba9c-f678c7f51760', '周長史昉畫毗沙門天王歌', '周长史昉畫毗沙门天王歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["長史畫神獨感神，高步區中無兩人。","雅而逸，高且真，形生虛無忽可親。","降魔大戟縮在手，倚天長劒橫諸紳。","慈威示物雖凜凜，在德無秋唯有春。","吾知真象本非色，此中妙用君心得。","苟能下筆合神造，誤點一點亦爲道。","寫出霜縑可舒卷，何人應識此情遠。","秋齋清寂無外物，盥手焚香聊自展。","憶昔胡兵圍未解，感得此神天上下。","至今雲旗圖我形，爲君一顧煙塵清。"]', '["长史畫神独感神，高步區中無兩人。","雅而逸，高且真，形生虛無忽可親。","降魔大戟縮在手，倚天长劒橫諸紳。","慈威示物雖凜凜，在德無秋唯有春。","吾知真象本非色，此中妙用君心得。","苟能下笔合神造，誤点一点亦爲道。","寫出霜縑可舒卷，何人應識此情远。","秋斋清寂無外物，盥手焚香聊自展。","憶昔胡兵圍未解，感得此神天上下。","至今云旗圖我形，爲君一顧煙塵清。"]', '诗', 'shi', '', NULL, '周長史昉畫毗沙門天王歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1631d0a-1ab3-49e4-9b18-b77d538961a5', '奉和顏魯公真卿落玄真子舴艋舟歌', '奉和顏魯公真卿落玄真子舴艋舟歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["滄浪子後玄真子，冥冥釣隱江之汜。","刳木新成舴艋舟，諸侯落舟自茲始。","得道身不繫，無機舟亦閑。","從水遠逝兮任風還，朝五湖兮夕三山。","停綸乍入芙蓉浦，擊汰時過明月灣。","太公取璜我不取，龍伯釣鼇我不釣。","竹竿嫋嫋魚簁簁，此中自得還自笑。","汗漫一遊何可期，後來誰遇冰雪姿。","上古初聞出堯世，今朝還見在堯時。"]', '["滄浪子後玄真子，冥冥釣隐江之汜。","刳木新成舴艋舟，諸侯落舟自茲始。","得道身不繫，無機舟亦闲。","從水远逝兮任风還，朝五湖兮夕三山。","停綸乍入芙蓉浦，擊汰时過明月灣。","太公取璜我不取，龙伯釣鼇我不釣。","竹竿嫋嫋鱼簁簁，此中自得還自笑。","汗漫一游何可期，後来誰遇冰雪姿。","上古初闻出堯世，今朝還见在堯时。"]', '诗', 'shi', '', NULL, '奉和顏魯公真卿落玄真子舴艋舟歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e20fd2-4917-4eeb-9bb1-27f12313ea48', '鄭容全成蛟形木机歌', '鄭容全成蛟形木机歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["萬物貴天然，天然不可得。","渾樸無勞剞劂工，幽姿自可蛟龍質。","欲騰未去何翩翩，揚袂爭前誰敢拂。","可中風雨一朝至，還應不是池中物。","蒼山萬重採一枝，形如器車生意奇。","風號雨噴心不折，衆木千叢君獨知。","高人心，多越格。","有時就月吟春風，持來座右驚神客。","愛君開閤江之濱，白雲黃鶴長相親。","南郭子綦我不識，非君獨是是何人。"]', '["万物貴天然，天然不可得。","渾樸無勞剞劂工，幽姿自可蛟龙質。","欲腾未去何翩翩，揚袂爭前誰敢拂。","可中风雨一朝至，還應不是池中物。","蒼山万重採一枝，形如器车生意奇。","风號雨噴心不折，衆木千叢君独知。","高人心，多越格。","有时就月吟春风，持来座右驚神客。","愛君开閤江之濱，白云黄鹤长相親。","南郭子綦我不識，非君独是是何人。"]', '诗', 'shi', '', NULL, '鄭容全成蛟形木机歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f9eba2b-be41-4cb3-ad59-c90b2cdba294', '奉同顏使君真卿清風樓賦得洞庭歌送吳鍊師歸林屋洞', '奉同顏使君真卿清风楼賦得洞庭歌送吳鍊師归林屋洞', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["名山洞府到金庭，三十六洞稱最靈。","不有古仙啓其秘，今日安知靈寶經。","中山鍊師栖白雲，道成仙秩號元君。","三千甲子朝玉帝，世上如今名始聞。","吐納青牙養肌髮，花冠玉舃何高潔。","不聞天上來謫仙，自是人間授真訣。","吳興太守道家流，仙師遠放清風樓。","應將內景還飛去，且從分風當此留。","湖之山兮樓上見，山冥冥兮水悠悠。","世人不到君自到，縹緲仙都誰與儔。","黃鶴孤雲天上物，物外飄然自天匹。","一別千年未可期，仙家不數人間日。"]', '["名山洞府到金庭，三十六洞稱最靈。","不有古仙啓其秘，今日安知靈寶經。","中山鍊師栖白云，道成仙秩號元君。","三千甲子朝玉帝，世上如今名始闻。","吐納青牙養肌髮，花冠玉舃何高潔。","不闻天上来謫仙，自是人间授真訣。","吳兴太守道家流，仙師远放清风楼。","應將內景還飞去，且從分风當此留。","湖之山兮楼上见，山冥冥兮水悠悠。","世人不到君自到，縹緲仙都誰與儔。","黄鹤孤云天上物，物外飄然自天匹。","一別千年未可期，仙家不數人间日。"]', '诗', 'shi', '', NULL, '奉同顏使君真卿清風樓賦得洞庭歌送吳鍊師歸林屋洞 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0830d6a3-d41e-4e82-9dee-73d31e69b61f', '戛銅椀爲龍吟歌', '戛銅椀爲龙吟歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["逸僧戛椀爲龍吟，世上未曾聞此音。","一從太尉房公賞，遂使秦人傳至今。","初戛徐徐聲漸顯，樂音不管何人[辨]。","似出龍泉萬丈底，乍怪聲來近而遠。","未必全繇戛者功，真生虛無非椀中。","寥亮掩清笛，縈迴凌細風。","遙聞不斷在煙杪，萬籟無聲天境空。","乍向天台宿華頂，秋宵一吟更清迥。","能令聽者易常性，憂人忘憂躁人靜。","今日鏗鍠江上聞，蛟螭奔飛如得羣。","聲過陰嶺恐成雨，響駐晴天將起雲。","坐來吟盡空江碧，却尋向者聽無迹。","人生萬事將此同，暮賤朝榮動還寂。"]', '["逸僧戛椀爲龙吟，世上未曾闻此音。","一從太尉房公賞，遂使秦人傳至今。","初戛徐徐声漸显，乐音不管何人[辨]。","似出龙泉万丈底，乍怪声来近而远。","未必全繇戛者功，真生虛無非椀中。","寥亮掩清笛，縈迴凌細风。","遙闻不斷在煙杪，万籟無声天境空。","乍向天台宿华頂，秋宵一吟更清迥。","能令听者易常性，憂人忘憂躁人静。","今日鏗鍠江上闻，蛟螭奔飞如得羣。","声過陰嶺恐成雨，响駐晴天將起云。","坐来吟尽空江碧，却尋向者听無迹。","人生万事將此同，暮賤朝榮动還寂。"]', '诗', 'shi', '', NULL, '戛銅椀爲龍吟歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41fca742-a88c-4a20-8dfe-a48d2d6f7d43', '飲茶歌誚崔石使君', '饮茶歌誚崔石使君', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["越人遺我剡溪茗，採得金牙爨金鼎。","素瓷雪色縹沫香，何似諸仙瓊蘂漿。","一飲滌昏寐，情來朗爽滿天地。","再飲清我神，忽如飛雨灑輕塵。","三飲便得道，何須苦心破煩惱。","此物清高世莫知，世人飲酒多自欺。","愁看畢卓甕間夜，笑向陶潛籬下時。","崔侯啜之意不已，狂歌一曲驚人耳。","孰知茶道全爾真，唯有丹丘得如此。"]', '["越人遺我剡溪茗，採得金牙爨金鼎。","素瓷雪色縹沫香，何似諸仙瓊蘂漿。","一饮滌昏寐，情来朗爽满天地。","再饮清我神，忽如飞雨灑轻塵。","三饮便得道，何須苦心破煩惱。","此物清高世莫知，世人饮酒多自欺。","愁看畢卓甕间夜，笑向陶潛籬下时。","崔侯啜之意不已，狂歌一曲驚人耳。","孰知茶道全爾真，唯有丹丘得如此。"]', '诗', 'shi', '', NULL, '飲茶歌誚崔石使君 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43cac04d-45ad-4a67-a715-f2d310cd6faa', '買藥歌送楊山人', '買藥歌送楊山人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["華陰少年何所希，欲餌丹砂化骨飛。","江南藥少淮南有，暫別胥門上京口。","京口斜通江水流，斐回應上青山頭。","夜驚潮沒鸕鶿堰，朝看日出芙蓉樓。","搖蕩春風亂帆影，片雲無數是揚州。","揚州喧喧賣藥市，浮俗無由識仙子。","河間姹女直千金，紫陽夫人服不死。","吾於此道復何如，昨朝新得蓬萊書。"]', '["华陰少年何所希，欲餌丹砂化骨飞。","江南藥少淮南有，暫別胥门上京口。","京口斜通江水流，斐回應上青山头。","夜驚潮沒鸕鶿堰，朝看日出芙蓉楼。","搖蕩春风亂帆影，片云無數是揚州。","揚州喧喧賣藥市，浮俗無由識仙子。","河间姹女直千金，紫陽夫人服不死。","吾於此道复何如，昨朝新得蓬萊书。"]', '诗', 'shi', '', NULL, '買藥歌送楊山人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a43169e8-7e6e-4b18-850d-09f64232409a', '薛卿教長行歌', '薛卿教长行歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["桂陽仙柳道家說，昔傳蘇君今是薛。","聊將握槊偶時人，便被人間稱冠絕。","黃楊文局龜螭蟠，琢成骰子雙琅玕。","初疑月破雲中墮，復怪星移指下攢。","誰識兵奇勢可保，坐看將軍上一道。","有時彩王非所希，笑擊單于出重圍。","鳧驚隼擊疾若飛，左顧右盻生光輝。","家本聯姻漢戚里，身是長安貴公子。","名高藝絕何翩翩，幾迴決勝君王前。","扈遊長樂與祈年，人望青雲白日邊。","謫宦江南歲陰晚，還將此道聊自遣。","繇來君子行最長，予亦知君寄心遠。"]', '["桂陽仙柳道家说，昔傳蘇君今是薛。","聊將握槊偶时人，便被人间稱冠絕。","黄楊文局龟螭蟠，琢成骰子雙琅玕。","初疑月破云中墮，复怪星移指下攢。","誰識兵奇勢可保，坐看將軍上一道。","有时彩王非所希，笑擊單于出重圍。","鳧驚隼擊疾若飞，左顧右盻生光輝。","家本聯姻漢戚里，身是长安貴公子。","名高藝絕何翩翩，幾迴決勝君王前。","扈游长乐與祈年，人望青云白日邊。","謫宦江南歲陰晚，還將此道聊自遣。","繇来君子行最长，予亦知君寄心远。"]', '诗', 'shi', '', NULL, '薛卿教長行歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efea89d2-59ff-4599-af6d-a2801c8ff62e', '桃花石枕歌送安吉康丞', '桃花石枕歌送安吉康丞', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["君吏桃州尚奇跡，桃州採得桃花石。","爛疑朝日照已舒，含似春風吹未坼。","珪璋特達世所珍，吾知此物亦其倫。","應羨花開不凋悴，應嘉玉片無緇磷。","立性堅剛平若砥，君子偏將交道比。","何人亦秉堅剛姿，吾見君心得如此。","君心所好我獨知，別多見少長相思。","從來賞翫安左右，萬里提攜君莫辭。"]', '["君吏桃州尚奇跡，桃州採得桃花石。","爛疑朝日照已舒，含似春风吹未坼。","珪璋特達世所珍，吾知此物亦其倫。","應羨花开不凋悴，應嘉玉片無緇磷。","立性堅剛平若砥，君子偏將交道比。","何人亦秉堅剛姿，吾见君心得如此。","君心所好我独知，別多见少长相思。","從来賞翫安左右，万里提携君莫辞。"]', '诗', 'shi', '', NULL, '桃花石枕歌送安吉康丞 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21cd5872-8790-43cb-b694-390d4bee7f25', '賦得吳王送女潮歌送李判官之河中府', '賦得吳王送女潮歌送李判官之河中府', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["見說吳王送女時，行宮直到荆溪口。","溪上千年送女潮，爲感吳王至今有。","乃知昔人繇志誠，流水無情翻有情。","平波忽起二三尺，此上疑與神仙宅。","今人猶望荆之湄，長令望者增所思。","吳王已歿女不返，潮水無情那有期。","溪草何草號帝女，溪竹何竹號湘妃。","靈濤旦暮自堪傷，的爍嬋娟又爭發。","客歸千里自茲始，覽古高歌感行子。","不知別後相見期，君意何如此潮水。"]', '["见说吳王送女时，行宮直到荆溪口。","溪上千年送女潮，爲感吳王至今有。","乃知昔人繇志誠，流水無情翻有情。","平波忽起二三尺，此上疑與神仙宅。","今人猶望荆之湄，长令望者增所思。","吳王已歿女不返，潮水無情那有期。","溪草何草號帝女，溪竹何竹號湘妃。","靈濤旦暮自堪傷，的爍嬋娟又爭發。","客归千里自茲始，覽古高歌感行子。","不知別後相见期，君意何如此潮水。"]', '诗', 'shi', '', NULL, '賦得吳王送女潮歌送李判官之河中府 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1670ba6-08bd-4517-9ed4-8ae750204488', '觀李中丞洪二美人唱歌軋箏歌', '观李中丞洪二美人唱歌軋箏歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["君家雙美姬，善歌工箏人莫知。","軋用蜀竹弦楚絲，清哇宛轉聲相隨。","夜靜酒闌佳月前，高張水引何淵淵。","美人矜名曲不誤，蹙響時時如迸泉。","趙琴素所[嘉]，齊謳世稱絕。","箏歌一動凡音輟，凝弦且莫停金罍。","淫聲已闋雅聲來，遊魚噞喁鶴裴回，主人高情始爲開。","高情放浪出常格，偶世有名道無跡。","勳業先登上將科，文章已冠諸人籍。","每笑石崇無道情，輕身重色禍亦成。","君有佳人當禪伴，於中不廢學無生。","愛君天然性寡欲，家貧祿薄常知足。","謫官無慍如古人，交道忘言比前躅。","不意全家萬里來，湖中再見春山綠。","吳興公舍幽且閑，何妨寄隱在其間。","時議名齊謝太傅，更看攜妓似東山。"]', '["君家雙美姬，善歌工箏人莫知。","軋用蜀竹弦楚絲，清哇宛轉声相隨。","夜静酒闌佳月前，高張水引何淵淵。","美人矜名曲不誤，蹙响时时如迸泉。","趙琴素所[嘉]，齊謳世稱絕。","箏歌一动凡音輟，凝弦且莫停金罍。","淫声已闋雅声来，游鱼噞喁鹤裴回，主人高情始爲开。","高情放浪出常格，偶世有名道無跡。","勳業先登上將科，文章已冠諸人籍。","每笑石崇無道情，轻身重色禍亦成。","君有佳人當禪伴，於中不廢学無生。","愛君天然性寡欲，家貧祿薄常知足。","謫官無慍如古人，交道忘言比前躅。","不意全家万里来，湖中再见春山綠。","吳兴公舍幽且闲，何妨寄隐在其间。","时議名齊謝太傅，更看携妓似东山。"]', '诗', 'shi', '', NULL, '觀李中丞洪二美人唱歌軋箏歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d82ba80c-aea7-4745-8113-a3632baf5248', '陳氏童子草書歌', '陳氏童子草书歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["書家孺子有奇名，天然大草令人驚。","僧虔老時把筆法，孺子如今皆暗合。","飆揮電灑眼不及，但覺毫端鳴颯颯。","有時作點險且能，太行片石看欲崩。","偶然長掣濃入燥，少室枯松欹不倒。","夏室炎炎少人歡，山軒日色在闌干。","桐花飛盡子規思，主人高歌興不至。","濁醪不飲嫌昏沈，欲翫草書開我襟。","龍爪狀奇鼠鬚銳，水牋白皙越人惠。","王家小令草最狂，爲予灑出驚騰勢。"]', '["书家孺子有奇名，天然大草令人驚。","僧虔老时把笔法，孺子如今皆暗合。","飆揮電灑眼不及，但覺毫端鳴颯颯。","有时作点險且能，太行片石看欲崩。","偶然长掣濃入燥，少室枯松欹不倒。","夏室炎炎少人歡，山軒日色在闌干。","桐花飞尽子規思，主人高歌兴不至。","濁醪不饮嫌昏沈，欲翫草书开我襟。","龙爪狀奇鼠鬚銳，水牋白皙越人惠。","王家小令草最狂，爲予灑出驚腾勢。"]', '诗', 'shi', '', NULL, '陳氏童子草書歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c4471c4-9b26-4c3c-88c0-9c4bdfaab437', '飲茶歌送鄭容', '饮茶歌送鄭容', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["丹丘羽人輕玉食，採茶飲之生羽翼。","名藏仙府世空知，骨化雲宮人不識。","雲山童子調金鐺，楚人茶經虛得名。","霜天半夜芳草折，爛漫緗花啜又生。","賞君此茶祛我疾，使人胸中蕩憂慄。","日上香罏情未畢，醉踏虎溪雲，高歌送君出。"]', '["丹丘羽人轻玉食，採茶饮之生羽翼。","名藏仙府世空知，骨化云宮人不識。","云山童子調金鐺，楚人茶經虛得名。","霜天半夜芳草折，爛漫緗花啜又生。","賞君此茶祛我疾，使人胸中蕩憂慄。","日上香罏情未畢，醉踏虎溪云，高歌送君出。"]', '诗', 'shi', '', NULL, '飲茶歌送鄭容 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a209fb14-de5a-42d6-8555-33f71a0cab7f', '花石長枕歌荅章居士贈', '花石长枕歌荅章居士贈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["楚山有石郢人琢，琢成長枕知是玉。","全疑冰片坐恐銷，間發花藂驚不足。","贈予比之金琅玕，瓊花爛熳浮席端。","吾師道吾不執寶，今日感君因執看。","試叩鏗然應清律，纖塵不留蠅敢拂。","萬物皆因造化資，如何獨負清貞質。","南山有雲鵠在空，長松爲我生涼風。","高友朗詠樂其中，行住四儀皆道意。","不學小乘一曲士，唯將此物安座隅，取次閑眠有禪味。"]', '["楚山有石郢人琢，琢成长枕知是玉。","全疑冰片坐恐銷，间發花藂驚不足。","贈予比之金琅玕，瓊花爛熳浮席端。","吾師道吾不執寶，今日感君因執看。","試叩鏗然應清律，纖塵不留蠅敢拂。","万物皆因造化資，如何独負清貞質。","南山有云鵠在空，长松爲我生涼风。","高友朗詠乐其中，行住四儀皆道意。","不学小乘一曲士，唯將此物安座隅，取次闲眠有禪味。"]', '诗', 'shi', '', NULL, '花石長枕歌荅章居士贈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4517e291-ba61-49b1-b490-1753020ca5c3', '觀王右丞維滄洲圖歌', '观王右丞維滄洲圖歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["滄洲誤是真，萋萋忽盈視。","便有春渚情，褰裳掇芳芷。","颯然風至草不動，始悟丹青得如此。","丹青變化不可尋，翻空作有移人心。","猶言雨色斜拂座，乍似水涼來入襟。","滄洲說近三湘口，誰知卷得在君手。","披圖擁褐臨水時，翛然不異滄洲臾。"]', '["滄洲誤是真，萋萋忽盈視。","便有春渚情，褰裳掇芳芷。","颯然风至草不动，始悟丹青得如此。","丹青变化不可尋，翻空作有移人心。","猶言雨色斜拂座，乍似水涼来入襟。","滄洲说近三湘口，誰知卷得在君手。","披圖擁褐臨水时，翛然不異滄洲臾。"]', '诗', 'shi', '', NULL, '觀王右丞維滄洲圖歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7cb0165-deb9-45a5-b298-988984481f33', '洞庭山維諒上人院階前孤生橘樹歌', '洞庭山維諒上人院階前孤生橘樹歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["洞庭仙山但生橘，不生凡木與梨栗。","真子無私自不栽，感得一株階下出。","細葉繁枝委露新，四時常綠不關春。","若言此物無道性，何意孤生來就人。","二月三月山初暖，最愛低簷數枝短。","白花不用烏銜來，自有風吹手中滿，九月十月爭破顏。","金實離離色殷殷，一夜天晴香滿山。","天生珍木異於俗，俗士來逢不敢觸。","清陰獨步禪起時，徙倚前看看不足。"]', '["洞庭仙山但生橘，不生凡木與梨栗。","真子無私自不栽，感得一株階下出。","細葉繁枝委露新，四时常綠不关春。","若言此物無道性，何意孤生来就人。","二月三月山初暖，最愛低簷數枝短。","白花不用烏銜来，自有风吹手中满，九月十月爭破顏。","金實離離色殷殷，一夜天晴香满山。","天生珍木異於俗，俗士来逢不敢觸。","清陰独步禪起时，徙倚前看看不足。"]', '诗', 'shi', '', NULL, '洞庭山維諒上人院階前孤生橘樹歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52031657-fa7f-46a3-81e9-690298f6995d', '春夜賦得漉水囊歌送鄭明府', '春夜賦得漉水囊歌送鄭明府', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["吳縑楚練何白皙，居士持來遺禪客。","禪客能裁漉水囊，不用衣工秉刀尺。","先師遺我式無缺，一濾一翻心敢賒。","夕望東峰思漱盥，曨曨斜月懸燈紗。","徙倚花前漏初斷，白猨爭嘯驚禪伴。","玉瓶徐瀉賞涓涓，濺著蓮衣水珠滿。","因識仁人爲宦情，還如漉水愛蒼生。","聊歌一曲與君別，莫忘寒泉見底清。"]', '["吳縑楚練何白皙，居士持来遺禪客。","禪客能裁漉水囊，不用衣工秉刀尺。","先師遺我式無缺，一濾一翻心敢賒。","夕望东峰思漱盥，曨曨斜月懸灯紗。","徙倚花前漏初斷，白猨爭嘯驚禪伴。","玉瓶徐瀉賞涓涓，濺著蓮衣水珠满。","因識仁人爲宦情，還如漉水愛蒼生。","聊歌一曲與君別，莫忘寒泉见底清。"]', '诗', 'shi', '', NULL, '春夜賦得漉水囊歌送鄭明府 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ae4a38c-eda3-43c6-a303-a231c1afa9db', '湛處士枸杞架歌', '湛处士枸杞架歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["天生靈草生靈地，誤生人間人不貴。","獨君井上有一根，始覺人間衆芳草。","拖線垂絲宜曙看，裴回滿架何珊珊。","春風亦解愛此物，褭褭時來傍香實。","濕雲綴葉擺不去，翠羽銜花驚畏失。","肯羨孤松不凋色，皇天正氣肅不得。","我獨全生異此輩，順時榮落不相背。","孤松自被斧斤傷，獨我柔枝保無害。","黃油酒囊石棊局，吾羨湛生心出俗。","擷芳生影風灑懷，其致翛然此中足。"]', '["天生靈草生靈地，誤生人间人不貴。","独君井上有一根，始覺人间衆芳草。","拖線垂絲宜曙看，裴回满架何珊珊。","春风亦解愛此物，褭褭时来傍香實。","濕云綴葉擺不去，翠羽銜花驚畏失。","肯羨孤松不凋色，皇天正氣肅不得。","我独全生異此輩，順时榮落不相背。","孤松自被斧斤傷，独我柔枝保無害。","黄油酒囊石棊局，吾羨湛生心出俗。","擷芳生影风灑懷，其致翛然此中足。"]', '诗', 'shi', '', NULL, '湛處士枸杞架歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53c20649-82fb-4e0b-94b1-0b1e9425b7b8', '觀裴秀才松石障歌', '观裴秀才松石障歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["誰工此松唯拂墨，巧思丹青營不得。","初寫松梢風正生，此中勢與真松爭。","高柯細葉動颯颯，乍聽幽飀如有聲。","左右雙松更奇絕，龍鱗麈尾仍半折。","經春寒色聚不散，逼座陰陰將下雪。","荆門石狀凌璵璠，蹙成數片倚松根。","何年蒨蒨苔黏跡，幾夜潺潺水擊痕。","裴生詩家後來客，爲我開圖翫松石。","對之自有高世心，何事勞君上山屐。"]', '["誰工此松唯拂墨，巧思丹青營不得。","初寫松梢风正生，此中勢與真松爭。","高柯細葉动颯颯，乍听幽飀如有声。","左右雙松更奇絕，龙鱗麈尾仍半折。","經春寒色聚不散，逼座陰陰將下雪。","荆门石狀凌璵璠，蹙成數片倚松根。","何年蒨蒨苔黏跡，幾夜潺潺水擊痕。","裴生诗家後来客，爲我开圖翫松石。","对之自有高世心，何事勞君上山屐。"]', '诗', 'shi', '', NULL, '觀裴秀才松石障歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db20c6f2-4d08-4acf-a055-5fe1a4ff4af8', '送顧處士歌', '送顧处士歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["吳門顧子予早聞，風貌真古誰似君。","人中黃憲與顏子，物表孤高將片雲。","性背時人高且逸，平生好古無儔匹。","醉書在篋稱絕倫，神畫開廚怕飛出。","謝氏檀郎亦可儔，道情還似我家流。","安貧日日讀書坐，不見將名干五侯。","知君別業長洲外，欲行秋田循畎澮。","門前便取觳觫乘，腰上還將鹿盧佩。","禪子有情非世情，御荈貢餘聊贈行。","滿道喧喧遇君別，爭窺玉潤與冰清。"]', '["吳门顧子予早闻，风貌真古誰似君。","人中黄憲與顏子，物表孤高將片云。","性背时人高且逸，平生好古無儔匹。","醉书在篋稱絕倫，神畫开廚怕飞出。","謝氏檀郎亦可儔，道情還似我家流。","安貧日日读书坐，不见將名干五侯。","知君別業长洲外，欲行秋田循畎澮。","门前便取觳觫乘，腰上還將鹿盧佩。","禪子有情非世情，御荈貢餘聊贈行。","满道喧喧遇君別，爭窺玉潤與冰清。"]', '诗', 'shi', '', NULL, '送顧處士歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69debd7f-bf3f-4ef1-a64e-8906aad836e3', '水精數珠歌', '水精數珠歌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["西方真人爲行密，臂上記珠皎如日。","佛名無著心亦空，珠去珠來體常一。","誰道佛身千萬身，重重只向心中出。"]', '["西方真人爲行密，臂上記珠皎如日。","佛名無著心亦空，珠去珠来體常一。","誰道佛身千万身，重重只向心中出。"]', '诗', 'shi', '', NULL, '水精數珠歌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('435cea06-ac01-4ca7-a132-bcc81d56427f', '兵後西日溪行', '兵後西日溪行', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一從清氣上爲天，仙叟何年見乾海。","黃河幾度濁復清，此水如今未曾改。","西尋仙人渚，誤入桃花穴。","風吹花片使我迷，時時問山驚踏雪。","石梁丹竈意更奇，春草不生多故轍。","我來隱道非隱身，如今世上無風塵。","路是武陵路，人非秦代人。","飯松得高侶，濯足偶清津。","數片昔賢磬石在，幾迴竝坐戴綸巾。"]', '["一從清氣上爲天，仙叟何年见乾海。","黄河幾度濁复清，此水如今未曾改。","西尋仙人渚，誤入桃花穴。","风吹花片使我迷，时时问山驚踏雪。","石梁丹竈意更奇，春草不生多故轍。","我来隐道非隐身，如今世上無风塵。","路是武陵路，人非秦代人。","飯松得高侶，濯足偶清津。","數片昔賢磬石在，幾迴竝坐戴綸巾。"]', '诗', 'shi', '', NULL, '兵後西日溪行 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db95391f-b0af-4027-addd-6e970841188e', '姑蘇行', '姑蘇行', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["古臺不見秋草衰，却憶吳王全盛時。","千年月照秋草上，吳王在時幾迴望。","至今月出君不還，世人空對姑蘇山。","山中精靈安可覩，轍跡人蹤麋鹿聚。","嬋娟西子傾國容，化作寒陵一堆土。"]', '["古台不见秋草衰，却憶吳王全盛时。","千年月照秋草上，吳王在时幾迴望。","至今月出君不還，世人空对姑蘇山。","山中精靈安可覩，轍跡人蹤麋鹿聚。","嬋娟西子傾国容，化作寒陵一堆土。"]', '诗', 'shi', '', NULL, '姑蘇行 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd2adb6-8bae-4f5c-bcc2-24ceb75895b5', '短歌行', '短歌行', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["古人若不死，吾亦何所悲。","蕭蕭煙雨九原上，白楊青松葬者誰。","貴賤同一塵，死生同一指。","人生在世共如此，何異浮雲與流水。","短歌行，短歌無窮日已傾。","鄴宮梁苑徒有名，春草秋風傷我情。","何爲不學金仙侶，一悟空王無死生。"]', '["古人若不死，吾亦何所悲。","蕭蕭煙雨九原上，白楊青松葬者誰。","貴賤同一塵，死生同一指。","人生在世共如此，何異浮云與流水。","短歌行，短歌無窮日已傾。","鄴宮梁苑徒有名，春草秋风傷我情。","何爲不学金仙侶，一悟空王無死生。"]', '诗', 'shi', '', NULL, '短歌行 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0cbc1c9-1684-43e8-9277-df5ef2354ffe', '山月行', '山月行', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["家家望秋月，不及秋山望。","山中萬境長寂寥，夜夜孤明我山上。","海人皆言生海東，山人自謂出山中。","憂虞歡樂皆占月，月本無心同不同。","自從有月山不改，古人望盡今人在。","不知萬世今夜時，孤月將□誰更待。"]', '["家家望秋月，不及秋山望。","山中万境长寂寥，夜夜孤明我山上。","海人皆言生海东，山人自謂出山中。","憂虞歡乐皆占月，月本無心同不同。","自從有月山不改，古人望尽今人在。","不知万世今夜时，孤月將□誰更待。"]', '诗', 'shi', '', NULL, '山月行 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ee3623-7412-4f9a-a181-96f798c2b512', '顧渚行寄裴方舟', '顧渚行寄裴方舟', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["我有雲泉隣渚山，山中茶事頗相關。","鶗鴂鳴時芳草死，山家漸欲收茶子。","伯勞飛日芳草滋，山僧又是採茶時。","繇來慣採無近遠，陰嶺長兮陽崖淺。","大寒山下葉未生，小寒山中葉初卷。","吳婉攜籠上翠微，蒙蒙香刺罥春衣。","迷山乍被落花亂，度水時驚啼鳥飛。","家園不遠乘露摘，歸時露彩猶滴瀝。","初看怕出欺玉英，更取煎來勝金液。","昨夜西峰雨色過，朝尋新茗復如何。","女宮露澀青芽老，堯市人稀紫筍多。","紫筍青芽誰得識，日暮採之長太息。","清泠真人待子元，貯此芳香思何極。"]', '["我有云泉隣渚山，山中茶事頗相关。","鶗鴂鳴时芳草死，山家漸欲收茶子。","伯勞飞日芳草滋，山僧又是採茶时。","繇来慣採無近远，陰嶺长兮陽崖淺。","大寒山下葉未生，小寒山中葉初卷。","吳婉携籠上翠微，蒙蒙香刺罥春衣。","迷山乍被落花亂，度水时驚啼鸟飞。","家园不远乘露摘，归时露彩猶滴瀝。","初看怕出欺玉英，更取煎来勝金液。","昨夜西峰雨色過，朝尋新茗复如何。","女宮露澀青芽老，堯市人稀紫筍多。","紫筍青芽誰得識，日暮採之长太息。","清泠真人待子元，貯此芳香思何極。"]', '诗', 'shi', '', NULL, '顧渚行寄裴方舟 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af62b125-aa6a-477f-9f7e-f40569724899', '武源行贈丘卿岑', '武源行贈丘卿岑', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["昔年羣盜阻江東，吳山動搖楚澤空。","齊人亦戴蜂蠆毒，美稷化爲荆棘藂。","洶洶四顧多窟穴，浮雲白波名不同。","萬人死地當虎口，一旦生涯懸彀中。","昨日將軍徇死節，悉向生民陷成血。","胸中豹略張陣雲，握內虵矛揮白雪。","長洲南去接孤城，居人散盡鼓譟驚。","三春不見芳草色，四面唯聞刁斗聲。","此時狂寇紛如市，君當要衝固深壘。","縱橫計出皆獲全，士卒身先每輕死。","埽平氛祲望吳門，人間歲美桑柘繁。","比屋生全受君賜，連營罷戰賴君恩。","如何棄置功不錄，通籍無名滯江曲。","灞亭不重李將軍，漢爵猶輕蘇屬國。","荒營寂寂隱山椒，春意空驚故柳條。","野戰攻城盡如此，即今誰是霍嫖姚。"]', '["昔年羣盜阻江东，吳山动搖楚澤空。","齊人亦戴蜂蠆毒，美稷化爲荆棘藂。","洶洶四顧多窟穴，浮云白波名不同。","万人死地當虎口，一旦生涯懸彀中。","昨日將軍徇死節，悉向生民陷成血。","胸中豹略張陣云，握內虵矛揮白雪。","长洲南去接孤城，居人散尽鼓譟驚。","三春不见芳草色，四面唯闻刁斗声。","此时狂寇紛如市，君當要衝固深壘。","縱橫計出皆獲全，士卒身先每轻死。","埽平氛祲望吳门，人间歲美桑柘繁。","比屋生全受君賜，連營罷戰賴君恩。","如何棄置功不錄，通籍無名滯江曲。","灞亭不重李將軍，漢爵猶轻蘇屬国。","荒營寂寂隐山椒，春意空驚故柳條。","野戰攻城尽如此，即今誰是霍嫖姚。"]', '诗', 'shi', '', NULL, '武源行贈丘卿岑 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f70d54e7-a999-4359-8355-c1917796cdb2', '長安少年行', '长安少年行', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["翠樓春酒蝦蟇陵，長安少年皆共矜。","紛紛半醉綠槐道，躞蹀花驄驕不勝。"]', '["翠楼春酒蝦蟇陵，长安少年皆共矜。","紛紛半醉綠槐道，躞蹀花驄驕不勝。"]', '诗', 'shi', '', NULL, '長安少年行 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd8db3ba-96ed-4396-94bf-a52fddf5e125', '風入松', '风入松', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["西嶺松聲落日秋，千枝萬葉風飀飀。","美人援琴弄成曲，寫得松間聲斷續。","聲斷續，清我魂，流波壞陵安足論。","美人夜坐月明裏，含少商兮點清徵。","風何淒兮飄飄，攪寒松兮又夜起。","夜未央，曲何長，金徽更促聲泱泱。","何人此時不得意，意苦弦悲聞客堂。"]', '["西嶺松声落日秋，千枝万葉风飀飀。","美人援琴弄成曲，寫得松间声斷續。","声斷續，清我魂，流波壞陵安足論。","美人夜坐月明裏，含少商兮点清徵。","风何淒兮飄飄，攪寒松兮又夜起。","夜未央，曲何长，金徽更促声泱泱。","何人此时不得意，意苦弦悲闻客堂。"]', '诗', 'shi', '', NULL, '風入松 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6383bc37-f778-4a0e-ba86-453a1c847052', '陪盧中丞閑遊山寺', '陪盧中丞闲游山寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["野寺出人境，捨舟登遠峰。","林開明見月，萬壑靜聞鐘。","擁燭明山翠，交麾動水容。","如何股肱守，塵外得相逢。"]', '["野寺出人境，捨舟登远峰。","林开明见月，万壑静闻鐘。","擁燭明山翠，交麾动水容。","如何股肱守，塵外得相逢。"]', '诗', 'shi', '', NULL, '陪盧中丞閑遊山寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3f70416-ea7e-4968-8668-117d15499d1b', '湖南草堂讀書招李少府', '湖南草堂读书招李少府', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["削去僧家事，南池便隱居。","爲憐松子壽，還卜道家書。","藥院常無客，茶樽獨對余。","有時招逸史，來飯野中蔬。"]', '["削去僧家事，南池便隐居。","爲怜松子壽，還卜道家书。","藥院常無客，茶樽独对余。","有时招逸史，来飯野中蔬。"]', '诗', 'shi', '', NULL, '湖南草堂讀書招李少府 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18dd38a4-0ad4-4ae9-ad90-4e1a2572b486', '荅李季蘭', '荅李季蘭', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["天女來相試，將花欲染衣。","禪心竟不起，還捧舊花歸。"]', '["天女来相試，將花欲染衣。","禪心竟不起，還捧旧花归。"]', '诗', 'shi', '', NULL, '荅李季蘭 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b94247-0fba-45d6-93cb-50069332c076', '酬鄭判官湖上見贈', '酬鄭判官湖上见贈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["歲歲湖南隱已成，如何星使忽知名。","沙鷗慣識無心客，今日逢君不解驚。"]', '["歲歲湖南隐已成，如何星使忽知名。","沙鷗慣識無心客，今日逢君不解驚。"]', '诗', 'shi', '', NULL, '酬鄭判官湖上見贈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b059853-57c0-434e-a748-879d646fb580', '送旻上人遊天台', '送旻上人游天台', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["真心不廢別，試看越溪清。","知汝機忘盡，春山自有情。","月思華頂宿，雲愛石門行。","海近應須汎，無令鷗鷺驚。"]', '["真心不廢別，試看越溪清。","知汝機忘尽，春山自有情。","月思华頂宿，云愛石门行。","海近應須汎，無令鷗鷺驚。"]', '诗', 'shi', '', NULL, '送旻上人遊天台 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eecf361b-0425-492e-8ee8-b3c65b626636', '送別', '送別', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["聞說情人怨別情，霜天淅瀝在寒城。","長宵漫漫角聲發，禪子無心恨亦生。"]', '["闻说情人怨別情，霜天淅瀝在寒城。","长宵漫漫角声發，禪子無心恨亦生。"]', '诗', 'shi', '', NULL, '送別 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd542e66-4935-4424-a967-44b0c712f9fa', '與昂上人兩字繼合四句初字日', '與昂上人兩字繼合四句初字日', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["有一鳥雛，凌寒獨宿。","若逢雲雨，兩兩相逐。"]', '["有一鸟雛，凌寒独宿。","若逢云雨，兩兩相逐。"]', '诗', 'shi', '', NULL, '與昂上人兩字繼合四句初字日 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fb5985f-b3a7-4815-ae19-f7ab098c1e5c', '次日', '次日', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["野外有一人，獨立無四隣。","彼見是我身，我見是彼身。"]', '["野外有一人，独立無四隣。","彼见是我身，我见是彼身。"]', '诗', 'shi', '', NULL, '次日 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8f1dfe9-2f17-42bb-99df-879459d09dc8', '皇太子頻賜存問幷索唱和新詩因有陳謝', '皇太子頻賜存问幷索唱和新诗因有陳謝', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["望苑招延後，禪扉訪道餘。","祗言俟文雅，何意及庸虛。","率性多非學，緣情偶自書。","清風聞寺響，白日見心初。","重道逢軒后，崇儒過魏儲。","青宮列芳梓，玄圃積瓊琚。","鄭鼠寧容者，齊竽久舍諸。","龍懷受恩感，含思幾躊躇。"]', '["望苑招延後，禪扉訪道餘。","祗言俟文雅，何意及庸虛。","率性多非学，緣情偶自书。","清风闻寺响，白日见心初。","重道逢軒后，崇儒過魏儲。","青宮列芳梓，玄圃積瓊琚。","鄭鼠寧容者，齊竽久舍諸。","龙懷受恩感，含思幾躊躇。"]', '诗', 'shi', '', NULL, '皇太子頻賜存問幷索唱和新詩因有陳謝 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dd4ed1a-be62-4feb-ad45-67023f70aedf', '禁中法會應制', '禁中法會應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["天上萬年枝，人間不可窺。","道場三教會，心地百王期。","侍讀霑恩早，傳香駐日遲。","在筵還向道，通籍許言詩。","空媿陪仙列，何階答聖慈。","從今精至理，長願契無爲。"]', '["天上万年枝，人间不可窺。","道場三教會，心地百王期。","侍读霑恩早，傳香駐日遲。","在筵還向道，通籍許言诗。","空媿陪仙列，何階答聖慈。","從今精至理，长願契無爲。"]', '诗', 'shi', '', NULL, '禁中法會應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21cc13eb-a312-48f6-b334-e28b334b45bf', '降誕日內庭獻壽應制', '降誕日內庭獻壽應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["慶壽千齡遠，敷仁萬國通。","登霄欣有路，捧日媿無功。","仙駕三山上，龍生二月中。","修齋長樂殿，講道大明宮。","此地人難到，諸天事不同。","法筵花散後，空界滿香風。"]', '["慶壽千齡远，敷仁万国通。","登霄欣有路，捧日媿無功。","仙駕三山上，龙生二月中。","修斋长乐殿，講道大明宮。","此地人难到，諸天事不同。","法筵花散後，空界满香风。"]', '诗', 'shi', '', NULL, '降誕日內庭獻壽應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921324d6-b166-4273-b2b8-58fdc567303d', '寺中柿樹一蒂四顆詠應制', '寺中柿樹一蒂四顆詠應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["珍木生奇畝，低枝拂梵宮。","因開四界分，本自百花中。","當夏陰涵綠，臨秋色變紅。","君看藥草喻，何減太陽功。"]', '["珍木生奇畝，低枝拂梵宮。","因开四界分，本自百花中。","當夏陰涵綠，臨秋色变紅。","君看藥草喻，何減太陽功。"]', '诗', 'shi', '', NULL, '寺中柿樹一蒂四顆詠應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('629673bf-1627-4277-8933-9d286026b661', '早秋降誕日獻壽二首應制 一', '早秋降誕日獻壽二首應制 一', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["秋蓂開六葉，元聖誕千年。","繞殿祥風起，當空瑞日懸。","道光中國主，人識大羅仙。","敢贊無疆壽，香花上法筵。"]', '["秋蓂开六葉，元聖誕千年。","繞殿祥风起，當空瑞日懸。","道光中国主，人識大羅仙。","敢贊無疆壽，香花上法筵。"]', '诗', 'shi', '', NULL, '早秋降誕日獻壽二首應制 一 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5362025b-04dc-4e24-87cd-9d6ab303628e', '早秋降誕日獻壽二首應制 二', '早秋降誕日獻壽二首應制 二', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["萬方瞻聖日，九土仰清光。","磬地山河壯，彌天福壽長。","瑞煙薰法界，真偈啓仁王。","看獻千秋樂，千秋樂未央。"]', '["万方瞻聖日，九土仰清光。","磬地山河壯，彌天福壽长。","瑞煙薰法界，真偈啓仁王。","看獻千秋乐，千秋乐未央。"]', '诗', 'shi', '', NULL, '早秋降誕日獻壽二首應制 二 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81046667-7eb1-4e93-9482-a165c3cdb153', '駕幸天長寺應制', '駕幸天长寺應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["天界宜春賞，禪門不掩關。","宸遊雙闕外，僧引百花間。","車馬喧長路，煙雲淨遠山。","觀空復觀俗，皇鑒此中閑。"]', '["天界宜春賞，禪门不掩关。","宸游雙闕外，僧引百花间。","车马喧长路，煙云淨远山。","观空复观俗，皇鑒此中闲。"]', '诗', 'shi', '', NULL, '駕幸天長寺應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f69b1eec-7a95-469d-bc42-a4f5af76f71d', '九月菊花詠應制', '九月菊花詠應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["可訝東籬菊，能知節候芳。","細枝青玉潤，繁蘂碎金香。","爽氣浮朝露，濃姿帶夜霜。","泛杯傳壽酒，應共樂時康。"]', '["可訝东籬菊，能知節候芳。","細枝青玉潤，繁蘂碎金香。","爽氣浮朝露，濃姿带夜霜。","泛杯傳壽酒，應共乐时康。"]', '诗', 'shi', '', NULL, '九月菊花詠應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ccbaef5-6d1e-456c-8a04-204bf22852e0', '駕幸聖容院應制', '駕幸聖容院應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["大唐國裏千年聖，王舍城中百億身。","却指容顏非我相，自言空色是吾真。","深殿虔心隨寶輦，廣庭徐步引金輪。","古來貴重緣親近，狂客慙爲侍從臣。"]', '["大唐国裏千年聖，王舍城中百億身。","却指容顏非我相，自言空色是吾真。","深殿虔心隨寶輦，廣庭徐步引金輪。","古来貴重緣親近，狂客慙爲侍從臣。"]', '诗', 'shi', '', NULL, '駕幸聖容院應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8312d3c-714f-429a-9a7a-c915224748de', '聖恩顧問獨遊月磴閣直書其事應制', '聖恩顧问独游月磴閣直书其事應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["禪居河畔無多地，來往尋春物正華。","磴道上盤千畝竹，欄干低壓萬人家。","簷前施飯來飛鳥，林下行香踏落花。","自解剎那知佛性，不勞更喻幾塵沙。"]', '["禪居河畔無多地，来往尋春物正华。","磴道上盤千畝竹，欄干低壓万人家。","簷前施飯来飞鸟，林下行香踏落花。","自解剎那知佛性，不勞更喻幾塵沙。"]', '诗', 'shi', '', NULL, '聖恩顧問獨遊月磴閣直書其事應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76be28ad-f2ca-4efc-b6f1-a0a8660ce410', '安國寺隨駕幸興唐觀應制', '安国寺隨駕幸兴唐观應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["東林何殿是西鄰，禪客垣牆接羽人。","萬乘遊仙宗有道，三車引路本無塵。","初傳寶訣長生術，已證金剛不壞身。","兩地盡修天上事，共瞻鑾駕重來巡。"]', '["东林何殿是西鄰，禪客垣牆接羽人。","万乘游仙宗有道，三车引路本無塵。","初傳寶訣长生術，已證金剛不壞身。","兩地尽修天上事，共瞻鑾駕重来巡。"]', '诗', 'shi', '', NULL, '安國寺隨駕幸興唐觀應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d051af0-83ac-4799-ae24-b0486d3aaf22', '賀王起', '賀王起', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["從辭鳳閣掌絲綸，便向青雲領貢賓。","再闢文場無枉路，兩開金榜絕冤人。","眼看龍化門前水，手放鶯飛谷口春。","明日定歸台席去，鶺鴒原上共陶鈞。"]', '["從辞鳳閣掌絲綸，便向青云領貢賓。","再闢文場無枉路，兩开金榜絕冤人。","眼看龙化门前水，手放鶯飞谷口春。","明日定归台席去，鶺鴒原上共陶鈞。"]', '诗', 'shi', '', NULL, '賀王起 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('067d10ee-d8f8-4161-904f-c413c8cd801a', '賀幸普濟寺應制', '賀幸普濟寺應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["南方寶界幾由旬，八部同瞻一佛身。","寺壓山河天宇靜，樓懸日月鏡光新。","重城柳暗東風曙，複道花明上苑春。","向晚鑾輿歸鳳闕，曲江池上動青蘋。"]', '["南方寶界幾由旬，八部同瞻一佛身。","寺壓山河天宇静，楼懸日月镜光新。","重城柳暗东风曙，複道花明上苑春。","向晚鑾輿归鳳闕，曲江池上动青蘋。"]', '诗', 'shi', '', NULL, '賀幸普濟寺應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('536f7f15-1020-4b20-9c23-910e2c64cc84', '紅樓院應制', '紅楼院應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["紅樓疑見白毫光，寺逼宸居福盛唐。","支遁愛山情謾切，曇摩泛海路空長。","經聲夜息聞天語，鑪氣晨飄接御香。","誰道此中難可到，自憐深院得徊翔。"]', '["紅楼疑见白毫光，寺逼宸居福盛唐。","支遁愛山情謾切，曇摩泛海路空长。","經声夜息闻天語，鑪氣晨飄接御香。","誰道此中难可到，自怜深院得徊翔。"]', '诗', 'shi', '', NULL, '紅樓院應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad79561a-2047-4894-b9cc-b0d0db7e384d', '再入道場紀事應制', '再入道場紀事應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["南方歸去再生天，內殿今年異昔年。","見闢乾坤新定位，看題日月更高懸。","行隨車輦登仙路，坐近爐煙講法筵。","自喜恩深陪侍從，兩朝長在聖人前。"]', '["南方归去再生天，內殿今年異昔年。","见闢乾坤新定位，看題日月更高懸。","行隨车輦登仙路，坐近爐煙講法筵。","自喜恩深陪侍從，兩朝长在聖人前。"]', '诗', 'shi', '', NULL, '再入道場紀事應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e9cf2f9-ea87-4d05-8742-ef85f4015b51', '寺中賞花應制', '寺中賞花應制', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["東風萬里送香來，上界千花向日開。","却笑霞樓紫芝侶，桃源仙洞訪仙才。"]', '["东风万里送香来，上界千花向日开。","却笑霞楼紫芝侶，桃源仙洞訪仙才。"]', '诗', 'shi', '', NULL, '寺中賞花應制 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c76a49-0ceb-4adf-abf5-903635a98441', '九月十五日夜宿鄭尚書絪東亭望月寄杜給事', '九月十五日夜宿鄭尚书絪东亭望月寄杜給事', '090f6bfa-0d45-4ed8-b2b9-b69a3b07e59d', '唐', '["霜天晴夜宿東齋，松竹交陰愜素懷。","迥出風塵心得地，可憐三五月當階。","清光滿院恩情見，寒色臨門笑語諧。","霄漢路殊從道合，往來人事不相乖。"]', '["霜天晴夜宿东斋，松竹交陰愜素懷。","迥出风塵心得地，可怜三五月當階。","清光满院恩情见，寒色臨门笑語諧。","霄漢路殊從道合，往来人事不相乖。"]', '诗', 'shi', '', NULL, '九月十五日夜宿鄭尚書絪東亭望月寄杜給事 廣宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a11467a-8bf2-45dc-9f86-e3a0b1fdff30', '酬盧仝見訪不遇題壁', '酬盧仝见訪不遇題壁', 'e6ecf4e3-0f62-4d6a-9392-8ca3fa508f68', '唐', '["長壽寺石壁，盧公一首詩。","渴讀即不渴，飢讀即不飢。","鯨吞海水盡，露出珊瑚枝。","海神知貴不知價，留向人間光照夜。"]', '["长壽寺石壁，盧公一首诗。","渴读即不渴，飢读即不飢。","鯨吞海水尽，露出珊瑚枝。","海神知貴不知價，留向人间光照夜。"]', '诗', 'shi', '', NULL, '酬盧仝見訪不遇題壁 含曦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997cd3bd-760b-41f1-af84-40b153b838dc', '旅中荅喻軍事問客情', '旅中荅喻軍事问客情', '0469f780-2ef9-4f8c-8acc-fa6a08b96b89', '唐', '["一自游他國，相逢少故人。","縱然爲客樂，爭似在家貧。","畜恨霜侵鬢，搜詩病入神。","若非憐片善，誰肯問風塵。"]', '["一自游他国，相逢少故人。","縱然爲客乐，爭似在家貧。","畜恨霜侵鬢，搜诗病入神。","若非怜片善，誰肯问风塵。"]', '诗', 'shi', '', NULL, '旅中荅喻軍事問客情 善生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c578582-d531-48e3-949c-76758c155a0b', '贈盧逸人', '贈盧逸人', '0469f780-2ef9-4f8c-8acc-fa6a08b96b89', '唐', '["高眠巖野間，至藝敵應難。","詩苦無多首，藥靈惟一丸。","引泉魚落釜，攀果露沾冠。","已得嵇康趣，逢迎事每闌。"]', '["高眠巖野间，至藝敵應难。","诗苦無多首，藥靈惟一丸。","引泉鱼落釜，攀果露沾冠。","已得嵇康趣，逢迎事每闌。"]', '诗', 'shi', '', NULL, '贈盧逸人 善生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c3f998e-32dc-4be9-bcc5-ec77185c7e4b', '送玉禪師', '送玉禪師', '0469f780-2ef9-4f8c-8acc-fa6a08b96b89', '唐', '["飄然無定迹，迥與律乘違。","入郭隨緣住，思山破夏歸。","盂擎數家飯，衲乞幾人衣。","洞了曹溪旨，寧輸俗者機。"]', '["飄然無定迹，迥與律乘違。","入郭隨緣住，思山破夏归。","盂擎數家飯，衲乞幾人衣。","洞了曹溪旨，寧輸俗者機。"]', '诗', 'shi', '', NULL, '送玉禪師 善生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fef71c0-a42f-49c8-bd26-df58bfb7f8e7', '送智光之南值雨', '送智光之南值雨', '0469f780-2ef9-4f8c-8acc-fa6a08b96b89', '唐', '["結束衣囊了，炎州定去游。","草堂方惜別，山雨爲相留。","又得一宵話，免生千里愁。","莫辭重卜日，後會必經秋。"]', '["結束衣囊了，炎州定去游。","草堂方惜別，山雨爲相留。","又得一宵話，免生千里愁。","莫辞重卜日，後會必經秋。"]', '诗', 'shi', '', NULL, '送智光之南值雨 善生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d337e5a0-0265-4747-972f-d41a99d83489', '謝白樂天招', '謝白乐天招', '199f01c5-be96-4d74-acc7-311228ce40e8', '唐', '["山僧野性好林泉，每向巖阿倚石眠。","不解栽松陪玉勒，惟能引水種金蓮。","白雲乍可來青嶂，明月難教下碧天。","城市不能飛錫去，恐妨鶯囀翠樓前。"]', '["山僧野性好林泉，每向巖阿倚石眠。","不解栽松陪玉勒，惟能引水種金蓮。","白云乍可来青嶂，明月难教下碧天。","城市不能飞錫去，恐妨鶯囀翠楼前。"]', '诗', 'shi', '', NULL, '謝白樂天招 韜光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43acca77-47dc-4735-9ac0-e79bd3c0973a', '五歲詠花', '五歲詠花', 'af9b9749-2018-4d7e-9199-f68932ccbd05', '唐', '["花開滿樹紅，花落萬枝空。","唯餘一孕在，明日定隨風。"]', '["花开满樹紅，花落万枝空。","唯餘一孕在，明日定隨风。"]', '诗', 'shi', '', NULL, '五歲詠花 知玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb6ac873-ad3a-4f6f-881c-38fdc072d624', '祝堯詩', '祝堯诗', 'af9b9749-2018-4d7e-9199-f68932ccbd05', '唐', '["生天本自生天業，未必求仙便得仙。","鶴背傾危龍背滑，君王且住一千年。"]', '["生天本自生天業，未必求仙便得仙。","鹤背傾危龙背滑，君王且住一千年。"]', '诗', 'shi', '', NULL, '祝堯詩 知玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26806e16-f95a-4ea8-9162-15b848082b8e', '荅僧澈', '荅僧澈', 'af9b9749-2018-4d7e-9199-f68932ccbd05', '唐', '["觀君法苑思沖虛，使我真乘刃有餘。","若使龍光時可待，應憐僧肇論成初。","五車外典知誰敵，九趣多才恐不如。","蕭寺講軒橫淡蕩，帝鄉雲樹正扶疎。","幾生曾得闍瑜意，今日堪將貝葉書。","一振微言冠千古，何人執卷問吾廬。"]', '["观君法苑思沖虛，使我真乘刃有餘。","若使龙光时可待，應怜僧肇論成初。","五车外典知誰敵，九趣多才恐不如。","蕭寺講軒橫淡蕩，帝乡云樹正扶疎。","幾生曾得闍瑜意，今日堪將貝葉书。","一振微言冠千古，何人執卷问吾廬。"]', '诗', 'shi', '', NULL, '荅僧澈 知玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c101d4-3425-442b-bce2-dbd80d9f958e', '月夜懷劉秀才', '月夜懷劉秀才', 'd820ca19-4c6e-4ad4-9ee6-bb87d9a74ce6', '唐', '["獨夜相思但自勞，阮生吟罷夢雲濤。","此時小定未禪寂，古塔月中松磬高。"]', '["独夜相思但自勞，阮生吟罷梦云濤。","此时小定未禪寂，古塔月中松磬高。"]', '诗', 'shi', '', NULL, '月夜懷劉秀才 元孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c2c3b54-7289-4df9-987b-f84f63191fbb', '送李四校書', '送李四校书', 'd820ca19-4c6e-4ad4-9ee6-bb87d9a74ce6', '唐', '["朱絲寫別鶴泠泠，詩滿紅箋月滿庭。","莫學楚狂隳姓字，知音還有子期聽。"]', '["朱絲寫別鹤泠泠，诗满紅箋月满庭。","莫学楚狂隳姓字，知音還有子期听。"]', '诗', 'shi', '', NULL, '送李四校書 元孚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e303bb-2186-46d7-90fc-f33fc26b8530', '邊思', '邊思', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["西北黃雲暮，聲聲畫角愁。","陰山一夜雨，白草四郊秋。","亂雁鳴寒渡，飛沙入廢樓。","何時番色盡，此地見芳洲。"]', '["西北黄云暮，声声畫角愁。","陰山一夜雨，白草四郊秋。","亂雁鳴寒渡，飞沙入廢楼。","何时番色尽，此地见芳洲。"]', '诗', 'shi', '', NULL, '邊思 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b5e17d8-03a9-40bd-a99d-baf6b994a05d', '八月十五夜翫月', '八月十五夜翫月', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["尋常三五夜，不是不嬋娟。","及至中秋滿，還勝別夜圓。","清光凝有露，皓魄爽無煙。","自古人皆望，年來又一年。"]', '["尋常三五夜，不是不嬋娟。","及至中秋满，還勝別夜圓。","清光凝有露，皓魄爽無煙。","自古人皆望，年来又一年。"]', '诗', 'shi', '', NULL, '八月十五夜翫月 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48e2260b-6d78-4713-bf1b-2df974a97f80', '尋山僧真勝上人不遇', '尋山僧真勝上人不遇', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["松下禪栖所，苔滋徑莫分。","青山春暮見，流水夜深聞。","不坐看心石，應隨出定雲。","猨猱非可問，巖谷自空曛。"]', '["松下禪栖所，苔滋徑莫分。","青山春暮见，流水夜深闻。","不坐看心石，應隨出定云。","猨猱非可问，巖谷自空曛。"]', '诗', 'shi', '', NULL, '尋山僧真勝上人不遇 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57015630-19e4-4820-8f3e-3a83e481e5fd', '贈李溟秀才', '贈李溟秀才', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["南居古廟深，高樹宿山禽。","明月上清漢，騷人動楚吟。","數篇正始韻，一片補亡心。","孤悄欺何謝，雲波不可尋。"]', '["南居古廟深，高樹宿山禽。","明月上清漢，騷人动楚吟。","數篇正始韻，一片補亡心。","孤悄欺何謝，云波不可尋。"]', '诗', 'shi', '', NULL, '贈李溟秀才 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c175f8ef-afbe-4fb6-bedd-7144eaea7433', '送石秀才', '送石秀才', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["正是歎羈游，知音拜楚侯。","何須辭遠道，自可樂扁舟。","倚棹江洲雨，聞猨島岫秋。","謝家山水興，終日待詩流。"]', '["正是歎羈游，知音拜楚侯。","何須辞远道，自可乐扁舟。","倚棹江洲雨，闻猨島岫秋。","謝家山水兴，終日待诗流。"]', '诗', 'shi', '', NULL, '送石秀才 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d76d62-cd8f-419b-863d-bdbadf291422', '送造微上人游五臺及禮本師', '送造微上人游五台及禮本師', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["寒空金錫響，欲過渭陽津。","極目多來鴈，孤城少故人。","與師雖別久，於法本相親。","又對清涼月，中宵語宿因。"]', '["寒空金錫响，欲過渭陽津。","極目多来鴈，孤城少故人。","與師雖別久，於法本相親。","又对清涼月，中宵語宿因。"]', '诗', 'shi', '', NULL, '送造微上人游五臺及禮本師 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38171e7f-158a-43d6-bf6e-be26927a569b', '送禪師宗極歸玉峰', '送禪師宗極归玉峰', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["背郭去歸宿，頭陀意頗濃。","鶴爭栖遠樹，猨鬬上孤峰。","夜戍經霜月，秋城過雨鐘。"]', '["背郭去归宿，头陀意頗濃。","鹤爭栖远樹，猨鬬上孤峰。","夜戍經霜月，秋城過雨鐘。"]', '诗', 'shi', '', NULL, '送禪師宗極歸玉峰 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee6b0053-2a16-4352-b943-0013e2dae934', '送僧歸舊山', '送僧归旧山', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["談空與破邪，獻壽復榮家。","白日得何偈，青天落幾花。","傳燈皆有分，化俗獨無涯。","却入中峯寺，還知有聚沙。"]', '["談空與破邪，獻壽复榮家。","白日得何偈，青天落幾花。","傳灯皆有分，化俗独無涯。","却入中峯寺，還知有聚沙。"]', '诗', 'shi', '', NULL, '送僧歸舊山 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fd9c5e0-d17c-4f1b-96a3-f1d858f26bcd', '送圓仁三藏歸本國', '送圓仁三藏归本国', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["家山臨晚日，海路信歸橈。","樹滅渾無岸，風生只有潮。","歲窮程未盡，天末國仍遙。","已入閩王夢，香花境外邀。"]', '["家山臨晚日，海路信归橈。","樹滅渾無岸，风生只有潮。","歲窮程未尽，天末国仍遙。","已入閩王梦，香花境外邀。"]', '诗', 'shi', '', NULL, '送圓仁三藏歸本國 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89978b38-400f-42f6-a73a-02f326571044', '送王鍊師歸嵩嶽', '送王鍊師归嵩嶽', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["飄然綠毛節，杳去洛城端。","隔水見秋嶽，兼霜掃石壇。","一溪松色古，半夜鶴聲寒。","迥與人寰別，勞生不可觀。"]', '["飄然綠毛節，杳去洛城端。","隔水见秋嶽，兼霜掃石壇。","一溪松色古，半夜鹤声寒。","迥與人寰別，勞生不可观。"]', '诗', 'shi', '', NULL, '送王鍊師歸嵩嶽 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d2c9460-ed93-442d-a6ce-1c19d0dd3d37', '壽昌節賦得紅雲表夏日', '壽昌節賦得紅云表夏日', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["景候融融陰氣潛，如峰雲共火相兼。","霞光捧日登天上，丹彩乘風入殿簷。","行逐赤龍千歲出，明當朱夏萬方瞻。","微臣多幸逢佳節，得賦殊祥近御簾。"]', '["景候融融陰氣潛，如峰云共火相兼。","霞光捧日登天上，丹彩乘风入殿簷。","行逐赤龙千歲出，明當朱夏万方瞻。","微臣多幸逢佳節，得賦殊祥近御簾。"]', '诗', 'shi', '', NULL, '壽昌節賦得紅雲表夏日 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23c54fa5-704e-4205-bc80-57b12a0a7679', '經廢宮', '經廢宮', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["終日河聲咽暮空，煙愁此地晝濛濛。","錦帆東去沙侵苑，玉輦西來樹滿宮。","魯客望津天欲雪，朔鴻離岸葦生風。","那堪獨立思前事，回首殘陽雉堞紅。"]', '["終日河声咽暮空，煙愁此地晝濛濛。","錦帆东去沙侵苑，玉輦西来樹满宮。","魯客望津天欲雪，朔鴻離岸葦生风。","那堪独立思前事，回首殘陽雉堞紅。"]', '诗', 'shi', '', NULL, '經廢宮 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9917ad6d-e7f7-419f-a007-0ecdd72a859a', '贈識古法師', '贈識古法師', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["重城深寺講初休，却憶家山訪舊游。","對月與君相送夜，聞蛩教我獨驚秋。","雲心杳杳難爲別，鶴性蕭蕭不可留。","遙想孤舟清渭上，飄然帆影起離愁。"]', '["重城深寺講初休，却憶家山訪旧游。","对月與君相送夜，闻蛩教我独驚秋。","云心杳杳难爲別，鹤性蕭蕭不可留。","遙想孤舟清渭上，飄然帆影起離愁。"]', '诗', 'shi', '', NULL, '贈識古法師 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da259365-e96a-44e9-a3eb-894785a24947', '月夜懷劉秀才', '月夜懷劉秀才', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["獨夜相思但自勞，阮生吟罷夢雲濤。","此時小定未禪寂，古塔月中松磐高。"]', '["独夜相思但自勞，阮生吟罷梦云濤。","此时小定未禪寂，古塔月中松磐高。"]', '诗', 'shi', '', NULL, '月夜懷劉秀才 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e01ff71-35a2-46a5-9437-c6c629a024c4', '寄南山景禪師', '寄南山景禪師', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["一度林前見遠公，靜聞真語世情空。","至今寂寞禪心在，任起桃花柳絮風。"]', '["一度林前见远公，静闻真語世情空。","至今寂寞禪心在，任起桃花柳絮风。"]', '诗', 'shi', '', NULL, '寄南山景禪師 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2842a2fa-b7e9-4e20-9019-4e5087e8ebb3', '哭劉得仁', '哭劉得仁', '7dd71e8d-caba-487a-9c09-ca3b81e4821f', '唐', '["爲愛詩名吟至死，風魂雪魄去難招。","直須桂子落墳上，生得一枝冤始消。"]', '["爲愛诗名吟至死，风魂雪魄去难招。","直須桂子落墳上，生得一枝冤始消。"]', '诗', 'shi', '', NULL, '哭劉得仁 栖白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74c36382-c6b5-4065-add5-5c05840f118d', '龍潭', '龙潭', '910d272e-7e77-4ff3-b2d9-02fb0b2835b3', '唐', '["石激懸流雪滿灣，五龍潛處野雲閑。","暫收雷電九峰下，且飲溪潭一水間。","浪引浮槎依北岸，波分曉日浸東山。","回瞻四面如看畫，須信游人不欲還。"]', '["石激懸流雪满灣，五龙潛处野云闲。","暫收雷電九峰下，且饮溪潭一水间。","浪引浮槎依北岸，波分晓日浸东山。","回瞻四面如看畫，須信游人不欲還。"]', '诗', 'shi', '', NULL, '龍潭 應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aee480d4-8058-4cfa-8a2a-639b70a39deb', '題化城寺', '題化城寺', '910d272e-7e77-4ff3-b2d9-02fb0b2835b3', '唐', '["平高選處創蓮宮，一水縈流處處通。","畫閣晝開遲日畔，禪房夜掩碧雲中。","平川不見龍行雨，幽谷遙聞虎嘯風。","偶與遊人論法要，真元浩浩理無窮。"]', '["平高選处創蓮宮，一水縈流处处通。","畫閣晝开遲日畔，禪房夜掩碧云中。","平川不见龙行雨，幽谷遙闻虎嘯风。","偶與游人論法要，真元浩浩理無窮。"]', '诗', 'shi', '', NULL, '題化城寺 應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73c8a0af-0b29-4e04-b22e-9b2d71da6e34', '戴雲山吟', '戴云山吟', '2b9b91a0-112e-429f-81e6-cdf1c869e7c2', '唐', '["人間謾說上天梯，上萬千迴總是迷。","曾似老人巖上坐，清風明月與心齊。"]', '["人间謾说上天梯，上万千迴總是迷。","曾似老人巖上坐，清风明月與心齊。"]', '诗', 'shi', '', NULL, '戴雲山吟 智亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39fcc78f-7ebe-4de5-8e49-76928167f97a', '又戴雲山吟', '又戴云山吟', '2b9b91a0-112e-429f-81e6-cdf1c869e7c2', '唐', '["戴雲山頂白雲齊，登頂方知世界低。","異草奇花人不識，一池分作九條溪。"]', '["戴云山頂白云齊，登頂方知世界低。","異草奇花人不識，一池分作九條溪。"]', '诗', 'shi', '', NULL, '又戴雲山吟 智亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb3a71a3-2c27-40d6-a58a-a0753f145b75', '荅盧鄴', '荅盧鄴', '32e599d0-4a87-4249-ba62-6e8d2c7219a6', '唐', '["風泉秪向夢中聞，身外無餘可寄君。","當戶一輪惟曉月，掛簷數片是秋雲。"]', '["风泉秪向梦中闻，身外無餘可寄君。","當戶一輪惟晓月，掛簷數片是秋云。"]', '诗', 'shi', '', NULL, '荅盧鄴 良乂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82af10b7-6438-40e8-b432-fe943c87a576', '山居八詠 一', '山居八詠 一', 'e02c661e-1d0a-4562-8ce9-558203ff0e79', '唐', '["身閑依祖寺，志僻性多慵。","少室遺真旨，層樓起暮鐘。","啜茶思好水，對月數諸峰。","有問山中趣，庭前是古松。"]', '["身闲依祖寺，志僻性多慵。","少室遺真旨，層楼起暮鐘。","啜茶思好水，对月數諸峰。","有问山中趣，庭前是古松。"]', '诗', 'shi', '', NULL, '山居八詠 一 常達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a6228ce-2dcc-4e4d-acc3-652b3a417bfa', '山居八詠 二', '山居八詠 二', 'e02c661e-1d0a-4562-8ce9-558203ff0e79', '唐', '["晚望虛庭物，心心見祖情。","煙開分嶽色，雨霧減泉聲。","遠樹猨長嘯，層巖日乍明。","更堪論的意，林下筍新生。"]', '["晚望虛庭物，心心见祖情。","煙开分嶽色，雨霧減泉声。","远樹猨长嘯，層巖日乍明。","更堪論的意，林下筍新生。"]', '诗', 'shi', '', NULL, '山居八詠 二 常達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d035016e-a397-40d8-8243-b6774dd6c4f3', '山居八詠 三', '山居八詠 三', 'e02c661e-1d0a-4562-8ce9-558203ff0e79', '唐', '["一室塵埃外，翛然祗麽常。","睡來開寢帳，鐘動下禪牀。","溪浸山光冷，秋凋木葉黃。","時提祖師意，欹石看斜陽。"]', '["一室塵埃外，翛然祗麽常。","睡来开寢帳，鐘动下禪牀。","溪浸山光冷，秋凋木葉黄。","时提祖師意，欹石看斜陽。"]', '诗', 'shi', '', NULL, '山居八詠 三 常達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33da39c-8c21-4279-9865-3ed9936c25f6', '山居八詠 四', '山居八詠 四', 'e02c661e-1d0a-4562-8ce9-558203ff0e79', '唐', '["西來真祖意，祗在見聞中。","寒雁一聲過，疎林幾葉空。","心閑憐水石，身老怯霜風。","爲報參玄者，山山月色同。"]', '["西来真祖意，祗在见闻中。","寒雁一声過，疎林幾葉空。","心闲怜水石，身老怯霜风。","爲報參玄者，山山月色同。"]', '诗', 'shi', '', NULL, '山居八詠 四 常達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1af19b68-1a4b-443d-bb19-b6a5bde4dd78', '山居八詠 五', '山居八詠 五', 'e02c661e-1d0a-4562-8ce9-558203ff0e79', '唐', '["真性寂無機，塵塵祖佛師。","日明庭砌暖，霜苦藥苗衰。","汲水和煙酌，栽松帶雪移。","好聽玄旨處，猨嘯嶺南枝。"]', '["真性寂無機，塵塵祖佛師。","日明庭砌暖，霜苦藥苗衰。","汲水和煙酌，栽松带雪移。","好听玄旨处，猨嘯嶺南枝。"]', '诗', 'shi', '', NULL, '山居八詠 五 常達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb5c14d-2f3c-4f4c-b66f-819ff4b2d23a', '山居八詠 六', '山居八詠 六', 'e02c661e-1d0a-4562-8ce9-558203ff0e79', '唐', '["古寺憑欄危，時聞舉妙機。","庭空月色淨，夜迥磬聲移。","漏轉寒更急，燈殘冷焰微。","太虛同萬象，相謂話玄微。"]', '["古寺憑欄危，时闻舉妙機。","庭空月色淨，夜迥磬声移。","漏轉寒更急，灯殘冷焰微。","太虛同万象，相謂話玄微。"]', '诗', 'shi', '', NULL, '山居八詠 六 常達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d85651-174e-4928-be49-1b426e7f324a', '山居八詠 七', '山居八詠 七', 'e02c661e-1d0a-4562-8ce9-558203ff0e79', '唐', '["胡僧論的旨，物物唱圓成。","疎柳春來翠，幽窗日漸明。","禪心清石室，蝶翅覆花英。","好聽談玄處，喬松鶴數聲。"]', '["胡僧論的旨，物物唱圓成。","疎柳春来翠，幽窗日漸明。","禪心清石室，蝶翅覆花英。","好听談玄处，喬松鹤數声。"]', '诗', 'shi', '', NULL, '山居八詠 七 常達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf25e8c0-10fb-4379-b9ed-6e91f43267c2', '山居八詠 八', '山居八詠 八', 'e02c661e-1d0a-4562-8ce9-558203ff0e79', '唐', '["祖祖唯心旨，春融日正長。","霜輕莎草綠，風細藥苗香。","月滿真如淨，花開覺樹芳。","庭前鶯囀處，時聽語圓常。"]', '["祖祖唯心旨，春融日正长。","霜轻莎草綠，风細藥苗香。","月满真如淨，花开覺樹芳。","庭前鶯囀处，时听語圓常。"]', '诗', 'shi', '', NULL, '山居八詠 八 常達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('015bfef1-49e4-4499-83a4-fe6b8cf37c0b', '苦熱行', '苦熱行', '37178ffa-7ac7-432f-8f44-c502e389c4b5', '唐', '["燭龍銜火飛天地，平陸無風海波沸。","彤雲疊疊聳奇峰，焰焰流光熱凝翠。","煙島摶鵬嚲雙翅，羲和赫怒強總轡。","飲流夸父斃長途，如見當中印王字。","明明夜西朝又東，古來有道仍再中。","扶桑老葉蔽不得，輝華直欲凌蒼空。","行人揮汗翻成雨，口燥喉乾嗌塵土。","西郊雲色晝冥冥，如何不救生靈苦。","何山怪木藏蛟龍，縮鱗卷鬣爲乖慵。","不發滂澤注天下，欲使風雷何所從。","旱苗原上枯成焰，嶽靈徒祝無神驗。","豪家簾外喚清風，水紋明角鋪長簟。","玉扇畫堂凝夜秋，歌豔繞梁催莫愁。","陽烏落盡酒不醒，扶上西園當月樓。","廢田暍死非吾屬，庫有黃金倉有粟。"]', '["燭龙銜火飞天地，平陸無风海波沸。","彤云叠叠聳奇峰，焰焰流光熱凝翠。","煙島摶鵬嚲雙翅，羲和赫怒強總轡。","饮流夸父斃长途，如见當中印王字。","明明夜西朝又东，古来有道仍再中。","扶桑老葉蔽不得，輝华直欲凌蒼空。","行人揮汗翻成雨，口燥喉乾嗌塵土。","西郊云色晝冥冥，如何不救生靈苦。","何山怪木藏蛟龙，縮鱗卷鬣爲乖慵。","不發滂澤注天下，欲使风雷何所從。","旱苗原上枯成焰，嶽靈徒祝無神驗。","豪家簾外喚清风，水紋明角鋪长簟。","玉扇畫堂凝夜秋，歌豔繞梁催莫愁。","陽烏落尽酒不醒，扶上西园當月楼。","廢田暍死非吾屬，庫有黄金倉有粟。"]', '诗', 'shi', '', NULL, '苦熱行 僧鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b2a314-64b6-4677-8048-d1a60c724884', '贈李粲秀才', '贈李粲秀才', '37178ffa-7ac7-432f-8f44-c502e389c4b5', '唐', '["隴西輝用真才子，搜奇探險無倫比。","筆下銛磨巨闕鋒，胸中靜灩西江水。","哀弦古樂清人耳，月露激寒哭秋鬼。","苔地無塵到曉吟，杉松老葉風乾起。","十軸示余三百篇，金碧爛光燒蜀牋。","雄芒逸氣測不得，使我躑躅成狂顛。","大郊遠闊空無邊，凝明淡綠收餘煙。","曠懷相對景何限，落日亂峰青倚天。","又驚大舶帆高懸，行濤劈浪凌飛仙。","回首瞥見五千仞，撲下香爐瀑布泉。","何事古人誇八斗，焉敢今朝定妍醜。","颯風驅雷暫不停，始向塲中稱大手。","駿如健鶻鶚與鵰，拏雲獵野翻重霄。","狐狸竄伏不敢動，却下雙鳴當迅飆。","愁如湘靈哭湘浦，咽咽哀音隔雲霧。","九嶷深翠轉巍峨，仙骨寒消不知處。","清同野客敲越甌，丁當急響涵清秋。","鸞雛相引叫未定，霜結夜闌仍在樓。","高若太空露雲物，片白激青皆彷彿。","仙鶴閑從淨碧飛，巨鼇頭戴蓬萊出。","前輩歌詩惟翰林，神仙老格何高深。","鞭馳造化繞筆轉，燦爛不爲酸苦吟。","夢乘明月清沈沈，飛到天台天姥岑。","傾湖湧海數百字，字字不朽長摐金。","此日多君可儔侶，堆珠疊璣滿玄圃。","終日並轡遊崑崙，十二樓中宴王母。"]', '["隴西輝用真才子，搜奇探險無倫比。","笔下銛磨巨闕鋒，胸中静灩西江水。","哀弦古乐清人耳，月露激寒哭秋鬼。","苔地無塵到晓吟，杉松老葉风乾起。","十軸示余三百篇，金碧爛光燒蜀牋。","雄芒逸氣測不得，使我躑躅成狂顛。","大郊远闊空無邊，凝明淡綠收餘煙。","曠懷相对景何限，落日亂峰青倚天。","又驚大舶帆高懸，行濤劈浪凌飞仙。","回首瞥见五千仞，撲下香爐瀑布泉。","何事古人誇八斗，焉敢今朝定妍醜。","颯风驱雷暫不停，始向塲中稱大手。","駿如健鶻鶚與鵰，拏云獵野翻重霄。","狐狸竄伏不敢动，却下雙鳴當迅飆。","愁如湘靈哭湘浦，咽咽哀音隔云霧。","九嶷深翠轉巍峨，仙骨寒消不知处。","清同野客敲越甌，丁當急响涵清秋。","鸾雛相引叫未定，霜結夜闌仍在楼。","高若太空露云物，片白激青皆彷彿。","仙鹤闲從淨碧飞，巨鼇头戴蓬萊出。","前輩歌诗惟翰林，神仙老格何高深。","鞭驰造化繞笔轉，燦爛不爲酸苦吟。","梦乘明月清沈沈，飞到天台天姥岑。","傾湖湧海數百字，字字不朽长摐金。","此日多君可儔侶，堆珠叠璣满玄圃。","終日並轡游崑崙，十二楼中宴王母。"]', '诗', 'shi', '', NULL, '贈李粲秀才 僧鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6ceb4b9-5559-43fa-8c86-f3e5dffcc54f', '和王季文題九華山', '和王季文題九华山', 'ecd87a30-fb52-43a5-9287-b08301151b48', '唐', '["衆岳雄分野，九華鎮南朝。","彩筆凝空遠，崔嵬寄青霄。","龍潭古仙府，靈藥今不凋。","瑩爲滄海鏡，煙霞作荒標。","造化心數奇，性狀精氣饒。","玉樹鬱玲瓏，天籟韻蕭寥。","寂寂尋乳竇，兢兢行石橋。","通泉漱雲母，藉草縈香苕。","我住幽且深，君賞昏復朝。","稀逢發清唱，片片霜凌飆。"]', '["衆岳雄分野，九华鎮南朝。","彩笔凝空远，崔嵬寄青霄。","龙潭古仙府，靈藥今不凋。","瑩爲滄海镜，煙霞作荒標。","造化心數奇，性狀精氣饒。","玉樹鬱玲瓏，天籟韻蕭寥。","寂寂尋乳竇，兢兢行石橋。","通泉漱云母，藉草縈香苕。","我住幽且深，君賞昏复朝。","稀逢發清唱，片片霜凌飆。"]', '诗', 'shi', '', NULL, '和王季文題九華山 神穎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21f3296c-bfbd-471c-bd8b-1b2316ea19e2', '宿嚴陵釣臺', '宿嚴陵釣台', 'ecd87a30-fb52-43a5-9287-b08301151b48', '唐', '["寒谷荒臺七里洲，賢人永逐水東流。","獨猿叫斷青天月，千古冥冥潭樹秋。"]', '["寒谷荒台七里洲，賢人永逐水东流。","独猿叫斷青天月，千古冥冥潭樹秋。"]', '诗', 'shi', '', NULL, '宿嚴陵釣臺 神穎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08921503-b709-494b-add8-12bafedf141c', '效古', '效古', '4c77cb0c-0cd2-4538-8466-6a600081bb21', '唐', '["榮辱又榮辱，一何翻與覆。","人生百歲中，孰肯死前足。","玄鬢忽如絲，青叢不再綠。","自古爭名徒，黃金是誰祿。"]', '["榮辱又榮辱，一何翻與覆。","人生百歲中，孰肯死前足。","玄鬢忽如絲，青叢不再綠。","自古爭名徒，黄金是誰祿。"]', '诗', 'shi', '', NULL, '效古 澹交 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99c53029-b8af-449e-9b67-630053e36683', '病後作', '病後作', '4c77cb0c-0cd2-4538-8466-6a600081bb21', '唐', '["未得忘身法，此身終未安。","病腸猶可洗，瘦骨不禁寒。","藥少心情餌，經無氣力看。","悠悠片雲質，獨對夕陽殘。"]', '["未得忘身法，此身終未安。","病腸猶可洗，瘦骨不禁寒。","藥少心情餌，經無氣力看。","悠悠片云質，独对夕陽殘。"]', '诗', 'shi', '', NULL, '病後作 澹交 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c16c60c-2206-4dcc-af22-a82767c13be2', '寫真', '寫真', '4c77cb0c-0cd2-4538-8466-6a600081bb21', '唐', '["圖形期自見，自見却傷神。","已是夢中夢，更逢身外身。","水花凝幻質，墨彩染空塵。","堪笑予兼爾，俱爲未了人。"]', '["圖形期自见，自见却傷神。","已是梦中梦，更逢身外身。","水花凝幻質，墨彩染空塵。","堪笑予兼爾，俱爲未了人。"]', '诗', 'shi', '', NULL, '寫真 澹交 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8094770c-24e2-4c91-af3f-32bae8ba718b', '端午', '端午', 'f9fd6299-65a4-4fa9-b78b-137dd995acb1', '唐', '["節分端午自誰言，萬古傳聞爲屈原。","堪笑楚江空渺渺，不能洗得直臣冤。"]', '["節分端午自誰言，万古傳闻爲屈原。","堪笑楚江空渺渺，不能洗得直臣冤。"]', '诗', 'shi', '', NULL, '端午 文秀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69404663-532a-4c1b-b80c-105738fb2db9', '謝友人見訪留詩', '謝友人见訪留诗', 'a86b4b46-3af9-4c55-ac00-095f5c41c8be', '唐', '["軒車誰肯到，泉石自相親。","暮雨凋殘寺，秋風悵望人。","庭新一片葉，衣故十年塵。","賴有瑤華贈，清吟愈病身。"]', '["軒车誰肯到，泉石自相親。","暮雨凋殘寺，秋风悵望人。","庭新一片葉，衣故十年塵。","賴有瑤华贈，清吟愈病身。"]', '诗', 'shi', '', NULL, '謝友人見訪留詩 懷楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f13fd8-83e3-45e6-94e6-d419f36ddbfe', '送新平故人', '送新平故人', 'a86b4b46-3af9-4c55-ac00-095f5c41c8be', '唐', '["常聽倉庚思舊友，又因蝴蝶夢生涯。","一千餘里河連郭，三十六峰寒到家。","陰島直分東虢雁，晴樓高入上陽鴉。","姜嫄廟北與君別，應笑薄寒悲落花。"]', '["常听倉庚思旧友，又因蝴蝶梦生涯。","一千餘里河連郭，三十六峰寒到家。","陰島直分东虢雁，晴楼高入上陽鴉。","姜嫄廟北與君別，應笑薄寒悲落花。"]', '诗', 'shi', '', NULL, '送新平故人 懷楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6a02f7-5c85-4314-8f6a-478f7d965b7a', '辭南平鍾王召', '辞南平鍾王召', 'dc76da9f-2d79-4b0b-8314-5776a4aaafeb', '唐', '["摧殘枯木倚寒林，幾度逢春不變心。","樵客見之猶不採，郢人何事苦搜尋。"]', '["摧殘枯木倚寒林，幾度逢春不变心。","樵客见之猶不採，郢人何事苦搜尋。"]', '诗', 'shi', '', NULL, '辭南平鍾王召 躭章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b48a8a83-7991-49f4-94b2-ecff5584984f', '短歌行', '短歌行', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["日月何忙忙，出沒住不得。","使我勇壯心，少年如頃刻。","人生石火光，通時少於塞。","四季倏往來，寒暑變爲賊。","偷人面上花，奪人頭上黑。"]', '["日月何忙忙，出沒住不得。","使我勇壯心，少年如頃刻。","人生石火光，通时少於塞。","四季倏往来，寒暑变爲賊。","偷人面上花，奪人头上黑。"]', '诗', 'shi', '', NULL, '短歌行 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('679a5329-7e1c-49e8-b550-d3765379af24', '飲馬長城窟', '饮马长城窟', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["游客長城下，飲馬長城窟。","馬嘶聞水腥，爲浸征人骨。","豈不是流泉，終不成潺湲。","洗盡骨上土，不洗骨中冤。","骨若比流水，四海有還魂。","空流嗚咽聲，聲中疑是言。"]', '["游客长城下，饮马长城窟。","马嘶闻水腥，爲浸征人骨。","豈不是流泉，終不成潺湲。","洗尽骨上土，不洗骨中冤。","骨若比流水，四海有還魂。","空流嗚咽声，声中疑是言。"]', '诗', 'shi', '', NULL, '飲馬長城窟 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68dcd1e9-0321-4e45-8ac4-fee2694683a7', '夜直', '夜直', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["大內隔重牆，多聞樂未央。","燈明宮樹色，茶煮禁泉香。","鳳輦通門靜，雞歌入漏長。","宴榮陪御席，話密近龍章。","吟步彤庭月，眠分玉暑涼。","欲粘朱紱重，頻草白麻忙。","筆力將羣吏，人情在致唐。","萬方瞻仰處，晨夕面吾皇。"]', '["大內隔重牆，多闻乐未央。","灯明宮樹色，茶煮禁泉香。","鳳輦通门静，雞歌入漏长。","宴榮陪御席，話密近龙章。","吟步彤庭月，眠分玉暑涼。","欲粘朱紱重，頻草白麻忙。","笔力將羣吏，人情在致唐。","万方瞻仰处，晨夕面吾皇。"]', '诗', 'shi', '', NULL, '夜直 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d68bae3-b35e-47fe-8835-b782c42cdc80', '贈行脚僧', '贈行脚僧', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["世界曾行遍，全無行可修。","炎涼三衲共，生死一身休。","片斷雲隨體，稀疎雪滿頭。","此門無所著，不肯暫淹留。"]', '["世界曾行遍，全無行可修。","炎涼三衲共，生死一身休。","片斷云隨體，稀疎雪满头。","此门無所著，不肯暫淹留。"]', '诗', 'shi', '', NULL, '贈行脚僧 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ed628a5-78b1-4eec-a10a-a31c84d8e927', '秋日思舊山', '秋日思旧山', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["咸言上國繁華，豈謂帝城羈旅。","十點五點殘螢，千聲萬聲秋雨。","白雲江上故鄉，月下風前吟處。","欲去不去遲遲，未展平生所佇。"]', '["咸言上国繁华，豈謂帝城羈旅。","十点五点殘螢，千声万声秋雨。","白云江上故乡，月下风前吟处。","欲去不去遲遲，未展平生所佇。"]', '诗', 'shi', '', NULL, '秋日思舊山 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f515b8a4-cdd6-485b-ac04-0a897e4e8db4', '寄乾陵楊侍郎', '寄乾陵楊侍郎', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["冷落官資不畏貧，司曹且共內官分。","步量野色成公案，點檢樵聲入奏聞。","陵廟路因朝去掃，御爐香每夜來焚。","碑寒樹古神門上，管得無窮空白雲。"]', '["冷落官資不畏貧，司曹且共內官分。","步量野色成公案，点檢樵声入奏闻。","陵廟路因朝去掃，御爐香每夜来焚。","碑寒樹古神门上，管得無窮空白云。"]', '诗', 'shi', '', NULL, '寄乾陵楊侍郎 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1380ea34-986c-4410-82b1-165f7a07a7e5', '登樓憶友', '登楼憶友', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["物象遠濛濛，周迴極望中。","帶煙千井樹，和磬一樓風。","月色寒沈地，波聲夜颺空。","登臨無限趣，恨不與君同。"]', '["物象远濛濛，周迴極望中。","带煙千井樹，和磬一楼风。","月色寒沈地，波声夜颺空。","登臨無限趣，恨不與君同。"]', '诗', 'shi', '', NULL, '登樓憶友 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6a784c-319a-4d75-aab7-0b7e6a68f7f9', '華嚴寺望樊川', '华嚴寺望樊川', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["萬木葉初紅，人家樹色中。","疎鐘搖雨脚，秋水浸雲容。","雪磧回寒鴈，村燈促夜舂。","舊山歸未得，生計欲何從。"]', '["万木葉初紅，人家樹色中。","疎鐘搖雨脚，秋水浸云容。","雪磧回寒鴈，村灯促夜舂。","旧山归未得，生計欲何從。"]', '诗', 'shi', '', NULL, '華嚴寺望樊川 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c7190c2-955c-4209-9734-5e6bd610663a', '與道侶同於水陸寺會宿', '與道侶同於水陸寺會宿', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["論道窮心少有朋，此時清話昔年曾。","柿凋紅葉鋪寒井，鵠墜霜毛著定僧。","風遰遠聲秋澗水，竹穿深色夜房燈。","出門盡是勞生者，只此長閑幾箇能。"]', '["論道窮心少有朋，此时清話昔年曾。","柿凋紅葉鋪寒井，鵠墜霜毛著定僧。","风遰远声秋澗水，竹穿深色夜房灯。","出门尽是勞生者，只此长闲幾箇能。"]', '诗', 'shi', '', NULL, '與道侶同於水陸寺會宿 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('045ed0b0-35b8-45ee-9275-b4fa51659c8b', '城上吟', '城上吟', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["古塚密於草，新墳侵官道。","城外無閑地，城中人又老。"]', '["古塚密於草，新墳侵官道。","城外無闲地，城中人又老。"]', '诗', 'shi', '', NULL, '城上吟 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68b9b6b-5e96-411e-8804-8943f8d2ae10', '襄陽曲', '襄陽曲', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["爲憶南遊人，移家大堤住。","千帆萬帆來，盡過門前去。"]', '["爲憶南游人，移家大堤住。","千帆万帆来，尽過门前去。"]', '诗', 'shi', '', NULL, '襄陽曲 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4daf63-3283-4120-b40d-bcd25d7bd807', '誡貪', '誡貪', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["多求待心足，未足旋傾覆。","明知貪者心，求榮不求辱。"]', '["多求待心足，未足旋傾覆。","明知貪者心，求榮不求辱。"]', '诗', 'shi', '', NULL, '誡貪 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e95281a-83b7-4762-9c68-d751e0befd79', '蟬二首 一', '蟬二首 一', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["獨蟬初唱古槐枝，委曲悲涼斷續遲。","雨後忽聞誰最苦，異鄉孤館憶家時。"]', '["独蟬初唱古槐枝，委曲悲涼斷續遲。","雨後忽闻誰最苦，異乡孤館憶家时。"]', '诗', 'shi', '', NULL, '蟬二首 一 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86bedc7f-6c4e-4e01-ad9b-0da991b9d29d', '蟬二首 二', '蟬二首 二', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["衰柳蟬吟旁濁河，正當殘日角聲和。","尋常不足少愁思，此際聞時愁更多。"]', '["衰柳蟬吟旁濁河，正當殘日角声和。","尋常不足少愁思，此際闻时愁更多。"]', '诗', 'shi', '', NULL, '蟬二首 二 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12d0306e-9266-438c-af72-21161bea05fb', '太平坊尋裴郎中故宅', '太平坊尋裴郎中故宅', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["不語淒涼無限情，荒堦行盡又重行。","昔年住此何人在，滿地槐花秋草生。"]', '["不語淒涼無限情，荒堦行尽又重行。","昔年住此何人在，满地槐花秋草生。"]', '诗', 'shi', '', NULL, '太平坊尋裴郎中故宅 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a315b5f-69f5-488e-a13d-ba2fd0b9e18d', '登樓', '登楼', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["邊邑鴻聲一例秋，大波平日遶山流。","故人千里同明月，盡夕無言空倚樓。"]', '["邊邑鴻声一例秋，大波平日遶山流。","故人千里同明月，尽夕無言空倚楼。"]', '诗', 'shi', '', NULL, '登樓 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('777d125c-03a2-4a15-9ae2-7f9754a267e1', '長安早秋', '长安早秋', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["風舞槐花落御溝，終南山色入城秋。","門門走馬徵兵急，公子笙歌醉玉樓。"]', '["风舞槐花落御溝，終南山色入城秋。","门门走马徵兵急，公子笙歌醉玉楼。"]', '诗', 'shi', '', NULL, '長安早秋 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff9cdef1-31fa-45ac-951f-07f62af10800', '對雪', '对雪', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["密密無聲墜碧空，霏霏有韻舞微風。","幽人吟望搜辭處，飄入窗來落硯中。"]', '["密密無声墜碧空，霏霏有韻舞微风。","幽人吟望搜辞处，飄入窗来落硯中。"]', '诗', 'shi', '', NULL, '對雪 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a11a829-508c-41c4-8486-820e78ea4b7a', '鸚鵡', '鸚鵡', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["翠毛丹觜乍教時，終日無寥似憶歸。","近來偷解人言語，亂向金籠說是非。"]', '["翠毛丹觜乍教时，終日無寥似憶归。","近来偷解人言語，亂向金籠说是非。"]', '诗', 'shi', '', NULL, '鸚鵡 子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a86d2a6-234b-465a-b109-c96b6c837e5a', '晚景', '晚景', 'b258ff3d-27a9-4cb2-a6ec-a8e819076eb7', '唐', '["池荷衰颯菊芬芳，策杖吟詩上草堂。","滿目暮雲風卷盡，郡樓寒角數聲長。"]', '["池荷衰颯菊芬芳，策杖吟诗上草堂。","满目暮云风卷尽，郡楼寒角數声长。"]', '诗', 'shi', '', NULL, '晚景 子蘭 shi');
